window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0234", [{"word":"population genetics","ipa_uk":"/ˌpɒpjʊˈleɪʃən dʒɪˈnetɪks/","ipa_us":"/ˌpɑːpjəˈleɪʃən dʒəˈnetɪks/","definition_zh":"群体遗传学；种群遗传学（研究种群内与种群间等位基因频率变化规律的遗传学分支）","definition_en":"the branch of genetics that studies how allele and genotype frequencies change within and between populations over time","core_image":"深夜实验室里，几十代果蝇的翅脉标本铺满长桌，研究员把每一代的性状比例换算成频率曲线","scene":"深夜的实验室里，研究员把几十代果蝇的翅脉记录摊在长桌上，想从整个群体的角度看清基因比例怎样一代代改变。Population genetics turns those breeding records into a map of shifting allele frequencies.","sceneCN":"这里指向这门学科本身（第 1 个义项：研究种群内遗传变异与等位基因频率变化的遗传学分支）；句意为群体遗传学把这些繁育记录变成一幅等位基因频率不断变动的地图。图中可辨识物件：培养瓶、翅脉标本、频率曲线、台灯。","pos":[{"tag":"n.","zh":"名词：不可数，指学科名称；作主语时谓语用单数"}],"collocations":[{"phrase":"population genetics theory","zh":"群体遗传学理论"},{"phrase":"population genetics model","zh":"群体遗传学模型"},{"phrase":"molecular population genetics","zh":"分子群体遗传学"},{"phrase":"population genetics of humans","zh":"人类群体遗传学"},{"phrase":"a course in population genetics","zh":"一门群体遗传学课程"},{"phrase":"population genetics approach","zh":"群体遗传学的研究路径"},{"phrase":"apply population genetics to conservation","zh":"把群体遗传学用于保护实践"}],"forms":[{"label":"学科名称","form":"population genetics"},{"label":"定语用法","form":"population genetics + 名词"},{"label":"介词短语","form":"in population genetics"},{"label":"复合修饰","form":"population-genetics methods"},{"label":"派生形容词","form":"population-genetic"},{"label":"分写变体","form":"population genetic analysis"}],"derivatives":[{"word":"population geneticist","pos":"n.","zh":"由学科名加表示「从业者」的词尾构成，义为「群体遗传学家」"},{"word":"population-genetic","pos":"adj.","zh":"由学科名转作定语形容词，义为「群体遗传层面的」"},{"word":"population genomics","pos":"n.","zh":"由 population 与 genomics 组合而成，义为「种群基因组学」，研究全基因组尺度的群体变异"},{"word":"population structure","pos":"n.","zh":"同一学科框架下的核心概念，义为「种群结构」，指群体内与群体间的遗传分化格局"},{"word":"population bottleneck","pos":"n.","zh":"同一框架下的概念，义为「种群瓶颈」，指群体规模骤然缩小导致遗传多样性下降"}],"senses":[{"no":"01","title":"The discipline itself","titleCN":"学科本身","definition":"the branch of genetics that studies the frequencies of alleles and genotypes in groups of interbreeding organisms","definitionCN":"研究互交群体中各类等位基因与基因型出现频率的遗传学分支","example":"Population genetics explains why some variants are common in one region and rare in another.","exampleCN":"群体遗传学解释了为什么某些变异在一个地区常见、在另一个地区罕见。","why":"The name simply joins the object of study, the population, to the tool, genetics; the discipline exists because inheritance has to be counted across many individuals, not just traced in one family.","whyCN":"名称只是把研究对象「群体」与工具「遗传学」拼在一起；这门学科之所以成立，是因为遗传必须在上千个体中计数，而不能只在一个家系里追踪。"},{"no":"02","title":"Allele frequency as the central measure","titleCN":"以等位基因频率为核心量","definition":"the proportion of each allele at a locus within a population, the quantity the field tracks over generations","definitionCN":"某一基因座上每种等位基因在群体中所占的比例，也是本学科跨世代追踪的核心量","example":"Population genetics detected a shift in allele frequency across two seasons, which showed that selection was acting.","exampleCN":"等位基因频率在两个季节间发生偏移，说明选择压力正在起作用。","why":"Individuals carry genotypes, but only frequencies can be summed over a group; making the frequency the unit of analysis is what turns heredity into a measurable population process.","whyCN":"个体携带的是基因型，但只有频率能在群体层面相加；把频率当作分析单位，才使遗传成为可测量的群体过程。"},{"no":"03","title":"Mathematical modelling tradition","titleCN":"数学建模传统","definition":"the tradition of building equations for selection, drift, mutation and migration, founded by Fisher, Haldane and Wright","definitionCN":"为选择、漂变、突变与迁移建立方程的传统，由费希尔、霍尔丹与赖特奠基","example":"A simple population genetics model showed that even weak selection could fix an allele in a few hundred generations.","exampleCN":"一个简单模型显示，即使很弱的选择压力也能在数百代内使某个等位基因固定下来。","why":"Field counts alone cannot separate several forces acting at once; equations let researchers ask what would happen if only one force were at work.","whyCN":"野外的计数无法同时拆开几种力量的作用；方程让人可以追问「若只有一种力量在起作用会怎样」。"},{"no":"04","title":"Division of labour with molecular genetics","titleCN":"与分子遗传学的分工","definition":"the subfield that works with frequencies in groups rather than with the molecular machinery of a single genome","definitionCN":"处理群体中的频率、而非单个基因组的分子机制的子领域","example":"Molecular genetics read the sequence, while population genetics asked how often that sequence appears.","exampleCN":"分子遗传学读取序列，群体遗传学则追问这段序列出现的频率有多高。","why":"The same data can be read at two scales: the molecule explains mechanism, the population explains distribution, and the field defines itself by the second question.","whyCN":"同一批数据可以在两个尺度上读：分子层面解释机制，群体层面解释分布，本学科正是以第二个问题界定自己。"},{"no":"05","title":"Conservation and ecology","titleCN":"保护生物学与生态学应用","definition":"the use of frequency models to estimate genetic diversity, inbreeding and viability in threatened species","definitionCN":"用频率模型估计受威胁物种的遗传多样性、近交程度与存续能力","example":"Conservation managers used population genetics to decide which herds could be safely mixed.","exampleCN":"保护管理者用群体遗传学判断哪些兽群可以安全地混群。","why":"Small isolated groups lose variants fast; counting those variants is the only way to tell whether a reserve is holding a viable gene pool.","whyCN":"小而隔离的群体丢失变异很快；只有把这些变异数清楚，才能判断保护区是否守住了可存续的基因库。"},{"no":"06","title":"Plant and animal breeding","titleCN":"动植物育种","definition":"the application of frequency and selection models to predict genetic gain in breeding programmes","definitionCN":"把频率与选择模型用于预测育种计划中的遗传增益","example":"Breeders rely on population genetics to predict how fast a trait will improve.","exampleCN":"育种者依靠群体遗传学预测某个性状改良得有多快。","why":"Breeding is selection made deliberate; the same equations that describe natural selection can forecast the response of a herd or a crop.","whyCN":"育种是把选择变成有意为之；描述自然选择的同一套方程，可以预测畜群或作物的改良反应。"},{"no":"07","title":"Medical and epidemiological use","titleCN":"医学与流行病学用途","definition":"the study of variant frequencies across human groups to interpret disease risk and ancestry","definitionCN":"研究不同人群中的变异频率，用以解释疾病风险与祖源","example":"Population genetics showed that the protective variant is far more common in one continent.","exampleCN":"群体遗传学显示，这种具有保护作用的变异在某个大陆要常见得多。","why":"A risk variant may look important in one clinic and be common everywhere; only a frequency comparison across groups can tell whether it is truly rare.","whyCN":"某个风险变异在一家诊所里可能显得重要，却可能到处都常见；只有跨群体比较频率，才能判断它是否真的罕见。"},{"no":"08","title":"A teaching subject and research toolkit","titleCN":"作为课程与研究工具","definition":"a standard course and a set of sampling and statistical methods taught across biology degrees","definitionCN":"一门标准课程，也是一套在生物学各学位中教授的采样与统计方法","example":"The seminar introduced population genetics through sampling exercises and frequency tables.","exampleCN":"研讨课通过采样练习与频率表来介绍群体遗传学。","why":"The field is defined as much by its methods as by its findings, so it is taught as a toolkit before it is taught as a body of results.","whyCN":"这门学科既由发现界定，也由方法界定，因此教学上先教工具、再教结论。"},{"no":"09","title":"Relation to population genomics","titleCN":"与种群基因组学的关系","definition":"the classical frequency framework that population genomics extends to thousands of loci at once","definitionCN":"经典频率框架，而种群基因组学把它扩展到同时分析成千上万个位点","example":"Population genetics supplied the theory that population genomics later scaled up to whole genomes.","exampleCN":"群体遗传学提供了理论，种群基因组学后来把它扩展到全基因组。","why":"More markers do not change the questions; they sharpen the estimates, so the newer field inherits its logic from the older one.","whyCN":"更多标记并不改变问题，只是让估计更精细；新领域因此继承了旧领域的逻辑。"}],"etymology":{"intro":{"en":"The phrase is built from an English noun of Latin origin, a Greek-derived technical term coined in the early twentieth century, and the plural marker of the discipline name. Each part is transparent, but the exact moment when the two words were first printed together is not recorded.","cn":"这个短语由拉丁语来源的英语名词、二十世纪初以希腊语词根造出的术语以及学科名的复数词尾构成。各部分含义清楚，但两个词最初印在一起的准确时刻并无记录。"},"items":[{"era":"LATIN POPULUS","en":"Populus meant a people or a community; populatio, from populari, to lay waste or to populate, gave English the noun population, first used of inhabitants and later of any interbreeding group.","cn":"这个词指人民或共同体的成员；由表示「使有人居住」的动词派生的名词进入英语后先指居民，后来才指任何互交繁育的群体。"},{"era":"GREEK GENESIS","en":"Genesis meant origin or coming into being; from it came genetikos, concerned with generation, the root behind the modern vocabulary of heredity.","cn":"这个词意为起源、生成；由它派生的形容词表示「与生育、发生有关的」，成为现代遗传词汇的词根。"},{"era":"ENGLISH GENETICS, 1905","en":"William Bateson coined genetics for the study of heredity and variation, deliberately choosing a Greek root rather than an existing Latin one.","cn":"贝特森为研究遗传与变异的学问造出这个术语，特意选用希腊词根而非现成的拉丁词根。"},{"era":"THE MODERN SYNTHESIS, 1930S","en":"Fisher, Haldane and Wright showed that selection, drift and migration could be written as frequency equations, and the phrase population genetics came into use for that programme.","cn":"费希尔、霍尔丹与赖特证明选择、漂变与迁移都能写成频率方程，这个短语随之成为该研究纲领的名称。"},{"era":"GENOMIC EXTENSION","en":"From the 1990s the same framework was applied to thousands of markers at once, and population genomics was named as its large-scale successor.","cn":"自一九九零年代起，同一框架被用于同时分析成千上万个标记，并以其大规模后继者的名义命名了新领域。"},{"era":"TERM DATING","en":"The compound itself appears in print in the second quarter of the twentieth century; the precise first attestation is uncertain, while the origin of each component is not in doubt.","cn":"这一复合词在二十世纪第二个二十五年间见于印刷品；其确切首见年代不确定，但各成分的来源并无争议。"}]},"similar":{"note":{"en":"The first group shares wording or the same technical root; the second group names neighbouring branches that ask related but distinct questions.","cn":"第一组共享字面或同一个术语词根；第二组是相邻分支，问题相关但各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"population genomics","ipa":"/ˌpɒpjʊˈleɪʃən dʒəˈnəʊmɪks/","tag":"near form","definition":"The study of variation across thousands of loci in a population, an extension of the classical framework.","definitionCN":"研究群体中成千上万个位点的变异，是经典框架的扩展。"},{"word":"population ecology","ipa":"/ˌpɒpjʊˈleɪʃən iˈkɒlədʒi/","tag":"same head noun","definition":"The study of how populations grow, interact and are limited by their environment.","definitionCN":"研究种群如何增长、相互作用并受环境限制。"},{"word":"genetics","ipa":"/dʒɪˈnetɪks/","tag":"root word","definition":"The broad study of heredity and variation.","definitionCN":"研究遗传与变异的广义学科。"},{"word":"gene pool","ipa":"/ˈdʒiːn puːl/","tag":"same field","definition":"The total stock of alleles carried by a population.","definitionCN":"一个群体所携带的全部等位基因总和。"},{"word":"population structure","ipa":"/ˌpɒpjʊˈleɪʃən ˈstrʌktʃə/","tag":"same field","definition":"The pattern of genetic differences among subpopulations of one species.","definitionCN":"同一物种各亚群体之间遗传差异的格局。"}]},{"heading":"NEAR MEANING","entries":[{"word":"evolutionary genetics","ipa":"/ˌiːvəˈluːʃənəri dʒɪˈnetɪks/","tag":"near meaning","definition":"Genetics applied to the causes of evolutionary change, of which population genetics is the quantitative core.","definitionCN":"把遗传学用于解释演化变化的原因，群体遗传学是其定量核心。"},{"word":"ecological genetics","ipa":"/ˌiːkəˈlɒdʒɪkəl dʒɪˈnetɪks/","tag":"near meaning","definition":"The study of genetic variation in natural populations with an emphasis on adaptation to habitat.","definitionCN":"研究自然群体中的遗传变异，侧重对栖息地的适应。"},{"word":"quantitative genetics","ipa":"/ˈkwɒntɪtətɪv dʒɪˈnetɪks/","tag":"near meaning","definition":"The genetics of continuously varying traits, using statistical rather than single-locus models.","definitionCN":"研究连续变异性状的遗传学，用统计模型而非单位点模型。"},{"word":"conservation genetics","ipa":"/ˌkɒnsəˈveɪʃən dʒɪˈnetɪks/","tag":"near meaning","definition":"The applied field that uses population principles to protect endangered species.","definitionCN":"运用群体原理保护濒危物种的应用领域。"},{"word":"population biology","ipa":"/ˌpɒpjʊˈleɪʃən baɪˈɒlədʒi/","tag":"near meaning","definition":"The wider study of populations, including ecology, genetics and demography.","definitionCN":"更宽泛的群体研究，涵盖生态、遗传与人口统计。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations chain the object of study, the central measure, and the applied uses; the abstract ones reduce the field to the arithmetic of inheritance.","cn":"正常联想串起研究对象、核心量与各项应用；抽象联想把整门学科化简为遗传的算术。"},"normal":[{"en":"Population is the object: a group of interbreeding individuals, not a single family.","cn":"群体是研究对象：一群互交繁育的个体，而不是一个家系。"},{"en":"Genetics is the tool: the same laws of inheritance, now counted instead of traced.","cn":"遗传学是工具：同样的遗传规律，从追踪改为计数。"},{"en":"Allele frequency is the measure that makes the group visible to statistics.","cn":"等位基因频率是让群体变得可统计的那个量。"},{"en":"The equations of Fisher, Haldane and Wright are the field's native language.","cn":"费希尔、霍尔丹与赖特的方程是这门学科的母语。"},{"en":"Conservation, breeding and medicine are the three places the equations are put to work.","cn":"保护、育种与医学是这些方程投入实际工作的三个场所。"}],"abstract":[{"en":"A population is an abacus: every individual is a bead, and the field counts which beads are alike.","cn":"群体是一把算盘：每个个体都是一颗珠子，学科数的是哪些珠子相同。"},{"en":"Inheritance stops being a family tree and becomes a ledger of proportions.","cn":"遗传不再是家谱，而变成一本比例账簿。"},{"en":"The field asks not who your ancestors were but how often your variant occurs.","cn":"这门学科问的不是你的祖先是谁，而是你的变异出现得有多频繁。"}]},"examples":[{"en":"Population genetics predicts that small isolated groups lose variation quickly.","cn":"群体遗传学预测，小而隔离的群体很快会丢失变异。"},{"en":"She applied population genetics to decide how to mix the two captive herds.","cn":"她运用群体遗传学来决定如何把两个圈养兽群混群。"},{"en":"A course in population genetics usually begins with allele frequency tables.","cn":"群体遗传学课程通常从等位基因频率表讲起。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「泡普雷申 基因题克斯」——把一大群人（population）的基因当成一道统计题（genetics）：群体遗传学","word":"population genetics"},"root":"第一个成分来自拉丁语 populus「人民」，经表示「使有人居住」的动词派生出英语「群体、人口」；第二个成分由希腊语 genesis「起源、生成」派生的形容词经德语进入英语，一九零五年由贝特森定名为遗传学。整个短语的确切首见年代不确定，但两个成分的来源清楚。","sensesIntro":{"en":"Nine senses divide into four layers: the discipline's definition, its two core instruments, its neighbours, and its applications.","cn":"九个义项分四层：学科定义、两件核心工具、与相邻学科的分工，以及各项应用。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bench of fruit-fly records, every generation reduced to a table of proportions.","cn":"核心意象：一桌果蝇记录，每一代都被化约成一张比例表。"},"chain":["A GROUP, NOT A FAMILY","ALLELE FREQUENCIES","EQUATIONS OF CHANGE","NEIGHBOURING BRANCHES","APPLIED USES","GENOMIC SCALE"],"branches":[{"senses":"01","en":"THE DEFINITION: the field is named for its object and its tool, and its first sense is simply that pairing.","cn":"定义本身：学科以研究对象与工具命名，第一个义项就是这一配对。"},{"senses":"02 · 03","en":"THE INSTRUMENTS: frequency is the measure, equations are the language, and together they turn heredity into a population process.","cn":"两件工具：频率是量，方程是语言，合起来把遗传变成群体过程。"},{"senses":"04 · 09","en":"THE BOUNDARIES: molecular genetics reads mechanism, population genomics reads scale, and the classical field sits between them.","cn":"学科边界：分子遗传学读机制，种群基因组学读规模，经典学科居于两者之间。"},{"senses":"05 · 06 · 07","en":"THE APPLICATIONS: conservation, breeding and medicine each borrow the frequency model for a practical decision.","cn":"三类应用：保护、育种与医学各自借用频率模型做实际决策。"},{"senses":"08","en":"THE CLASSROOM: the field is also taught as a toolkit of sampling and tables before it is taught as results.","cn":"课堂形态：这门学科在讲结论之前，先作为采样与制表的工具被教授。"}]},"affixes":{"intro":{"en":"The term is a compound of an English noun with Latin ancestry and a Greek-derived technical word; its parts say object plus instrument, nothing more.","cn":"这个术语由一个有拉丁渊源英语名词与一个希腊词根术语复合而成；各部件只说明「对象加工具」。"},"latinIntro":{"en":"Latin supplies the word for a people and the noun of inhabiting; Greek supplies the root for origin and generation, which English turned into the name of a science.","cn":"拉丁语提供了「人民」与「居住」的名词；希腊语提供了「起源、生成」的词根，英语据此造出学科名。"},"items":[{"word":"populus","structure":"Latin noun","meaning":"a people, a community","meaningCN":"人民；共同体","example":"The word named the body of citizens before it named any breeding group.","exampleCN":"这个词先指公民整体，后来才指任何繁育群体。"},{"word":"populatio","structure":"Latin noun","meaning":"inhabiting; a populated body","meaningCN":"居住；有人口的整体","example":"It gave English the noun population.","exampleCN":"它给英语提供了「群体、人口」这一名词。"},{"word":"-ation","structure":"Latin noun ending","meaning":"action or result","meaningCN":"动作或结果","example":"It turns the verb of inhabiting into a noun of state.","exampleCN":"它把表示居住的动词变成状态名词。"},{"word":"genesis","structure":"Greek noun","meaning":"origin, coming into being","meaningCN":"起源；生成","example":"The root names the beginning of a new organism or form.","exampleCN":"这个词根指新个体或新形态的开端。"},{"word":"genetikos","structure":"Greek adjective","meaning":"concerned with generation","meaningCN":"与生育、发生有关的","example":"It is the direct source of the English adjective genetic.","exampleCN":"它是英语形容词的直接来源。"},{"word":"gene","structure":"English noun, 1909","meaning":"the unit of heredity","meaningCN":"遗传单位","example":"Johannsen shortened the Greek root into a word for the unit itself.","exampleCN":"约翰森把希腊词根缩短，造出指遗传单位的词。"},{"word":"-ics","structure":"Greek-derived suffix","meaning":"a field of study","meaningCN":"学科领域","example":"It turns the adjective into the name of a discipline.","exampleCN":"它把形容词变成学科名称。"},{"word":"population","structure":"English noun","meaning":"a group of interbreeding organisms","meaningCN":"互交繁育的生物群体","example":"In biology the word narrows from inhabitants to a breeding unit.","exampleCN":"在生物学中，这个词从「居民」窄化为「繁育单位」。"},{"word":"genetics","structure":"English noun","meaning":"the study of heredity and variation","meaningCN":"研究遗传与变异的学科","example":"The name was coined in 1905 and covers all scales of inheritance.","exampleCN":"该名称造于一九零五年，涵盖各尺度的遗传研究。"}],"latinEntries":[{"word":"populus","structure":"Latin noun","meaning":"people","meaningCN":"人民"},{"word":"populatio","structure":"Latin noun","meaning":"populated body","meaningCN":"有人口的整体"},{"word":"genesis","structure":"Greek noun","meaning":"origin","meaningCN":"起源"},{"word":"genetikos","structure":"Greek adjective","meaning":"of generation","meaningCN":"与生育有关的"}],"derivatives":[{"word":"population geneticist","pos":"n.","zh":"由学科名加表示「从业者」的词尾构成，义为「群体遗传学家」"},{"word":"population-genetic","pos":"adj.","zh":"由学科名转作定语形容词，义为「群体遗传层面的」"},{"word":"population genomics","pos":"n.","zh":"由 population 与 genomics 组合而成，义为「种群基因组学」，研究全基因组尺度的群体变异"},{"word":"population structure","pos":"n.","zh":"同一学科框架下的核心概念，义为「种群结构」，指群体内与群体间的遗传分化格局"},{"word":"population bottleneck","pos":"n.","zh":"同一框架下的概念，义为「种群瓶颈」，指群体规模骤然缩小导致遗传多样性下降"}]}},{"word":"genetic drift","ipa_uk":"/dʒɪˈnetɪk drɪft/","ipa_us":"/dʒəˈnetɪk drɪft/","definition_zh":"遗传漂变；基因漂变（小种群中由抽样误差引起的等位基因频率随机波动）","definition_en":"random change in allele frequencies from one generation to the next because only a sample of individuals reproduces","core_image":"一口被岩石围住的小水塘里，几十条鱼各自带着不同的斑纹，几代之后某些斑纹再也找不到","scene":"山谷里那口被岩石围住的小水塘只剩几十条鱼，研究者发现一种并不带来优势的斑纹在几代之内就再也找不到了。In a small isolated pond, genetic drift removed a neutral colour variant within a few generations.","sceneCN":"这里指随机漂变这一机制（第 1 个义项：小种群中因抽样误差而发生的等位基因频率随机变动）；句意为在一个小而隔离的池塘里，漂变在几代之内就让一个中性色斑变异消失了。图中可辨识物件：水塘、鱼群、斑纹、岩石围岸。","pos":[{"tag":"n.","zh":"名词短语：不可数，指一种演化机制；可加定冠词或修饰语"}],"collocations":[{"phrase":"random genetic drift","zh":"随机遗传漂变"},{"phrase":"genetic drift in small populations","zh":"小种群中的遗传漂变"},{"phrase":"the role of genetic drift","zh":"遗传漂变的作用"},{"phrase":"drift and selection","zh":"漂变与选择"},{"phrase":"drift load","zh":"漂变负荷"},{"phrase":"counteract genetic drift","zh":"抵消遗传漂变"},{"phrase":"drift dominates","zh":"漂变占主导"}],"forms":[{"label":"术语原形","form":"genetic drift"},{"label":"定冠词用法","form":"the genetic drift"},{"label":"形容词修饰","form":"random genetic drift"},{"label":"介词短语","form":"by genetic drift"},{"label":"复合定语","form":"genetic-drift models"},{"label":"相关动词搭配","form":"genetic drift acts on"}],"derivatives":[{"word":"drift","pos":"n./v.","zh":"同一词根独立成词，义为「漂移；漂流」，在遗传学中引申为频率的随机游走"},{"word":"drift","pos":"n.","zh":"由动词转作名词，义为「缓慢的移动；趋势」，是本短语的中心词"},{"word":"drifting","pos":"adj.","zh":"由中心词加进行式词尾构成，义为「漂移的；漂流的」"},{"word":"driftwood","pos":"n.","zh":"由中心词与「木材」复合，义为「浮木」，字面即被水推着走的木头"},{"word":"drift net","pos":"n.","zh":"由中心词与「网」复合，义为「流网」，指随水流漂移的渔网"}],"senses":[{"no":"01","title":"The mechanism itself","titleCN":"机制本身","definition":"random fluctuation of allele frequencies caused by the sampling of gametes in each generation","definitionCN":"每一代配子抽样所造成的等位基因频率随机波动","example":"Genetic drift can change a neutral variant's frequency without any change in fitness.","exampleCN":"遗传漂变可以在适应度毫无变化的情况下改变一个中性变异的频率。","why":"Not every individual reproduces, so each generation inherits a sample rather than the whole pool; sampling always wobbles, and the wobble is the mechanism.","whyCN":"并非每个个体都留下后代，因此每一代继承的只是一个样本而非全部基因库；抽样必然抖动，这种抖动就是机制本身。"},{"no":"02","title":"Sampling error, not fitness","titleCN":"抽样误差而非适应度","definition":"the statistical error that arises because a finite number of offspring is drawn from a larger pool","definitionCN":"从较大基因库中只抽取有限数量后代时产生的统计误差","example":"The allele spread through genetic drift, by sampling error rather than because it helped its carriers.","exampleCN":"这个等位基因扩散开来是抽样误差所致，而不是因为它对携带者有利。","why":"In a finite population the next generation is a random draw; any draw can depart from the parental proportions, and the departure needs no advantage.","whyCN":"在有限群体中，下一代是一次随机抽取；任何一次抽取都可能偏离亲代比例，而这种偏离并不需要任何优势。"},{"no":"03","title":"Stronger in small populations","titleCN":"在小种群中更强","definition":"the smaller the effective number of breeders, the larger the random swings in frequency","definitionCN":"参与繁殖的有效个体越少，频率的随机摆幅就越大","example":"Genetic drift in a handful of survivors can shift frequencies far more than a thousand breeders could.","exampleCN":"少数幸存者能造成的频率偏移，远比上千个繁殖个体所能造成的更大。","why":"With few draws the law of large numbers stops protecting the population, so chance alone can push a variant to a high frequency.","whyCN":"抽取次数很少时，大数定律不再保护群体，单靠偶然就能把某个变异推到很高的频率。"},{"no":"04","title":"Contrast with natural selection","titleCN":"与自然选择的对比","definition":"change that is random with respect to fitness, unlike selection, which is directed by reproductive advantage","definitionCN":"相对于适应度而言是随机的变化，不同于由繁殖优势定向的选择","example":"Selection favours the faster fish, while genetic drift ignores speed altogether.","exampleCN":"选择偏爱游得更快的鱼，漂变则完全不看速度。","why":"Selection has a criterion; drift has none, so the two forces can push the same allele in opposite directions.","whyCN":"选择有标准，漂变没有标准，因此两种力量可以把同一个等位基因推向相反方向。"},{"no":"05","title":"Contrast with gene flow","titleCN":"与基因流的对比","definition":"loss or fixation within a closed group, whereas gene flow brings alleles in from outside","definitionCN":"在封闭群体内部的丢失或固定，而基因流从外部把等位基因带进来","example":"The island lost variation through genetic drift because no migrants reached it.","exampleCN":"这座岛因为从未有迁入者到达，变异在漂变中流失。","why":"Drift reshuffles a closed gene pool; migration reopens it, so the two mechanisms pull diversity in opposite directions.","whyCN":"漂变在一个封闭基因库里重新洗牌；迁移把它重新打开，两种机制因此把多样性往相反方向拉。"},{"no":"06","title":"Fixation and loss","titleCN":"固定与丢失","definition":"the end points of drift, where one allele reaches a frequency of one and all others reach zero","definitionCN":"漂变的两个终点：某个等位基因频率达到一，其他等位基因频率降到零","example":"After several bottlenecks, genetic drift fixed the rare allele in the whole herd.","exampleCN":"经历数次瓶颈之后，那个稀有等位基因在整个兽群中被固定下来。","why":"A random walk in a bounded interval must eventually hit a boundary; in genetics the boundaries are one hundred percent and zero.","whyCN":"有界区间内的随机游走终究会撞到边界；在遗传学里，边界就是一成与零。"},{"no":"07","title":"Population bottlenecks","titleCN":"种群瓶颈","definition":"a sharp temporary reduction in population size that lets drift erase much of the standing variation","definitionCN":"种群规模的骤然暂时缩减，使漂变抹去大量既有变异","example":"A bottleneck during the drought let genetic drift cut the colony's diversity by half.","exampleCN":"干旱期间的瓶颈使这个群体的多样性减少了一半。","why":"A crash keeps only a small sample of the old gene pool, and the survivors' proportions become the new baseline.","whyCN":"崩溃只留下旧基因库的一小份样本，而幸存者的比例就成了新的基准。"},{"no":"08","title":"The founder effect","titleCN":"奠基者效应","definition":"drift in a small group that leaves a parent population and carries only a fraction of its variation","definitionCN":"一小群个体离开母群体时只带走一部分变异，由此产生的漂变","example":"Through the founder effect, genetic drift left the new colony with an allele absent from the mainland.","exampleCN":"奠基者效应使新群体带有一个大陆群体根本没有的等位基因。","why":"A founding group is a sample taken once, so its quirks are frozen into the new population before drift even starts.","whyCN":"奠基群体是一次性抽取的样本，它的偶然特征在漂变开始之前就已被冻结进新群体。"},{"no":"09","title":"Effective population size","titleCN":"有效种群规模","definition":"the number of individuals that actually contribute genes, which is usually far below the census count","definitionCN":"真正贡献基因的个体数目，通常远低于清点得到的个体数","example":"The effective population size was a tenth of the head count, so genetic drift acted far faster than expected.","exampleCN":"有效种群规模只有清点头数的十分之一，因此漂变起作用的速度远超预期。","why":"Only breeders pass genes on, and unequal family sizes shrink the effective number further, so census size overstates the buffer against drift.","whyCN":"只有繁殖者传递基因，而各家庭规模不均又进一步压低有效数目，所以清点规模会高估抵御漂变的缓冲。"}],"etymology":{"intro":{"en":"The phrase joins a Greek-derived technical adjective with an Old English noun of motion. The adjective dates from the naming of genetics in 1905; the noun's shift from physical drifting to statistical wandering happened in the twentieth century.","cn":"这个短语由希腊词根的技术形容词与一个古英语动作名词组成。形容词随一九零五年遗传学的命名而定型；名词从物理漂移转向统计意义上的游走，则发生在二十世纪。"},"items":[{"era":"GREEK GENESIS","en":"Genetikos meant concerned with generation, from genesis, origin; English genetics was coined from this root in 1905.","cn":"这个希腊形容词表示「与生育、发生有关的」，源于表示「起源」的名词；英语的遗传学之名即由此在一九零五年造出。"},{"era":"OLD ENGLISH DRIFAN","en":"Drifan meant to drive or to push; the noun drift described the slow movement of a boat or of snow heaped by wind.","cn":"这个古英语动词意为驱动、推动；其名词形式先指船只的缓慢移动或被风堆积的雪。"},{"era":"DRIFT AS A NOUN","en":"By the fourteenth century drift covered anything carried along without steering, including cloud, sand and ships.","cn":"到十四世纪，这个词已涵盖一切无人操舵而被动带走之物，包括云、沙与船。"},{"era":"WRIGHT AND THE STATISTICAL SENSE","en":"Sewall Wright described evolution by random drift in the late 1920s and 1930s, giving the old word a statistical meaning.","cn":"赖特在二十世纪二十年代末至三十年代描述了由随机漂变推动的演化，使这个旧词获得了统计含义。"},{"era":"MODERN PHRASE","en":"The fixed phrase genetic drift spread in the middle of the twentieth century; its exact first appearance is not dated with certainty.","cn":"这个固定短语在二十世纪中叶流行开来；其确切首见时间并无确定记录。"}]},"similar":{"note":{"en":"The first group is built on the same noun or the same field; the second group names other forces that move allele frequencies.","cn":"第一组共享同一个中心词或同一领域；第二组是推动等位基因频率的其他力量。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"drift","ipa":"/drɪft/","tag":"root word","definition":"The noun behind the phrase, meaning slow unsteered movement.","definitionCN":"短语背后的名词，义为缓慢且无人操控的移动。"},{"word":"genetic drift theory","ipa":"/dʒɪˈnetɪk drɪft ˈθɪəri/","tag":"near form","definition":"The body of models describing random frequency change.","definitionCN":"描述频率随机变动的一套模型。"},{"word":"drift load","ipa":"/drɪft ləʊd/","tag":"same field","definition":"The loss of fitness caused by the accumulation of harmful variants through drift.","definitionCN":"因漂变累积有害变异而造成的适应度损失。"},{"word":"drift barrier","ipa":"/drɪft ˈbæriə/","tag":"same field","definition":"The population size below which drift overwhelms weak selection.","definitionCN":"漂变压过弱选择时的种群规模界限。"},{"word":"gene drift","ipa":"/dʒiːn drɪft/","tag":"older variant","definition":"An older looser wording for the same mechanism.","definitionCN":"同一机制的较早、较宽松说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"natural selection","ipa":"/ˈnætʃərəl sɪˈlekʃən/","tag":"near meaning","definition":"Directed change in allele frequencies caused by differences in survival and reproduction.","definitionCN":"由生存与繁殖差异造成的、有方向性的等位基因频率变化。"},{"word":"gene flow","ipa":"/dʒiːn fləʊ/","tag":"near meaning","definition":"Movement of alleles between populations through migration or dispersal.","definitionCN":"通过迁移或扩散在群体之间发生的等位基因流动。"},{"word":"founder effect","ipa":"/ˈfaʊndə ɪˈfekt/","tag":"near meaning","definition":"A special case of drift set off by a small founding group.","definitionCN":"由小型奠基群体引发的一种特殊漂变。"},{"word":"bottleneck effect","ipa":"/ˈbɒtlnek ɪˈfekt/","tag":"near meaning","definition":"A special case of drift set off by a sharp population crash.","definitionCN":"由种群骤减引发的一种特殊漂变。"},{"word":"sampling error","ipa":"/ˈsæmplɪŋ ˈerə/","tag":"near meaning","definition":"The statistical deviation that drift turns into an evolutionary force.","definitionCN":"漂变转化为演化力量的那个统计偏差。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the sampling picture; abstract ones treat drift as a coin walk with no judge.","cn":"正常联想沿着抽样图景展开；抽象联想把漂变看作一场没有裁判的硬币游走。"},"normal":[{"en":"Drift is what happens when nobody is choosing: the survivors are simply whoever happened to breed.","cn":"漂变就是无人挑选时发生的事：幸存者只是碰巧留下后代的那一批。"},{"en":"The smaller the pond, the bigger the wobble; a few fish can rewrite the proportions.","cn":"水塘越小，摆幅越大；几条鱼就能改写整个比例。"},{"en":"Bottlenecks and founder events are drift given a dramatic entrance.","cn":"瓶颈与奠基者事件，是漂变有了戏剧性的登场方式。"},{"en":"Fixation is the end of the walk: one variant at one hundred percent, all the others at zero.","cn":"固定是这次游走的终点：一个变异达到一成，其余全部归零。"},{"en":"Effective population size, not the head count, tells drift how much room it has.","cn":"决定漂变空间的是有效种群规模，而不是清点人数。"}],"abstract":[{"en":"Drift is a coin tossed by survivors, and no one is keeping score of fitness.","cn":"漂变是幸存者抛出的硬币，没有人替适应度记账。"},{"en":"Randomness needs no reason; it only needs a small enough room.","cn":"随机不需要理由，只需要一个足够小的空间。"},{"en":"In a closed room, diversity leaks away one accidental generation at a time.","cn":"在封闭的房间里，多样性会随着一个个偶然的世代慢慢漏光。"}]},"examples":[{"en":"Genetic drift can fix a harmful allele in a small herd.","cn":"遗传漂变可能在一个小兽群中把有害等位基因固定下来。"},{"en":"Island populations lose variation through genetic drift more quickly than mainland ones.","cn":"岛屿群体通过遗传漂变丢失变异的速度快于大陆群体。"},{"en":"The model separates genetic drift from selection by switching fitness off.","cn":"该模型通过关闭适应度，把遗传漂变与选择区分开来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「基因 追福特」——基因像被水流推着走，没人掌舵，方向全靠偶然：遗传漂变","word":"genetic drift"},"root":"第一个成分是希腊语 genesis「起源」派生的形容词，一九零五年成为遗传学的名称；第二个成分来自古英语 drifan「驱动、推动」，名词本指船只或积雪的缓慢移动，二十世纪三十年代由赖特赋予统计含义。短语的确切首见年代不确定，两个成分的来源清楚。","sensesIntro":{"en":"Nine senses run from the bare mechanism through its statistical cause, its strength in small groups, its two contrasts, its end points, its two dramatic cases and its accounting unit.","cn":"九个义项从机制本身出发，经过统计成因、在小群体中的强度、两组对比、两个终点、两种戏剧性情形，最后落到核算单位。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rock-walled pond where a harmless stripe quietly disappears.","cn":"核心意象：一口石围小塘，一种无害斑纹悄然消失。"},"chain":["RANDOM SAMPLE","SMALLER POOL, BIGGER SWING","NOT SELECTION","NOT MIGRATION","FIX OR LOSE","BOTTLENECK AND FOUNDER"],"branches":[{"senses":"01","en":"THE MECHANISM: a finite sample of gametes wobbles, and the wobble is drift.","cn":"机制本身：有限的配子样本发生抖动，这种抖动就是漂变。"},{"senses":"02 · 03","en":"THE SCALE EFFECT: few breeders mean wide swings, because large-number protection fails.","cn":"规模效应：繁殖者少则摆幅大，因为大数保护失效。"},{"senses":"04 · 05","en":"THE TWO CONTRASTS: selection has a criterion, migration reopens the pool, drift has neither.","cn":"两组对比：选择有标准，迁移能重新打开基因库，而漂变两者皆无。"},{"senses":"06 · 09","en":"THE END POINT AND ITS ACCOUNTING: the walk hits one or zero, and effective size sets how fast.","cn":"终点与核算：游走撞到一或零，而有效规模决定撞得多快。"},{"senses":"07 · 08","en":"THE DRAMATIC CASES: a crash or a small founding group compresses the whole process into a moment.","cn":"戏剧性情形：一次崩溃或一个小奠基群，把整个过程压缩到一瞬间。"}]},"affixes":{"intro":{"en":"Both halves of the phrase are whole words rather than affixes; the only bound pieces are the adjective ending and the noun's old verbal core.","cn":"短语两半都是完整的词而非词缀；真正的黏着成分只有形容词词尾与名词古老的动词核心。"},"latinIntro":{"en":"Greek supplies the root of generation; Old English supplies the verb of driving. No Latin noun stands behind the phrase, so the Latin entry list is left empty.","cn":"希腊语提供了「生成」的词根；古英语提供了「驱动」的动词。短语背后没有拉丁名词，因此拉丁词条列表留空。"},"items":[{"word":"genesis","structure":"Greek noun","meaning":"origin, generation","meaningCN":"起源；生成","example":"It is the root of the whole vocabulary of genetics.","exampleCN":"它是整套遗传学词汇的词根。"},{"word":"genetikos","structure":"Greek adjective","meaning":"concerned with generation","meaningCN":"与生育、发生有关的","example":"English shortened it into the adjective genetic.","exampleCN":"英语把它缩略为形容词。"},{"word":"gene","structure":"English noun, 1909","meaning":"unit of heredity","meaningCN":"遗传单位","example":"The unit was named before the mechanism was understood.","exampleCN":"这个单位在机制被理解之前就已得名。"},{"word":"-ic","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It attaches the Greek root to an English adjective.","exampleCN":"它把希腊词根挂到英语形容词上。"},{"word":"drifan","structure":"Old English verb","meaning":"to drive, to push","meaningCN":"驱动；推动","example":"The verb describes a force moving something along.","exampleCN":"这个动词描述把某物推着走的力量。"},{"word":"drift","structure":"English noun","meaning":"slow unsteered movement","meaningCN":"缓慢且无人操控的移动","example":"The noun moved from boats and snow to allele frequencies.","exampleCN":"这个名词从船只与积雪转到等位基因频率。"},{"word":"drift","structure":"English verb","meaning":"to be carried along","meaningCN":"被带着走","example":"The verb keeps the passive image behind the statistical term.","exampleCN":"这个动词保留了统计术语背后的被动意象。"},{"word":"-t","structure":"Old English noun ending","meaning":"result of an action","meaningCN":"动作的结果","example":"It turns the verb of driving into a noun of motion.","exampleCN":"它把表示驱动的动词变成表示运动的名词。"}],"latinEntries":[],"derivatives":[{"word":"drift","pos":"n./v.","zh":"同一词根独立成词，义为「漂移；漂流」，在遗传学中引申为频率的随机游走"},{"word":"drift","pos":"n.","zh":"由动词转作名词，义为「缓慢的移动；趋势」，是本短语的中心词"},{"word":"drifting","pos":"adj.","zh":"由中心词加进行式词尾构成，义为「漂移的；漂流的」"},{"word":"driftwood","pos":"n.","zh":"由中心词与「木材」复合，义为「浮木」，字面即被水推着走的木头"},{"word":"drift net","pos":"n.","zh":"由中心词与「网」复合，义为「流网」，指随水流漂移的渔网"}]}},{"word":"gene flow","ipa_uk":"/dʒiːn fləʊ/","ipa_us":"/dʒiːn floʊ/","definition_zh":"基因流；基因流动（通过个体迁移、花粉或种子扩散在群体之间传递等位基因）","definition_en":"the transfer of alleles from one population to another through migration, dispersal of seeds or pollen, or human movement","core_image":"山脊隘口的风把一片兰花的花粉吹到另一片兰花上，两种花色在两侧渐渐混匀","scene":"山脊两侧各有一片兰花，花色深浅原本不同，风把花粉送过隘口之后，两边花色的比例渐渐接近。Pollen carried across the ridge produced gene flow between the two orchid populations.","sceneCN":"这里指群体之间的等位基因传递（第 1 个义项：通过迁移或繁殖体扩散把等位基因带入另一群体）；句意为被风送过山脊的花粉在两个兰花群体之间形成了基因流。图中可辨识物件：山脊、隘口、两片花丛、飘散的花粉。","pos":[{"tag":"n.","zh":"名词短语：不可数，指群体间的等位基因传递过程"}],"collocations":[{"phrase":"gene flow between populations","zh":"群体之间的基因流"},{"phrase":"restrict gene flow","zh":"限制基因流"},{"phrase":"gene flow from wild relatives","zh":"来自野生近缘种的基因流"},{"phrase":"measurable gene flow","zh":"可测量的基因流"},{"phrase":"gene flow and genetic drift","zh":"基因流与遗传漂变"},{"phrase":"barriers to gene flow","zh":"基因流的屏障"},{"phrase":"gene flow among islands","zh":"岛屿间的基因流"}],"forms":[{"label":"术语原形","form":"gene flow"},{"label":"介词搭配","form":"gene flow between A and B"},{"label":"定语用法","form":"gene-flow estimates"},{"label":"动词搭配","form":"gene flow occurs"},{"label":"复合修饰","form":"gene-flow barrier"},{"label":"相关短语","form":"rate of gene flow"}],"derivatives":[{"word":"gene","pos":"n.","zh":"短语的第一个成分，义为「基因」，一九零九年由约翰森定名"},{"word":"flow","pos":"n./v.","zh":"短语的中心词，义为「流动」，本指液体的连续移动"},{"word":"gene pool","pos":"n.","zh":"同一领域的概念，义为「基因库」，指一个群体携带的全部等位基因"},{"word":"gene frequency","pos":"n.","zh":"同一领域的量，义为「基因频率」，即某等位基因在群体中的比例"},{"word":"gene flow rate","pos":"n.","zh":"由本短语加「速率」构成，义为「基因流速率」，常以每代迁入个体比例表示"}],"senses":[{"no":"01","title":"The process itself","titleCN":"过程本身","definition":"the movement of alleles between populations when individuals or gametes cross a boundary","definitionCN":"个体或配子跨越边界时等位基因在群体之间的移动","example":"Gene flow between the two valleys kept their colour patterns similar.","exampleCN":"两个山谷之间的基因流使它们的花色格局保持相似。","why":"A boundary that individuals can cross is also a boundary that genes can cross, so the movement of bodies carries the movement of alleles.","whyCN":"个体能越过的边界，基因也能越过；因此身体的移动同时携带了等位基因的移动。"},{"no":"02","title":"Contrast with genetic drift","titleCN":"与遗传漂变的对比","definition":"a gain of variation from outside, whereas drift is a random loss or fixation inside a closed group","definitionCN":"从外部获得变异，而漂变是在封闭群体内部随机丢失或固定","example":"Drift eroded the island's variation while gene flow from the mainland restored it.","exampleCN":"漂变侵蚀了岛上的变异，而来自大陆的基因流又把它补回。","why":"Drift only reshuffles what is already present; gene flow is the one force that adds new alleles to a population.","whyCN":"漂变只重排已有的东西；基因流则是唯一能给群体添入新等位基因的力量。"},{"no":"03","title":"Distinction from migration","titleCN":"与「迁移」的区别","definition":"the genetic consequence of movement, not the movement itself; an individual can migrate without breeding successfully","definitionCN":"移动带来的遗传后果，而非移动本身；个体可以迁移却没有成功繁殖","example":"The birds migrated, but gene flow occurred only where they nested and raised chicks.","exampleCN":"候鸟确实迁徙了，但只有它们筑巢育雏的地方才发生基因流。","why":"Migration is an ecological event; gene flow is its genetic ledger, and a ledger stays empty when no offspring are produced.","whyCN":"迁移是生态事件，基因流是它的遗传账本；没有产生后代，账本上就是空的。"},{"no":"04","title":"Reducing divergence between populations","titleCN":"降低群体间的分化","definition":"the homogenising effect that keeps neighbouring populations genetically similar","definitionCN":"使相邻群体在遗传上保持相似的同质化作用","example":"Strong gene flow prevented the two colonies from splitting into distinct subspecies.","exampleCN":"强大的基因流阻止了两个群体分化为不同的亚种。","why":"Differences accumulate only when gene flow is weak; constant exchange keeps pulling the two gene pools back together.","whyCN":"只有在基因流微弱时差异才会累积；持续的交换不断把两个基因库拉回同一状态。"},{"no":"05","title":"Barriers and connectivity","titleCN":"屏障与连通性","definition":"geographic features, distance or human construction that reduce the probability of successful exchange","definitionCN":"地形、距离或人造设施降低成功交换概率的情形","example":"A new motorway became a barrier to gene flow for the forest frogs.","exampleCN":"新建的高速公路成了林蛙基因流的屏障。","why":"Gene flow needs a path; when a barrier makes crossing rare, drift and local selection begin to separate the groups.","whyCN":"基因流需要通路；当屏障使跨越变得罕见，漂变与局部选择就开始把两群分开。"},{"no":"06","title":"Plant-mediated flow","titleCN":"植物介导的基因流","definition":"pollen and seed dispersal, which move genes without moving whole plants","definitionCN":"花粉与种子的扩散，在不移动整株植物的情况下搬运基因","example":"Wind-borne pollen carried gene flow across the whole meadow.","exampleCN":"风媒花粉把基因流带遍了整片草甸。","why":"A plant cannot walk, but its pollen and seeds can travel, so dispersal replaces migration as the vehicle.","whyCN":"植物不会走路，但花粉与种子能旅行，于是扩散取代迁移成为载体。"},{"no":"07","title":"Animal-mediated flow","titleCN":"动物介导的基因流","definition":"gene movement carried by migrating herds, birds, fish or insects","definitionCN":"由迁徙的兽群、鸟、鱼或昆虫携带的基因移动","example":"Migrating salmon brought gene flow from the sea back to their home streams.","exampleCN":"洄游的鲑鱼把基因流从海洋带回故乡的溪流。","why":"Animals that return to breed link distant sites in a single lifetime, making them extremely effective vectors.","whyCN":"返回繁殖地的动物在一个生命周期内就把相距遥远的地点连起来，因此是极高效的载体。"},{"no":"08","title":"Human-mediated flow","titleCN":"人类活动介导的基因流","definition":"translocation, stocking, shipping and trade that move organisms far beyond their natural range","definitionCN":"引种、放养、船运与贸易把生物带到远超自然分布范围的地方","example":"Ballast water created gene flow between ports that had never exchanged shellfish.","exampleCN":"压舱水在从未交换过贝类的港口之间造成了基因流。","why":"Modern transport compresses distance to nearly zero, so gene flow can occur between places with no natural corridor.","whyCN":"现代运输把距离压缩到近乎为零，于是没有天然走廊的地点之间也能发生基因流。"},{"no":"09","title":"Conservation and corridor design","titleCN":"保护与走廊设计","definition":"the management use of gene flow to counter inbreeding while avoiding the introduction of maladapted genes","definitionCN":"用基因流缓解近交、同时避免引入不适应当地基因的管理应用","example":"Managers allowed limited gene flow to rescue the isolated herd without swamping local adaptation.","exampleCN":"管理者允许有限的基因流来挽救隔离兽群，又不至于淹没本地适应。","why":"Too little flow means inbreeding; too much can erase local adaptation, so the useful concept is a controlled rate rather than a maximum.","whyCN":"流得太少会近交，流得太多会抹掉本地适应，因此有用的概念是受控的速率而非越大越好。"}],"etymology":{"intro":{"en":"The phrase pairs a word coined in 1909 for the unit of inheritance with an Old English verb of flowing. Its modern genetic sense belongs to the twentieth century; the exact first printed use of the pair is not fixed.","cn":"这个短语把一九零九年为遗传单位造出的词与一个古英语「流动」动词配在一起。其现代遗传学含义属于二十世纪；两词首次印在一起的准确时间并不确定。"},"items":[{"era":"GREEK GENOS","en":"Genos meant race, stock or kind; Johannsen took it through German to name the gene in 1909.","cn":"这个词意为族、种、类；约翰森经德语把它引入，于一九零九年为「基因」命名。"},{"era":"ENGLISH GENE","en":"The new noun named the unit of heredity before anyone knew what it was made of.","cn":"这个新名词在人们知道遗传单位由什么构成之前就已为它命名。"},{"era":"OLD ENGLISH FLOWAN","en":"Flowan meant to flow or to run as water does; its noun flow named the continuous movement itself.","cn":"这个古英语动词意为像水一样流动；其名词形式指这种连续运动本身。"},{"era":"POPULATION THINKING","en":"Once heredity was counted in populations, the movement of genes between groups needed a name of its own.","cn":"当遗传开始在群体中计数，群体之间基因的移动就需要一个自己的名字。"},{"era":"MODERN TERM","en":"The fixed phrase spread in the middle of the twentieth century with the rise of population genetics; its first attestation is uncertain in date but not in origin.","cn":"这个固定短语随群体遗传学的兴起在二十世纪中叶流行；其首见年代不确定，来源却清楚。"}]},"similar":{"note":{"en":"The first group shares the word gene or the flow frame; the second group names other ways alleles travel or mix.","cn":"第一组共享「基因」一词或「流动」框架；第二组是等位基因传播与混合的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gene pool","ipa":"/dʒiːn puːl/","tag":"shared word","definition":"All the alleles carried by one population at a given time.","definitionCN":"某一时刻一个群体所携带的全部等位基因。"},{"word":"gene frequency","ipa":"/dʒiːn ˈfriːkwənsi/","tag":"shared word","definition":"The proportion of a particular allele within a population.","definitionCN":"某个特定等位基因在群体中所占的比例。"},{"word":"gene drive","ipa":"/dʒiːn draɪv/","tag":"near form","definition":"A genetic construct that spreads a trait faster than ordinary inheritance.","definitionCN":"一种让某性状传播得比普通遗传更快的遗传构造。"},{"word":"gene flux","ipa":"/dʒiːn flʌks/","tag":"near form","definition":"An informal term for the rate at which genes enter or leave a group.","definitionCN":"非正式说法，指基因进出群体的速率。"},{"word":"genetic flow","ipa":"/dʒɪˈnetɪk fləʊ/","tag":"loose variant","definition":"A looser wording sometimes used for the same idea.","definitionCN":"有时用于同一含义的较宽松说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"migration","ipa":"/maɪˈɡreɪʃən/","tag":"near meaning","definition":"The ecological movement of individuals, which may or may not carry genes into the breeding pool.","definitionCN":"个体的生态性移动，未必能把基因带入繁殖群体。"},{"word":"dispersal","ipa":"/dɪˈspɜːsl/","tag":"near meaning","definition":"The spreading of seeds, spores or young away from the parent.","definitionCN":"种子、孢子或幼体离开亲体向外扩散。"},{"word":"introgression","ipa":"/ˌɪntrəˈɡreʃən/","tag":"near meaning","definition":"The permanent incorporation of genes from one species into another through hybridisation.","definitionCN":"通过杂交把一个物种的基因永久并入另一个物种。"},{"word":"admixture","ipa":"/ədˈmɪkstʃə/","tag":"near meaning","definition":"The mixing of two previously separated gene pools.","definitionCN":"两个先前隔离的基因库发生混合。"},{"word":"hybridisation","ipa":"/ˌhaɪbrɪdaɪˈzeɪʃən/","tag":"near meaning","definition":"Crossing between distinct groups, often the route by which gene flow becomes introgression.","definitionCN":"不同群体间的杂交，常是基因流变成渐渗的途径。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the vehicles of flow; abstract ones treat gene flow as a door in a wall.","cn":"正常联想沿着基因流的各种载体展开；抽象联想把它看作墙上的一扇门。"},"normal":[{"en":"Genes travel in bodies, in pollen and in seeds; the traveller is the vehicle.","cn":"基因随身体、花粉与种子旅行；旅行者就是载体。"},{"en":"Migration is the walk; gene flow is the birth that follows it.","cn":"迁移是走路，基因流是走路之后发生的繁殖。"},{"en":"Drift closes the room, gene flow opens a window.","cn":"漂变关上房间，基因流打开一扇窗。"},{"en":"Barriers make flow rare, and rarity lets drift and selection pull the two sides apart.","cn":"屏障让流动变少，稀少又让漂变与选择把两侧拉开。"},{"en":"In conservation the useful setting is a controlled trickle, not a flood.","cn":"在保护实践中，有用的设定是受控的细流，而不是洪水。"}],"abstract":[{"en":"Gene flow is the only force that adds new letters to a population's alphabet.","cn":"基因流是唯一能给群体的字母表添入新字母的力量。"},{"en":"A corridor is a sentence spoken between two populations that could not otherwise talk.","cn":"走廊是两个本无法交谈的群体之间说出的一句话。"},{"en":"Distance is a resistor, and each migrant is a small current.","cn":"距离是电阻，每个迁入者都是一小股电流。"}]},"examples":[{"en":"Gene flow from the mainland restored variation the island had lost.","cn":"来自大陆的基因流恢复了岛屿已经丢失的变异。"},{"en":"A motorway reduced gene flow between the two frog populations.","cn":"一条高速公路降低了两群林蛙之间的基因流。"},{"en":"Pollen dispersal is the main route of gene flow in wind-pollinated grasses.","cn":"花粉扩散是风媒禾草中基因流的主要途径。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「基因 弗楼」——基因像水一样「流」过山谷，把两边的库连起来：基因流","word":"gene flow"},"root":"第一个成分由希腊语 genos「族、种」经德语于一九零九年定为「基因」；第二个成分来自古英语 flowan「流动」。整个短语在二十世纪中叶随群体遗传学兴起而通行，确切首见年代不确定。","sensesIntro":{"en":"Nine senses move from the bare process to its contrast with drift, its difference from migration, its effects, its vehicles and its management.","cn":"九个义项从过程本身出发，依次到与漂变的对比、与迁移的区别、效应、各种载体，最后到管理应用。"},"semanticMap":{"core":{"en":"CORE IMAGE: wind over a ridge pass, pollen crossing from one orchid patch to the other.","cn":"核心意象：风越过山口，花粉从一片兰花飘到另一片。"},"chain":["ALLELES CROSS","GAIN FROM OUTSIDE","NOT MERE MOVEMENT","DIVERGENCE FALLS","VEHICLES","CORRIDORS"],"branches":[{"senses":"01","en":"THE PROCESS: bodies or gametes cross a boundary, and alleles cross with them.","cn":"过程本身：个体或配子越过边界，等位基因随之越界。"},{"senses":"02 · 03","en":"THE TWO DISTINCTIONS: drift only reshuffles inside, and migration matters only when offspring are produced.","cn":"两组区分：漂变只在内部重排，迁移只有产生后代才有效。"},{"senses":"04 · 05","en":"THE EFFECT AND ITS BRAKE: exchange homogenises neighbours until a barrier makes crossing rare.","cn":"效应与刹车：交换使邻群同质化，直到屏障让跨越变少。"},{"senses":"06 · 07 · 08","en":"THE VEHICLES: pollen, animals and human transport each carry genes by a different route.","cn":"三类载体：花粉、动物与人类运输各以不同路径搬运基因。"},{"senses":"09","en":"THE MANAGEMENT: conservation wants a controlled trickle that fights inbreeding without erasing local adaptation.","cn":"管理应用：保护实践要的是受控细流，既抗近交又不抹掉本地适应。"}]},"affixes":{"intro":{"en":"The phrase is two free words; its only bound pieces are the old adjective ending on the first word and the noun endings on both.","cn":"这个短语由两个自由词构成；黏着成分只有第一个词上的古老形容词词尾与两个词的名词词尾。"},"latinIntro":{"en":"Greek gives the root for kind or stock; Old English gives the verb of flowing. No Latin noun underlies either half, so the Latin entry list is left empty.","cn":"希腊语提供「族、种」的词根；古英语提供「流动」动词。两半背后都没有拉丁名词，因此拉丁词条列表留空。"},"items":[{"word":"genos","structure":"Greek noun","meaning":"race, stock, kind","meaningCN":"族；种；类","example":"The root names a line of descent rather than a single trait.","exampleCN":"这个词根指一条血统，而非单个性状。"},{"word":"gene","structure":"English noun, 1909","meaning":"the unit of heredity","meaningCN":"遗传单位","example":"Johannsen created the short form for the unit.","exampleCN":"约翰森为这个单位造出这个短词。"},{"word":"genetic","structure":"English adjective","meaning":"relating to genes","meaningCN":"与基因有关的","example":"The adjective links the unit to the whole science.","exampleCN":"这个形容词把单位与整门科学连起来。"},{"word":"-ic","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It attaches the Greek root to English syntax.","exampleCN":"它把希腊词根接入英语句法。"},{"word":"flowan","structure":"Old English verb","meaning":"to flow, to run","meaningCN":"流动；流","example":"The verb described water moving without a fixed shape.","exampleCN":"这个动词描述水在没有固定形状的情况下移动。"},{"word":"flow","structure":"English noun","meaning":"continuous movement","meaningCN":"连续流动","example":"The noun names movement as a process rather than an event.","exampleCN":"这个名词把移动看作过程而非事件。"},{"word":"inflow","structure":"English compound","meaning":"movement inward","meaningCN":"流入","example":"The prefix marks direction toward the centre.","exampleCN":"前缀标记朝向中心的运动。"},{"word":"outflow","structure":"English compound","meaning":"movement outward","meaningCN":"流出","example":"The prefix marks direction away from the centre.","exampleCN":"前缀标记离开中心的运动。"}],"latinEntries":[],"derivatives":[{"word":"gene","pos":"n.","zh":"短语的第一个成分，义为「基因」，一九零九年由约翰森定名"},{"word":"flow","pos":"n./v.","zh":"短语的中心词，义为「流动」，本指液体的连续移动"},{"word":"gene pool","pos":"n.","zh":"同一领域的概念，义为「基因库」，指一个群体携带的全部等位基因"},{"word":"gene frequency","pos":"n.","zh":"同一领域的量，义为「基因频率」，即某等位基因在群体中的比例"},{"word":"gene flow rate","pos":"n.","zh":"由本短语加「速率」构成，义为「基因流速率」，常以每代迁入个体比例表示"}]}},{"word":"juvenile","ipa_uk":"/ˈdʒuːvənɪl/","ipa_us":"/ˈdʒuːvənaɪl/","definition_zh":"幼年的；青少年的；幼稚的；（名词）幼体、青少年","definition_en":"young and not yet mature; of or for young people; (noun) a young animal or a young person below the legal age of adulthood","core_image":"育幼室的玻璃窗前，一只幼年黑猩猩抓着奶瓶，饲养员在记录板上写下体重","scene":"动物园的育幼室里，饲养员每天给一只幼年黑猩猩称重，记录它第一次自己抓握奶瓶的时刻。Keepers weighed the juvenile chimpanzee every morning during its first year.","sceneCN":"这里用作形容词，指尚未成年的（第 1 个义项：生物学上处于幼年阶段的）；句意为饲养员在这只幼年黑猩猩出生后的第一年里每天为它称重。图中可辨识物件：育幼箱、奶瓶、记录板、玻璃窗。","pos":[{"tag":"adj.","zh":"形容词：幼年的；未成年的；幼稚的"},{"tag":"n.","zh":"名词：幼体、幼兽；青少年"}],"collocations":[{"phrase":"juvenile delinquency","zh":"少年犯罪"},{"phrase":"juvenile court","zh":"少年法庭"},{"phrase":"juvenile literature","zh":"少儿读物"},{"phrase":"juvenile hormone","zh":"保幼激素"},{"phrase":"juvenile stage","zh":"幼期阶段"},{"phrase":"juvenile fish","zh":"幼鱼"},{"phrase":"a juvenile offender","zh":"少年犯"}],"forms":[{"label":"形容词原形","form":"juvenile"},{"label":"名词单数","form":"juvenile"},{"label":"名词复数","form":"juveniles"},{"label":"比较级","form":"more juvenile"},{"label":"最高级","form":"most juvenile"},{"label":"派生名词","form":"juvenility"},{"label":"派生形容词","form":"juvenile-like"}],"derivatives":[{"word":"juvenility","pos":"n.","zh":"由形容词加表示「性质」的词尾构成，义为「幼稚；少年状态」"},{"word":"juvenile","pos":"n.","zh":"由形容词转作名词，义为「幼体；青少年」"},{"word":"juveniles","pos":"n.","zh":"名词复数形式，义为「幼体们；青少年们」"},{"word":"juvenescence","pos":"n.","zh":"由拉丁词根加表示「开始进入某状态」的词尾构成，义为「幼态延续；保持年轻状态」"},{"word":"rejuvenate","pos":"v.","zh":"由表示「再次」的前缀加拉丁词根构成，义为「使恢复年轻；使复苏」"}],"senses":[{"no":"01","title":"Young and not yet mature","titleCN":"幼年的；尚未成熟的","definition":"of an organism that has not reached sexual or adult maturity","definitionCN":"指生物尚未达到性成熟或成体阶段的","example":"The juvenile birds still followed their mother for food.","exampleCN":"这些幼鸟仍然跟着母亲觅食。","why":"The word simply marks the stage before adulthood, so it applies to any species whose young differ from the adult form.","whyCN":"这个词只标记成年之前的那一阶段，因此适用于任何幼体与成体形态不同的物种。"},{"no":"02","title":"A young animal or plant","titleCN":"幼体、幼兽","definition":"a noun for an individual in its early stage of life","definitionCN":"作名词，指处于生命早期阶段的个体","example":"The reef was crowded with juveniles of three different fish species.","exampleCN":"礁区挤满了三种鱼的幼体。","why":"Biologists need a neutral noun for the stage, because words such as baby or chick are tied to particular groups.","whyCN":"生物学家需要一个中性的阶段名词，因为「婴儿」「雏鸟」之类的词都绑定在特定类群上。"},{"no":"03","title":"A young person below legal adulthood","titleCN":"未成年人；青少年","definition":"a noun used in law and social policy for a person who is not yet an adult","definitionCN":"法律与社会政策中作名词，指尚未成年的人","example":"The programme offers mentoring to juveniles who have left school early.","exampleCN":"该项目为早早辍学的青少年提供辅导。","why":"Legal systems need a category between child and adult, and this word supplies the neutral label for that category.","whyCN":"法律体系需要在儿童与成人之间设一档，这个词就提供了这一档的中性标签。"},{"no":"04","title":"Childish or immature in manner","titleCN":"幼稚的；不成熟的","definition":"an adjective describing behaviour that seems too young for the person's age","definitionCN":"形容行为与年龄不相称、显得过于孩子气","example":"It was a juvenile joke, and nobody laughed.","exampleCN":"那是个幼稚的玩笑，没人笑。","why":"The biological sense of not-yet-adult slides easily into a judgement about behaviour that has not matured either.","whyCN":"「尚未成年」这一生物学含义很容易滑向对行为的评判：行为同样没有成熟。"},{"no":"05","title":"The juvenile court system","titleCN":"少年法庭体系","definition":"the branch of law that handles young offenders with different procedures from adult courts","definitionCN":"以不同于成人法庭的程序处理少年违法者的法律分支","example":"The juvenile court prioritised schooling over punishment.","exampleCN":"少年法庭把就学安排置于惩罚之上。","why":"Because young offenders are still developing, the legal system separates their cases and aims at correction rather than simple penalty.","whyCN":"由于少年违法者仍在发育，法律体系把他们的案件分开处理，目标在矫正而非单纯惩罚。"},{"no":"06","title":"Juvenile delinquency","titleCN":"少年犯罪","definition":"the fixed term for law-breaking by minors, studied in criminology and social work","definitionCN":"指未成年人违法的固定术语，是犯罪学与社会工作的研究对象","example":"The report linked juvenile delinquency to absent after-school care.","exampleCN":"报告把少年犯罪与缺少课后照管联系起来。","why":"The phrase names a social problem rather than a legal category, which is why it carries a policy charge the bare adjective lacks.","whyCN":"这个短语命名的是一个社会问题而非法律类别，因此它带有单纯形容词所没有的政策意味。"},{"no":"07","title":"Juvenile literature","titleCN":"少儿读物","definition":"the publishing category for books written for children and young teenagers","definitionCN":"面向儿童与少年读者的出版类别","example":"The library moved juvenile literature to the ground floor.","exampleCN":"图书馆把少儿读物移到了一层。","why":"Publishers needed a shelf label for the reading age, and the word supplied a neutral one.","whyCN":"出版方需要一个按阅读年龄划分的书架标签，这个词提供了中性选项。"},{"no":"08","title":"Juvenile hormone","titleCN":"保幼激素","definition":"an insect hormone that keeps the larva in its juvenile form and prevents premature metamorphosis","definitionCN":"昆虫体内维持幼虫形态、阻止过早变态的激素","example":"A drop in juvenile hormone triggers the insect to pupate.","exampleCN":"保幼激素水平下降会触发昆虫化蛹。","why":"The hormone literally keeps the insect juvenile, so the technical name reuses the everyday adjective in its strict biological sense.","whyCN":"这种激素字面上就是让昆虫保持幼态，因此技术名称沿用了日常形容词的严格生物学含义。"},{"no":"09","title":"Juvenile water in geology","titleCN":"地质学上的初生水","definition":"water that has never been part of the atmosphere or surface cycle, released from magma","definitionCN":"从未进入大气或地表循环、由岩浆释放的水","example":"Geologists sampled juvenile water from a deep fracture.","exampleCN":"地质学家从一条深断裂中采集了初生水。","why":"The geological sense borrows the same image of a substance still in its first, unmodified state.","whyCN":"地质学含义借用了同一个意象：某种物质仍处于最初、未被改造的状态。"}],"etymology":{"intro":{"en":"The word comes from Latin iuvenis, a young person, through the adjective iuvenilis. Its Latin ancestry is clear; only the exact date of its first English use is approximate.","cn":"这个词经拉丁形容词进入英语，源头是表示「年轻人」的拉丁名词。其拉丁渊源清楚，只有进入英语的确切年代为约数。"},"items":[{"era":"LATIN IUVENIS","en":"Iuvenis meant a young person, and it stood in contrast to senex, an old one.","cn":"这个词指年轻人，与表示「老人」的词相对。"},{"era":"LATIN IUVENILIS","en":"The adjective iuvenilis meant youthful or belonging to youth, and it is the direct source of the English word.","cn":"这个形容词表示「年轻的、属于青年的」，是英语词的直接来源。"},{"era":"RELATED LATIN WORDS","en":"Iuventus, youth, and iuvenca, a young cow, come from the same stock, which is also behind the comparative junior.","cn":"表示「青年」与「小母牛」的拉丁词出自同一词族，比较级形式的「较年幼的」也来自这里。"},{"era":"ENGLISH, 17TH CENTURY","en":"English adopted the adjective in the seventeenth century in the sense of youthful or suitable for young people.","cn":"英语在十七世纪引入这个形容词，义为「年轻的」或「适合年轻人的」。"},{"era":"LEGAL AND BIOLOGICAL SPLIT","en":"In the nineteenth and twentieth centuries the word specialised in two directions: the legal minor and the young organism.","cn":"在十九与二十世纪，这个词朝两个方向专门化：法律上的未成年人，以及生物学上的幼体。"}]},"similar":{"note":{"en":"The first group shares the stem or the fixed compounds; the second group names other ways of being young.","cn":"第一组共享词干或固定搭配；第二组是「年轻」的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"juveniles","ipa":"/ˈdʒuːvənaɪlz/","tag":"same word","definition":"The plural noun for young animals or young people.","definitionCN":"指幼体或青少年的复数名词。"},{"word":"juvenilia","ipa":"/ˌdʒuːvəˈnɪliə/","tag":"same stem","definition":"Works produced by an author in childhood or youth.","definitionCN":"作者童年或青年时期的作品。"},{"word":"juvenile court","ipa":"/ˈdʒuːvənɪl kɔːt/","tag":"compound","definition":"The court that handles young offenders.","definitionCN":"处理少年违法者的法庭。"},{"word":"juvenile hormone","ipa":"/ˈdʒuːvənɪl ˈhɔːməʊn/","tag":"compound","definition":"The insect hormone maintaining larval form.","definitionCN":"维持幼虫形态的昆虫激素。"},{"word":"juvenility","ipa":"/ˌdʒuːvəˈnɪləti/","tag":"derived noun","definition":"The quality of being juvenile.","definitionCN":"幼稚、年幼的状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adolescent","ipa":"/ˌædəˈlesənt/","tag":"near meaning","definition":"A person in the teenage years; also the adjective for that stage.","definitionCN":"处于青少年时期的人，也可作该阶段的形容词。"},{"word":"immature","ipa":"/ˌɪməˈtjʊə/","tag":"near meaning","definition":"Not yet fully developed, used of bodies, behaviour or ideas.","definitionCN":"尚未充分发育的，可用于身体、行为或想法。"},{"word":"young","ipa":"/jʌŋ/","tag":"near meaning","definition":"The general word for having lived a short time.","definitionCN":"表示「年岁小」的通用词。"},{"word":"underage","ipa":"/ˌʌndərˈeɪdʒ/","tag":"near meaning","definition":"Below the legal age for a activity or right.","definitionCN":"未达到某项活动或权利的法定年龄。"},{"word":"childish","ipa":"/ˈtʃaɪldɪʃ/","tag":"near meaning","definition":"Behaving in a way judged too young, usually negatively.","definitionCN":"行为显得过于孩子气，通常带贬义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations run through the life stage, the legal category and the technical compounds; abstract ones keep the image of something still in its first form.","cn":"正常联想串联生命阶段、法律类别与技术搭配；抽象联想保留「仍处最初形态」的意象。"},"normal":[{"en":"Juvenile is the stage before adult, in any species.","cn":"幼年就是任何物种成年之前的那个阶段。"},{"en":"As a noun it can be a young animal or a legal minor, depending on the room it is used in.","cn":"作名词时可以是幼兽，也可以是法律上的未成年人，取决于使用场合。"},{"en":"Juvenile court and juvenile delinquency belong to the legal family.","cn":"少年法庭与少年犯罪属于法律这一族用法。"},{"en":"Juvenile hormone keeps an insect in its larval body on purpose.","cn":"保幼激素有意让昆虫停留在幼虫身体里。"},{"en":"The geology sense keeps water in its first, untouched state.","cn":"地质学含义让水保持最初、未被触碰的状态。"}],"abstract":[{"en":"Juvenile is a door marked not yet, and every field decides what lies beyond it.","cn":"「幼年」是一扇写着「尚未」的门，每个领域自行决定门后是什么。"},{"en":"The same word can describe a body, a behaviour and a drop of water, because all three are unfinished.","cn":"同一个词能形容身体、行为与一滴水，因为三者都尚未完成。"},{"en":"Growing up is mostly a change of label.","cn":"长大，多半只是标签的更换。"}]},"examples":[{"en":"The juvenile fish stay in the shallows until they are large enough to migrate.","cn":"幼鱼留在浅水区，直到长到足以迁徙。"},{"en":"The juvenile court handles cases involving offenders under eighteen.","cn":"少年法庭处理涉及十八岁以下违法者的案件。"},{"en":"Juvenile hormone levels determine when the larva can pupate.","cn":"保幼激素水平决定幼虫何时可以化蛹。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「猪维奈尔」——小猪还没长大，正是「幼年的」：幼年的、青少年","word":"juvenile"},"root":"来自拉丁语 iuvenis「年轻人」，经形容词 iuvenilis「年轻的」进入英语，十七世纪起使用。同族还有表示「青年」与「小母牛」的词，以及比较级形式的「较年幼的」。拉丁渊源清楚，英语首见年代为约数。","sensesIntro":{"en":"Nine senses spread across three worlds: the biological stage, the legal minor, and the technical compounds that keep the literal sense.","cn":"九个义项分布在三个世界：生物学阶段、法律上的未成年人，以及保留字面含义的技术搭配。"},"semanticMap":{"core":{"en":"CORE IMAGE: a nursery window, a young ape holding its bottle, a keeper writing the weight.","cn":"核心意象：育幼室窗前，幼猿抱着奶瓶，饲养员记下体重。"},"chain":["NOT YET ADULT","YOUNG ORGANISM","LEGAL MINOR","CHILDISH MANNER","COURT AND DELINQUENCY","TECHNICAL COMPOUNDS"],"branches":[{"senses":"01","en":"THE CORE: the word marks the stage before adulthood.","cn":"核心：这个词标记成年之前的阶段。"},{"senses":"02","en":"THE ORGANISM: as a noun it names the young animal or plant itself.","cn":"生物个体：作名词时指幼体本身。"},{"senses":"03 · 04","en":"THE PERSON AND THE JUDGEMENT: a legal minor, and behaviour that has not matured.","cn":"人与评判：法律上的未成年人，以及尚未成熟的行为。"},{"senses":"05 · 06","en":"THE LAW: court and delinquency turn the stage into an institution and a social problem.","cn":"法律：法庭与少年犯罪把这一阶段变成制度与社会问题。"},{"senses":"07 · 08 · 09","en":"THE TECHNICAL USES: reading age, insect hormone, and water still in its first state.","cn":"技术用法：阅读年龄、昆虫激素，以及仍处最初状态的水。"}]},"affixes":{"intro":{"en":"The word is one Latin adjective with an English noun life; the endings are the only bound parts.","cn":"这个词是一个拉丁形容词加英语名词用法；黏着成分只有词尾。"},"latinIntro":{"en":"Latin supplies iuvenis, a young person, and the adjective ending -ilis; the same stock gives youth, the comparative junior and the revived verb of making young again.","cn":"拉丁语提供了「年轻人」与形容词词尾；同一词族还给出「青年」、「较年幼的」以及「使恢复年轻」的动词。"},"items":[{"word":"iuvenis","structure":"Latin noun","meaning":"a young person","meaningCN":"年轻人","example":"It stands opposite the Latin word for an old person.","exampleCN":"它与拉丁语中表示老人的词相对。"},{"word":"iuvenilis","structure":"Latin adjective","meaning":"youthful, of youth","meaningCN":"年轻的；属于青年的","example":"It is the direct source of the English adjective.","exampleCN":"它是英语形容词的直接来源。"},{"word":"-ilis","structure":"Latin adjective ending","meaning":"belonging to, fitted for","meaningCN":"属于……的；适于……的","example":"It turns the noun of a person into an adjective of quality.","exampleCN":"它把指人的名词变成性质形容词。"},{"word":"iuventus","structure":"Latin noun","meaning":"youth","meaningCN":"青年；青春","example":"The abstract noun names the whole period.","exampleCN":"这个抽象名词指整个时期。"},{"word":"junior","structure":"Latin comparative","meaning":"younger","meaningCN":"较年幼的","example":"The comparative survives in English as a rank and a term for a younger person.","exampleCN":"这个比较级在英语中保留为职级与「较年幼者」的称呼。"},{"word":"juvenility","structure":"English noun","meaning":"the state of being young or childish","meaningCN":"年幼；幼稚","example":"The suffix -ity turns the adjective into a quality.","exampleCN":"表示「性质」的词尾把形容词变成性质名词。"},{"word":"juvenescence","structure":"English noun","meaning":"the process of remaining or becoming young","meaningCN":"保持年轻；幼态延续","example":"The suffix marks the beginning of a state.","exampleCN":"这个词尾标记进入某种状态的开端。"},{"word":"rejuvenate","structure":"English verb","meaning":"to make young again","meaningCN":"使恢复年轻","example":"The prefix means again, and the verb reverses ageing.","exampleCN":"前缀意为「再次」，整个动词表示逆转老化。"}],"latinEntries":[{"word":"iuvenis","structure":"Latin noun","meaning":"young person","meaningCN":"年轻人"},{"word":"iuvenilis","structure":"Latin adjective","meaning":"youthful","meaningCN":"年轻的"},{"word":"iuventus","structure":"Latin noun","meaning":"youth","meaningCN":"青年"},{"word":"junior","structure":"Latin comparative","meaning":"younger","meaningCN":"较年幼的"}],"derivatives":[{"word":"juvenility","pos":"n.","zh":"由形容词加表示「性质」的词尾构成，义为「幼稚；少年状态」"},{"word":"juvenile","pos":"n.","zh":"由形容词转作名词，义为「幼体；青少年」"},{"word":"juveniles","pos":"n.","zh":"名词复数形式，义为「幼体们；青少年们」"},{"word":"juvenescence","pos":"n.","zh":"由拉丁词根加表示「开始进入某状态」的词尾构成，义为「幼态延续；保持年轻状态」"},{"word":"rejuvenate","pos":"v.","zh":"由表示「再次」的前缀加拉丁词根构成，义为「使恢复年轻；使复苏」"}]}},{"word":"maturity","ipa_uk":"/məˈtʃʊərəti/","ipa_us":"/məˈtʃʊrəti/","definition_zh":"成熟；成熟期；（金融票据、合同等的）到期；到期日","definition_en":"the state of being fully developed; the point at which a financial instrument or contract falls due","core_image":"果园里，技术员切开一颗果子查看糖度，记录板上画着逐周上升的曲线","scene":"果园里，技术员每隔一周测一次果实的糖度，直到整片园子的果子都达到采收标准。The orchard was picked only after the fruit reached full maturity.","sceneCN":"这里指果实发育完成（第 1 个义项：生理或发育意义上的成熟）；句意为直到果实完全成熟，果园才开始采摘。图中可辨识物件：果树、糖度计、记录板、采果篮。","pos":[{"tag":"n.","zh":"名词：不可数，指成熟状态；金融语境可指到期或到期日"}],"collocations":[{"phrase":"reach maturity","zh":"达到成熟；到期"},{"phrase":"sexual maturity","zh":"性成熟"},{"phrase":"maturity date","zh":"到期日"},{"phrase":"yield to maturity","zh":"到期收益率"},{"phrase":"at maturity","zh":"到期时"},{"phrase":"emotional maturity","zh":"情感成熟"},{"phrase":"maturity of the bond","zh":"债券到期"}],"forms":[{"label":"名词原形","form":"maturity"},{"label":"复数（罕见）","form":"maturities"},{"label":"定语用法","form":"maturity + 名词"},{"label":"介词短语","form":"at maturity"},{"label":"相关形容词","form":"mature"},{"label":"相关动词","form":"mature"}],"derivatives":[{"word":"mature","pos":"adj./v.","zh":"同一词根独立成词，义为「成熟的；使成熟」"},{"word":"maturation","pos":"n.","zh":"由动词加表示「过程」的词尾构成，义为「成熟过程；成熟」"},{"word":"immature","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不成熟的」"},{"word":"immaturity","pos":"n.","zh":"由否定前缀加本词构成，义为「不成熟；幼稚」"},{"word":"premature","pos":"adj.","zh":"由表示「之前」的前缀加形容词构成，义为「过早的；早产的」"},{"word":"maturities","pos":"n.","zh":"本词的复数形式，金融中指多笔不同期限的到期安排"}],"senses":[{"no":"01","title":"Biological maturity","titleCN":"生理成熟","definition":"the stage at which an organism can reproduce and its body has finished growing","definitionCN":"生物能够繁殖、身体完成生长的阶段","example":"The seals reach sexual maturity at about four years old.","exampleCN":"这些海豹大约四岁达到性成熟。","why":"Development has a natural end point, and the word names the moment when growth and reproduction are both available.","whyCN":"发育有天然的终点，这个词命名的正是生长与繁殖都已具备的时刻。"},{"no":"02","title":"Emotional and judgemental maturity","titleCN":"心理与判断上的成熟","definition":"the capacity to weigh consequences and act responsibly rather than impulsively","definitionCN":"能权衡后果、负责任地行动而不凭冲动的能力","example":"The negotiations demanded patience and a certain maturity from both sides.","exampleCN":"谈判要求双方都有耐心与一定的成熟度。","why":"The same word for ripening is applied to character, because both describe something that has stopped being unripe.","whyCN":"表示「成熟」的同一个词被用到性格上，因为两者都描述某物不再青涩。"},{"no":"03","title":"Ripeness of fruit or crops","titleCN":"果实与作物的成熟","definition":"the point at which a crop is ready to harvest, judged by colour, sugar or texture","definitionCN":"作物达到可采收的程度，常以颜色、糖度或质地判断","example":"Growers test sugar levels to decide when the grapes reach maturity.","exampleCN":"种植者测试糖度来决定葡萄何时成熟。","why":"Harvest timing needs a threshold, and the word names the stage where the fruit is fully formed and ready.","whyCN":"采收时机需要一个阈值，这个词命名的就是果实完全成形且可用的阶段。"},{"no":"04","title":"A financial instrument falling due","titleCN":"金融票据到期","definition":"the date on which a bond, note or loan must be repaid, or the state of having reached that date","definitionCN":"债券、票据或贷款必须偿还的日期，或已到达该日期的状态","example":"The bond has a maturity of ten years from issue.","exampleCN":"这只债券自发行起十年到期。","why":"Finance borrowed the language of ripening: a debt is mature when it has reached the point of payment.","whyCN":"金融借用了「成熟」的说法：债务到了该偿付的时刻，就说它到期。"},{"no":"05","title":"The maturity date","titleCN":"到期日","definition":"the specific calendar day on which the principal of an instrument must be repaid","definitionCN":"票据本金必须偿还的具体日期","example":"Investors marked the maturity date in their calendars.","exampleCN":"投资者把到期日标在日历上。","why":"Once a date had to be written down, the abstract state became a fixed appointment.","whyCN":"一旦必须写下一个日期，抽象状态就变成了固定的约定。"},{"no":"06","title":"Yield to maturity","titleCN":"到期收益率","definition":"the total return an investor receives if a bond is held until it matures","definitionCN":"债券持有至到期时投资者获得的总回报率","example":"The bond's yield to maturity was higher than its coupon rate.","exampleCN":"这只债券的到期收益率高于票面利率。","why":"The measure exists because the value of a bond depends on everything received up to and including the final day.","whyCN":"这一指标之所以存在，是因为债券价值取决于到期日及之前收到的全部现金流。"},{"no":"07","title":"Expiry of a contract or policy","titleCN":"合同或保单期满","definition":"the end of the term for which an insurance policy or agreement runs","definitionCN":"保险单或协议的有效期限结束","example":"The policy reached maturity and paid out a lump sum.","exampleCN":"这份保单到期并支付了一笔一次性款项。","why":"Contracts also have a ripening point, after which the obligations are settled or renewed.","whyCN":"合同同样有一个「熟透」的时点，此后义务结清或续约。"},{"no":"08","title":"Cellular and tissue maturation","titleCN":"细胞与组织的成熟","definition":"the process by which unspecialised cells acquire their adult structure and function","definitionCN":"未特化细胞获得成年结构与功能的过程","example":"The culture took three weeks to reach full maturity.","exampleCN":"这组培养物用了三周才完全成熟。","why":"In cell biology maturity means differentiation is complete, so the word shifts from the whole body to a single lineage.","whyCN":"在细胞生物学中，成熟意味着分化完成，这个词于是从整个身体转到单一细胞谱系。"},{"no":"09","title":"Soil and ecological maturity","titleCN":"土壤与生态的成熟","definition":"the developed state of a soil profile or an ecosystem that has reached a stable community","definitionCN":"土壤剖面发育完善，或生态系统达到稳定群落的状态","example":"The forest had reached maturity after a century without disturbance.","exampleCN":"这片森林在百年无干扰之后达到成熟。","why":"Ecology applies the same arc from young to developed, treating a climax community as the mature end point.","whyCN":"生态学套用同样的由幼到熟的弧线，把顶极群落视为成熟的终点。"}],"etymology":{"intro":{"en":"The word comes from Latin maturus, ripe or timely, and its noun maturitas. The Latin origin is clear; the exact date of the English noun's first use is approximate.","cn":"这个词来自拉丁语中表示「成熟的、适时的」形容词及其名词形式。拉丁来源清楚，英语名词的确切首见年代为约数。"},"items":[{"era":"LATIN MATURUS","en":"Maturus described fruit that had ripened and, by extension, anything that had come at the right time.","cn":"这个词先形容果实已经成熟，引申指任何「来得正是时候」的事物。"},{"era":"TIMELY AND MORNING","en":"The same old root is thought to lie behind matutinus, of the morning, so ripeness and early hour share an idea of the right moment.","cn":"一般认为同一个古老词根也藏在表示「早晨的」形容词背后，因此「成熟」与「清晨」共享「恰当时刻」这一观念。"},{"era":"LATIN MATURITAS","en":"The abstract noun named the state of being ripe or timely, which English took over almost unchanged.","cn":"这个抽象名词指成熟或适时的状态，英语几乎原样借入。"},{"era":"ENGLISH MATURITY","en":"English used the word first for physical ripeness and later for the due date of a debt.","cn":"英语先用它指生理成熟，后来才用于债务的到期。"},{"era":"FINANCIAL SENSE","en":"As bills and bonds became standard instruments, maturity moved from the ripening of fruit to the day a payment falls due.","cn":"当票据与债券成为标准工具，「成熟」便从果实成熟转到付款到期的日子。"},{"era":"TERM DATING","en":"The financial use is dated to the modern banking era, but the precise first attestation of the noun is uncertain.","cn":"金融用法可系于现代银行时代，但该名词的确切首见时间不确定。"}]},"similar":{"note":{"en":"The first group shares the stem or the finance compounds; the second group names related states of completion.","cn":"第一组共享词干或金融搭配；第二组是表示「完成」的相关状态。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mature","ipa":"/məˈtʃʊə/","tag":"same stem","definition":"The adjective and verb meaning fully developed or to become so.","definitionCN":"表示「成熟的」或「使成熟」的形容词与动词。"},{"word":"maturation","ipa":"/məˈtʃʊəreɪʃən/","tag":"same stem","definition":"The process of becoming mature, especially in biology.","definitionCN":"变为成熟的过程，尤用于生物学。"},{"word":"immaturity","ipa":"/ˌɪməˈtʃʊərəti/","tag":"derived opposite","definition":"The state of not yet being mature.","definitionCN":"尚未成熟的状态。"},{"word":"maturity date","ipa":"/məˈtʃʊərəti deɪt/","tag":"compound","definition":"The day on which a financial instrument falls due.","definitionCN":"金融工具到期的那一天。"},{"word":"yield to maturity","ipa":"/jiːld tə məˈtʃʊərəti/","tag":"compound","definition":"The return earned by holding a bond to its due date.","definitionCN":"持有债券至到期所获得的回报率。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ripeness","ipa":"/ˈraɪpnəs/","tag":"near meaning","definition":"The state of fruit being ready to eat or harvest.","definitionCN":"果实可以食用或采收的状态。"},{"word":"adulthood","ipa":"/əˈdʌlthʊd/","tag":"near meaning","definition":"The stage of being a fully grown person.","definitionCN":"成为完全成年人的阶段。"},{"word":"full development","ipa":"/fʊl ˌdiːvəˈləpmənt/","tag":"near meaning","definition":"The completion of growth or formation.","definitionCN":"生长或形成的完成。"},{"word":"due date","ipa":"/ˈdjuː deɪt/","tag":"near meaning","definition":"The date by which a payment or obligation must be met.","definitionCN":"付款或义务必须履行的日期。"},{"word":"expiry","ipa":"/ɪkˈspaɪəri/","tag":"near meaning","definition":"The end of the period for which something is valid.","definitionCN":"某物有效的期限结束。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the arc from fruit to character to finance; abstract ones treat maturity as a threshold rather than a feeling.","cn":"正常联想沿着从果实到性格再到金融的弧线展开；抽象联想把成熟看作阈值而非感受。"},"normal":[{"en":"Maturity begins as a fruit word: colour, sugar, texture, ready to pick.","cn":"成熟最初是果实词：颜色、糖度、质地，到了可采摘的程度。"},{"en":"The same word then describes a person who can wait and weigh consequences.","cn":"同一个词随后形容能等待、能权衡后果的人。"},{"en":"In finance the fruit becomes a bond, and ripe means payable.","cn":"在金融里，果实变成债券，「熟」就是「该付了」。"},{"en":"A maturity date is the day the ripening is written into a calendar.","cn":"到期日就是把「成熟」写进日历的那一天。"},{"en":"Cells and soils mature too, because every system has a developed end state.","cn":"细胞与土壤也会成熟，因为每个系统都有发育完成的状态。"}],"abstract":[{"en":"Maturity is not an age, it is the point where something stops needing to be finished.","cn":"成熟不是年龄，而是某物不再需要被完成的那一刻。"},{"en":"Every field keeps the same fruit metaphor: unripe, ripening, due.","cn":"每个领域都保留同一个果实隐喻：未熟、将熟、到期。"},{"en":"A threshold can be crossed quietly, which is why maturity is often noticed only afterwards.","cn":"阈值可以悄无声息地被跨过，所以成熟往往事后才被察觉。"}]},"examples":[{"en":"The grapes reach maturity in late September.","cn":"葡萄在九月下旬成熟。"},{"en":"The bond has a maturity of five years.","cn":"这只债券期限五年。"},{"en":"Emotional maturity matters more than age in this role.","cn":"在这个岗位上，情感成熟比年龄更重要。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「马球里提」——果子熟了才敢办「马球赛」，晚了就到期了：成熟、到期","word":"maturity"},"root":"来自拉丁语 maturus「成熟的、适时的」及其名词 maturitas，经法语进入英语。一般认为表示「早晨的」拉丁形容词也出自同一古老词根，因此「成熟」与「恰当时刻」共享一个观念。金融「到期」义属现代银行时代的引申，确切首见年代不确定。","sensesIntro":{"en":"Nine senses grow from one image of ripening: the body, the character, the crop, the debt, the date, the return, the contract, the cell and the soil.","cn":"九个义项都从一个「成熟」意象长出来：身体、性格、作物、债务、日期、回报、合同、细胞与土壤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sugar meter, a rising curve, a crate waiting at the end of the row.","cn":"核心意象：糖度计、上升的曲线、地头等着的果筐。"},"chain":["RIPENING","BODY READY","CHARACTER SETTLED","DEBT DUE","DATE AND RETURN","CELLS AND SOIL"],"branches":[{"senses":"01 · 03","en":"THE RIPENING CORE: body and crop both arrive at the point of being fully formed.","cn":"成熟内核：身体与作物都到达完全成形的时点。"},{"senses":"02","en":"THE CHARACTER: the same threshold applied to judgement and patience.","cn":"性格层面：同一阈值被用到判断力与耐心上。"},{"senses":"04 · 05 · 06","en":"THE FINANCIAL ARC: due, the date of due, and the return earned by waiting for it.","cn":"金融弧线：到期、到期日，以及等到期所获的回报。"},{"senses":"07 · 08","en":"THE OTHER COMPLETIONS: a contract's term ends, a cell's differentiation finishes.","cn":"其他完成形态：合同期限结束，细胞分化完成。"},{"senses":"09","en":"THE ECOLOGICAL END: a soil profile or a community reaches its developed state.","cn":"生态终点：土壤剖面或群落达到发育完成的状态。"}]},"affixes":{"intro":{"en":"The word is a Latin adjective plus an abstract noun ending, with English relatives built by negation and by prefixes of time.","cn":"这个词是拉丁形容词加抽象名词词尾，英语亲属词由否定与时间前缀构成。"},"latinIntro":{"en":"Latin supplies the adjective of ripeness, its abstract noun and the verb of ripening; English adds the ending -ity and the negative and anticipatory prefixes.","cn":"拉丁语提供了表示成熟的形容词、抽象名词与使成熟的动词；英语加上表示性质的词尾，以及否定与提前的前缀。"},"items":[{"word":"maturus","structure":"Latin adjective","meaning":"ripe, timely","meaningCN":"成熟的；适时的","example":"It described fruit at the right moment and then any timely thing.","exampleCN":"它先形容恰当时刻的果实，后指任何适时之物。"},{"word":"maturitas","structure":"Latin noun","meaning":"ripeness, timeliness","meaningCN":"成熟；适时","example":"The abstract noun passed into English almost unchanged.","exampleCN":"这个抽象名词几乎原样进入英语。"},{"word":"maturare","structure":"Latin verb","meaning":"to ripen, to make ready","meaningCN":"使成熟；使就绪","example":"The verb supplies the English process noun and verb.","exampleCN":"这个动词提供了英语的过程名词与动词。"},{"word":"-ity","structure":"Latin noun ending","meaning":"state or quality","meaningCN":"状态或性质","example":"It turns the adjective into the name of a state.","exampleCN":"它把形容词变成状态名称。"},{"word":"mature","structure":"English adjective","meaning":"fully developed","meaningCN":"完全发育的","example":"The shorter form drops the abstract ending.","exampleCN":"较短的形容词形式去掉了抽象词尾。"},{"word":"maturation","structure":"English noun","meaning":"the process of maturing","meaningCN":"成熟的过程","example":"The ending marks an ongoing process rather than a state.","exampleCN":"这个词尾标记进行中的过程而非状态。"},{"word":"im-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不","example":"It forms the adjective and noun for what has not ripened.","exampleCN":"它构成表示「尚未成熟」的形容词与名词。"},{"word":"pre-","structure":"Latin prefix","meaning":"before","meaningCN":"在……之前","example":"It marks a birth or event that comes before the due time.","exampleCN":"它标记早于应有时刻的出生或事件。"}],"latinEntries":[{"word":"maturus","structure":"Latin adjective","meaning":"ripe, timely","meaningCN":"成熟的；适时的"},{"word":"maturitas","structure":"Latin noun","meaning":"ripeness","meaningCN":"成熟"},{"word":"maturare","structure":"Latin verb","meaning":"to ripen","meaningCN":"使成熟"},{"word":"praematurus","structure":"Latin adjective","meaning":"too early","meaningCN":"过早的"}],"derivatives":[{"word":"mature","pos":"adj./v.","zh":"同一词根独立成词，义为「成熟的；使成熟」"},{"word":"maturation","pos":"n.","zh":"由动词加表示「过程」的词尾构成，义为「成熟过程；成熟」"},{"word":"immature","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不成熟的」"},{"word":"immaturity","pos":"n.","zh":"由否定前缀加本词构成，义为「不成熟；幼稚」"},{"word":"premature","pos":"adj.","zh":"由表示「之前」的前缀加形容词构成，义为「过早的；早产的」"},{"word":"maturities","pos":"n.","zh":"本词的复数形式，金融中指多笔不同期限的到期安排"}]}},{"word":"lifespan","ipa_uk":"/ˈlaɪfspæn/","ipa_us":"/ˈlaɪfspæn/","definition_zh":"寿命；使用寿命；存在期限；有效年限","definition_en":"the length of time that a living thing, an object or a system lasts or is expected to last","core_image":"一支被刻上刻度的旧温度计，两端各有一道标记，中间拉出一条时间轴","scene":"博物馆的展柜里放着一支旧温度计，旁边的标签写着它从出厂到报废之间的年份跨度。A simple label recorded the lifespan of the instrument from the day it was made to the day it failed.","sceneCN":"这里指器物从出厂到失效的使用寿命（第 4 个义项：产品与设备的使用期限）；句意为标签记下了这支仪器从制成到损坏的寿命。图中可辨识物件：展柜、旧温度计、刻度、纸质标签。","pos":[{"tag":"n.","zh":"名词：可数，指寿命或使用期限；常带表示所属的介词短语"}],"collocations":[{"phrase":"average lifespan","zh":"平均寿命"},{"phrase":"maximum lifespan","zh":"最长寿命；寿命上限"},{"phrase":"a lifespan of ten years","zh":"十年的寿命"},{"phrase":"extend the lifespan","zh":"延长寿命"},{"phrase":"shorten the lifespan","zh":"缩短寿命"},{"phrase":"lifespan of a species","zh":"物种的寿命"},{"phrase":"throughout its lifespan","zh":"在其整个寿命期内"}],"forms":[{"label":"名词原形","form":"lifespan"},{"label":"复数","form":"lifespans"},{"label":"分写变体","form":"life span"},{"label":"所有格","form":"lifespan's"},{"label":"定语用法","form":"lifespan + 名词"},{"label":"介词短语","form":"over a lifespan"}],"derivatives":[{"word":"life span","pos":"n.","zh":"分写形式，与本词同义，多见于较早的文本"},{"word":"lifespans","pos":"n.","zh":"本词复数，指多个物种或多种产品的寿命"},{"word":"lifetime","pos":"n.","zh":"由 life 与 time 构成的近义复合词，义为「一生；终身」"},{"word":"lifelong","pos":"adj.","zh":"由 life 与 long 构成，义为「终身的」"},{"word":"wingspan","pos":"n.","zh":"同一构词方式下的复合词，义为「翼展」"},{"word":"timespan","pos":"n.","zh":"同一构词方式下的复合词，义为「时间跨度」"}],"senses":[{"no":"01","title":"Maximum lifespan of a species","titleCN":"物种的寿命上限","definition":"the longest time that an individual of a species has been known to live under ideal conditions","definitionCN":"某一物种的个体在理想条件下已知能存活的最长时间","example":"The maximum lifespan of the bristlecone pine is measured in thousands of years.","exampleCN":"刺果松的寿命上限以千年计。","why":"Biologists separate the ceiling from the average because the oldest known individual marks the genetic limit of a species.","whyCN":"生物学家把上限与平均值分开，因为已知最老的个体标记着该物种的遗传极限。"},{"no":"02","title":"Average or expected lifespan","titleCN":"平均寿命与预期寿命","definition":"the typical number of years members of a group actually live, usually given as a mean","definitionCN":"某一群体成员实际存活的典型年数，通常以平均值表示","example":"Average lifespan in the region rose by nearly a decade after clean water arrived.","exampleCN":"清洁水源到位后，该地区的平均寿命提高了近十年。","why":"Public health needs a single summary number, and the mean of many lives provides it.","whyCN":"公共卫生需要一个概括性的数字，众多个体寿命的平均值正好提供它。"},{"no":"03","title":"An individual's lifetime","titleCN":"个体的一生","definition":"the whole period during which one person or animal is alive","definitionCN":"一个人或一只动物活着的整个时期","example":"Her lifespan covered two wars and the first moon landing.","exampleCN":"她的一生横跨两次战争与首次登月。","why":"The compound can also be read one life at a time, as a span with a beginning and an end.","whyCN":"这个复合词也可以一次只指一条生命，看作有起点与终点的一段时间。"},{"no":"04","title":"Product or device lifespan","titleCN":"产品与设备的使用寿命","definition":"the period for which a manufactured object remains usable before failure or replacement","definitionCN":"制成品在失效或更换之前保持可用的时期","example":"The pump has a lifespan of about eight years under normal load.","exampleCN":"这台泵在正常负荷下的使用寿命约为八年。","why":"Engineers borrowed the biological word because machines also wear out along a predictable curve.","whyCN":"工程师借用了生物学的词，因为机器也沿着可预测的曲线磨损。"},{"no":"05","title":"Battery and component lifespan","titleCN":"电池与部件的寿命","definition":"the number of charge cycles or operating hours a component delivers before its capacity falls below a threshold","definitionCN":"部件在容量降到阈值之前所能提供的充电循环次数或工作小时数","example":"Cycle testing is used to estimate the lifespan of the new cells.","exampleCN":"循环测试被用来估算新电芯的寿命。","why":"A component's life is counted in cycles rather than years, so the word gains a technical unit.","whyCN":"部件的寿命以循环而非年计数，这个词因此获得了技术性的计量单位。"},{"no":"06","title":"Lifespan of a star","titleCN":"恒星寿命","definition":"the time a star spends fusing hydrogen and then heavier elements before it ends as a remnant","definitionCN":"恒星从开始聚变氢到最终成为残骸所经历的时间","example":"A massive star has a much shorter lifespan than a small one.","exampleCN":"大质量恒星的寿命远短于小质量恒星。","why":"Astronomy applies the same span to objects that were never alive, because their evolution has a clear start and finish.","whyCN":"天文学把同一跨度用到了从未有生命的天体上，因为它们的演化有明确的开始与结束。"},{"no":"07","title":"Lifespan of an institution or custom","titleCN":"机构与习俗的存续期","definition":"the period during which an organisation, language or practice continues to exist","definitionCN":"组织、语言或习俗持续存在的时期","example":"The guild had a lifespan of three centuries before it dissolved.","exampleCN":"这个行会存在了三个世纪才解散。","why":"Social scientists extend the word to anything that is founded, maintained and finally ended.","whyCN":"社会科学家把这个词扩展到任何被创立、维持并最终结束的事物。"},{"no":"08","title":"Lifespan of stored data","titleCN":"数据与载体的保存寿命","definition":"the time for which a storage medium keeps its contents readable without error","definitionCN":"存储介质在不出现错误的情况下保持内容可读的时间","example":"Archivists test the lifespan of optical discs before committing to them.","exampleCN":"档案人员在使用光盘之前会测试其保存寿命。","why":"Digital preservation turned the word into a specification: how long before the bits decay.","whyCN":"数字保存把这个词变成了一项指标：比特在多长时间后开始劣化。"},{"no":"09","title":"Working lifespan","titleCN":"职业寿命与有效工作年限","definition":"the number of years a person can remain in a demanding job or profession","definitionCN":"一个人能留在高强度岗位或专业领域工作的年数","example":"Better recovery routines have extended the working lifespan of many athletes.","exampleCN":"更好的恢复安排延长了许多运动员的职业寿命。","why":"Careers also begin, peak and end, so the biological span is applied to employment.","whyCN":"职业生涯同样有开始、顶峰与结束，于是生物学的跨度被用到就业上。"}],"etymology":{"intro":{"en":"The word is a plain English compound of life and span, whose second element first meant the distance from thumb to little finger. The source is clear; the date of the compound's first recorded use is approximate.","cn":"这个词是 life 与 span 组成的普通英语复合词，其中 span 最初指拇指到小指之间的一拃长度。来源清楚，复合词的确切首见年代为约数。"},"items":[{"era":"OLD ENGLISH SPANN","en":"Spann named a unit of length, the stretch between an outstretched thumb and the little finger.","cn":"这个词原是一个长度单位，指张开拇指与小指之间的一拃。"},{"era":"FROM LENGTH TO DURATION","en":"From a hand's width the sense widened to any stretch or extent, and then to a stretch of time.","cn":"从一只手的宽度，词义扩展到任何伸展或范围，再扩展到一段时间。"},{"era":"ENGLISH LIFE","en":"Life has meant a living being's existence since the oldest English records.","cn":"自最早的英语文献起，这个词就指活物的存在。"},{"era":"THE COMPOUND","en":"Life and span joined to name the length of one life, first recorded in American usage in the mid-nineteenth century.","cn":"两者结合，用来指一条生命的长度，最早见于十九世纪中期的美国用法。"},{"era":"EXTENSION TO OBJECTS","en":"The compound then spread from creatures to machines, batteries, stars and institutions.","cn":"此后这个复合词从生物扩展到机器、电池、恒星与机构。"},{"era":"DATING THE FIRST USE","en":"Reference works differ by decades on the earliest citation, so the first date is best given as approximate.","cn":"各类辞书对最早引例的年份相差数十年，因此首见年代只能给约数。"}]},"similar":{"note":{"en":"The first group shares the second element or the same compound pattern; the second group names other measures of duration.","cn":"第一组共享第二个构词成分或相同的复合方式；第二组表示其他「时长」概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"life span","ipa":"/laɪf spæn/","tag":"spelling variant","definition":"The two-word spelling of the same compound.","definitionCN":"同一复合词的分写形式。"},{"word":"wingspan","ipa":"/ˈwɪŋspæn/","tag":"same pattern","definition":"The distance from one wing tip to the other.","definitionCN":"从一侧翼尖到另一侧翼尖的距离。"},{"word":"timespan","ipa":"/ˈtaɪmspæn/","tag":"same pattern","definition":"A period of time between two points.","definitionCN":"两个时点之间的一段时间。"},{"word":"attention span","ipa":"/əˈtenʃən spæn/","tag":"same pattern","definition":"How long a person can concentrate on one task.","definitionCN":"一个人能专注于一项任务的时间长度。"},{"word":"lifetime","ipa":"/ˈlaɪftaɪm/","tag":"same pattern","definition":"The whole period during which someone is alive.","definitionCN":"某人活着的整个时期。"}]},{"heading":"NEAR MEANING","entries":[{"word":"life expectancy","ipa":"/laɪf ɪkˈspektənsi/","tag":"near meaning","definition":"The number of years a person is statistically expected to live.","definitionCN":"按统计预期一个人能活的年数。"},{"word":"longevity","ipa":"/lɒnˈdʒevəti/","tag":"near meaning","definition":"Long duration of life, especially an unusually long one.","definitionCN":"长寿，尤指异常长的寿命。"},{"word":"duration","ipa":"/djʊˈreɪʃən/","tag":"near meaning","definition":"The length of time during which something continues.","definitionCN":"某事物持续的时长。"},{"word":"service life","ipa":"/ˈsɜːvɪs laɪf/","tag":"near meaning","definition":"The period an object remains usable in service.","definitionCN":"物体在使用中保持可用的期限。"},{"word":"shelf life","ipa":"/ʃelf laɪf/","tag":"near meaning","definition":"The time food or a product stays good before spoiling.","definitionCN":"食品或产品在变质前保持良好状态的时间。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations run from the hand-span measure to a life, then to machines and stars; abstract ones treat the word as a bounded interval.","cn":"正常联想从「一拃」的量度走到一条生命，再到机器与恒星；抽象联想把这个词看作一段有界的区间。"},"normal":[{"en":"Span first meant a hand's width, thumb to little finger.","cn":"表示跨度的那个成分最初指一只手的宽度，从拇指到小指。"},{"en":"Stretch the hand into a timeline and you get a life span.","cn":"把手张开拉成一条时间轴，就得到了生命周期。"},{"en":"A pump outlives its warranty but still has a lifespan.","cn":"泵的保修期早过了，但它仍有使用寿命。"},{"en":"A battery counts its life in cycles, not birthdays.","cn":"电池的寿命以循环计，而不是以生日计。"},{"en":"Stars are not alive, yet they too have a lifespan.","cn":"恒星没有生命，却同样有寿命。"}],"abstract":[{"en":"A lifespan is not a number but an interval with two edges.","cn":"寿命不是一个数字，而是一段有两条边的区间。"},{"en":"Anything founded can also be spent, which is why institutions borrow the word.","cn":"凡被创立者皆可耗尽，机构因此也借用这个词。"},{"en":"Knowing the span changes how you plan the middle of it.","cn":"知道跨度有多长，会改变你对中间那段日子的安排。"}]},"examples":[{"en":"The average lifespan of the species is about twelve years.","cn":"该物种的平均寿命约为十二年。"},{"en":"Regular maintenance can double the lifespan of the machine.","cn":"定期维护能让这台机器的寿命翻倍。"},{"en":"Researchers compared the lifespan of wild and captive animals.","cn":"研究人员比较了野生与圈养动物的寿命。"}],"dict_mnemonic":{"note":"拆分记忆 · 非词源","text":"life（生命）+ span（跨度）——生命的跨度就是寿命","word":"lifespan"},"root":"由英语 life「生命」与 span「跨度」复合而成。span 源自古英语 spann，本指拇指到小指张开的一拃长度，后引申为任何延伸范围与时间跨度。复合词最早见于十九世纪中期的美国用法，确切首见年代不确定。","sensesIntro":{"en":"Nine senses extend one measure of duration from a species to a single life, then to pumps, batteries, stars, guilds and archives.","cn":"九个义项把同一个「时长」量度从物种延伸到单个生命，再到泵、电池、恒星、行会与档案。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruler laid along a life, with a mark at each end.","cn":"核心意象：一把尺子贴着一条生命摆放，两端各有一道刻痕。"},"chain":["SPECIES CEILING","EXPECTED YEARS","ONE LIFE","MACHINES","STARS AND DATA","WORKING YEARS"],"branches":[{"senses":"01 · 02","en":"THE BIOLOGICAL RANGE: the ceiling a species can reach and the average its members actually reach.","cn":"生物学区间：物种能达到的上限与成员实际达到的平均值。"},{"senses":"03","en":"THE SINGLE SPAN: one person's whole stretch of being alive.","cn":"单条跨度：一个人活着的整段时光。"},{"senses":"04 · 05","en":"THE ENGINEERED SPAN: a product's usable years and a component's counted cycles.","cn":"工程跨度：产品的可用年数与部件的循环计数。"},{"senses":"06 · 08","en":"THE NON-LIVING SPAN: a star's fusion years and a disc's readable years.","cn":"非生命跨度：恒星的聚变年数与光盘的可读年数。"},{"senses":"07 · 09","en":"THE SOCIAL SPAN: how long an institution lasts and how long a career lasts.","cn":"社会跨度：机构能存续多久，职业能维持多久。"}]},"affixes":{"intro":{"en":"The word is an English compound rather than a prefixed form, so its parts are two free morphemes.","cn":"这个词是英语复合词而非前缀派生形式，因此它的组成部分是两个自由语素。"},"latinIntro":{"en":"Its second element goes back to an Old English measure of length; the first is the ordinary word for being alive.","cn":"第二个成分可追溯到古英语的长度量度；第一个成分就是表示「活着」的常用词。"},"items":[{"word":"līf","structure":"Old English noun","meaning":"life, existence","meaningCN":"生命；存在","example":"It is the first element and the oldest word for being alive.","exampleCN":"它是第一个成分，也是表示活着的最古老词。"},{"word":"spann","structure":"Old English noun","meaning":"a hand's span, a measure","meaningCN":"一拃；一种长度单位","example":"The word began as a body-based unit of length.","exampleCN":"这个词最初是以身体为依据的长度单位。"},{"word":"span","structure":"English noun","meaning":"extent, stretch of time","meaningCN":"范围；时间跨度","example":"Its meaning widened from width to duration.","exampleCN":"它的词义从宽度扩展到了时长。"},{"word":"lifespan","structure":"English compound","meaning":"the length of a life","meaningCN":"寿命","example":"The compound is the base form used in this entry.","exampleCN":"这个复合词是本词条的基本形式。"},{"word":"wingspan","structure":"English compound","meaning":"distance between wing tips","meaningCN":"翼展","example":"It shows the same span pattern applied to wings.","exampleCN":"它展示了同一构词方式用在翅膀上。"},{"word":"timespan","structure":"English compound","meaning":"a period between two points","meaningCN":"时间跨度","example":"It applies the pattern to time itself.","exampleCN":"它把这一方式用到时间本身。"},{"word":"attention span","structure":"English compound","meaning":"how long attention holds","meaningCN":"注意力持续时间","example":"The pattern extends to mental endurance.","exampleCN":"这一方式延伸到心理耐力。"},{"word":"lifetime","structure":"English compound","meaning":"the whole of a life","meaningCN":"一生；终身","example":"A near-synonym built from the same first element.","exampleCN":"由同一第一个成分构成的近义词。"},{"word":"lifelong","structure":"English compound","meaning":"lasting for a life","meaningCN":"终身的","example":"The adjective shows the first element in another compound.","exampleCN":"这个形容词展示了第一个成分的另一复合用法。"}],"latinEntries":[],"derivatives":[{"word":"life span","pos":"n.","zh":"分写形式，与本词同义，多见于较早的文本"},{"word":"lifespans","pos":"n.","zh":"本词复数，指多个物种或多种产品的寿命"},{"word":"lifetime","pos":"n.","zh":"由 life 与 time 构成的近义复合词，义为「一生；终身」"},{"word":"lifelong","pos":"adj.","zh":"由 life 与 long 构成，义为「终身的」"},{"word":"wingspan","pos":"n.","zh":"同一构词方式下的复合词，义为「翼展」"},{"word":"timespan","pos":"n.","zh":"同一构词方式下的复合词，义为「时间跨度」"}]}},{"word":"senescence","ipa_uk":"/sɪˈnesns/","ipa_us":"/sɪˈnesns/","definition_zh":"衰老；老化；（细胞的）衰老状态；老年期","definition_en":"the process or state of growing old, especially the biological decline of cells and organisms","core_image":"一片由绿转黄的银杏叶，叶脉清晰，叶柄旁放着一枚放大镜","scene":"公园的银杏林里，叶子由绿转黄，管理员蹲下捡起一片开始褪色的叶子夹进标本册。Autumn senescence turns the whole grove gold before the leaves drop.","sceneCN":"这里指植物与叶片的衰老（第 4 个义项：叶片在脱落前发生的有序衰退）；句意为秋天的衰老过程让整片林子转黄，之后叶子才落下。图中可辨识物件：银杏叶、叶脉、标本册、放大镜。","pos":[{"tag":"n.","zh":"名词：不可数，指衰老的过程或状态；生物学中特指细胞停止分裂的状态"}],"collocations":[{"phrase":"cellular senescence","zh":"细胞衰老"},{"phrase":"replicative senescence","zh":"复制性衰老"},{"phrase":"the onset of senescence","zh":"衰老的开始"},{"phrase":"delay senescence","zh":"延缓衰老"},{"phrase":"senescence-associated","zh":"与衰老相关的"},{"phrase":"programmed senescence","zh":"程序性衰老"},{"phrase":"senescence marker","zh":"衰老标志物"}],"forms":[{"label":"名词原形","form":"senescence"},{"label":"复数（罕见）","form":"senescences"},{"label":"相关形容词","form":"senescent"},{"label":"相关动词","form":"senesce"},{"label":"定语用法","form":"senescence + 名词"},{"label":"介词短语","form":"during senescence"}],"derivatives":[{"word":"senescent","pos":"adj.","zh":"由动词加表示「正在……的」词尾构成，义为「衰老的；老化的」"},{"word":"senesce","pos":"v.","zh":"去掉名词词尾得到的动词，义为「变老；开始衰老」"},{"word":"senility","pos":"n.","zh":"同一词根经另一形容词路径形成的名词，义为「衰老；老态」"},{"word":"senile","pos":"adj.","zh":"同一词根的形容词，义为「年老的；老年性的」"},{"word":"immunosenescence","pos":"n.","zh":"由表示「免疫」的成分加本词构成，义为「免疫衰老」"},{"word":"senolytic","pos":"adj./n.","zh":"由本词加表示「溶解、清除」的成分构成，指清除衰老细胞的药物"}],"senses":[{"no":"01","title":"Cellular senescence","titleCN":"细胞衰老","definition":"a stable state in which a cell stops dividing but remains alive and secretes signalling molecules","definitionCN":"细胞停止分裂却仍然存活、并分泌信号分子的稳定状态","example":"Cellular senescence is marked by a permanent exit from the cell cycle.","exampleCN":"细胞衰老的标志是永久退出细胞周期。","why":"The word names a controlled programme, not passive wear, which is why biology adopted it for cells that refuse to divide.","whyCN":"这个词命名的是一套受控程序而非被动磨损，因此生物学用它指拒绝分裂的细胞。"},{"no":"02","title":"Organismal ageing","titleCN":"个体衰老","definition":"the gradual loss of function that living things undergo as they grow older","definitionCN":"生物随年龄增长而逐渐丧失功能的过程","example":"Senescence in the whole organism brings a steady loss of reserve capacity.","exampleCN":"整个机体的衰老带来储备能力的逐步丧失。","why":"At the level of the body the word covers every system at once, from skin to kidney.","whyCN":"在身体层面，这个词同时涵盖从皮肤到肾脏的每一个系统。"},{"no":"03","title":"Replicative senescence","titleCN":"复制性衰老","definition":"the permanent arrest that cells enter after a fixed number of divisions, known as the Hayflick limit","definitionCN":"细胞在完成固定次数分裂后进入的永久停滞，即海弗利克极限","example":"Replicative senescence was shown by growing fibroblasts until they stopped dividing.","exampleCN":"复制性衰老是通过培养成纤维细胞直到其停止分裂而得到证明的。","why":"Counting divisions gave ageing a measurable clock, and the word became the name of that clock's end.","whyCN":"计数分裂次数为衰老提供了可测量的钟表，这个词就成了那只钟走到尽头的名称。"},{"no":"04","title":"Plant and leaf senescence","titleCN":"植物与叶片衰老","definition":"the ordered breakdown of a leaf or whole plant before it sheds parts or dies back","definitionCN":"叶片或整株植物在脱落或枯死之前发生的有序分解","example":"Autumn senescence turns the whole grove gold before the leaves drop.","exampleCN":"秋天的衰老过程让整片林子转黄，随后叶子才落下。","why":"In plants the process is scheduled and nutrient-recycling, so the word carries no sense of failure.","whyCN":"在植物身上这一过程是有计划的养分回收，因此这个词不含「衰败」的贬义。"},{"no":"05","title":"Demographic senescence","titleCN":"人口老龄化","definition":"the rising share of elderly people within a population","definitionCN":"一个群体中老年人所占比例不断上升","example":"Demographic senescence has reshaped the country's labour market.","exampleCN":"人口老龄化重塑了该国的劳动力市场。","why":"Demography borrowed the biological noun to describe what happens when a whole population grows older.","whyCN":"人口学借用这个生物学名词，描述整个人口变老时发生的事。"},{"no":"06","title":"Senescence in disease","titleCN":"衰老与疾病","definition":"the accumulation of senescent cells that drive inflammation and chronic disease","definitionCN":"衰老细胞的堆积推动炎症与慢性疾病","example":"Senescence in the tissue is now treated as a target for new drugs.","exampleCN":"组织中的衰老现象如今被视为新药的靶点。","why":"Once senescent cells were linked to illness, the word moved from description to a medical target.","whyCN":"当衰老细胞与疾病建立联系后，这个词便从描述变成了医学靶点。"},{"no":"07","title":"Old age as a stage","titleCN":"老年期","definition":"the later part of life, described in formal or literary writing","definitionCN":"人生的后期阶段，多用于正式或文学性表达","example":"The essay describes senescence as a season rather than a single hour.","exampleCN":"这篇文章把老年期描述成一个季节，而不是一个时辰。","why":"Before biology claimed the word, it simply meant the state of being old, and that literary sense survives.","whyCN":"在生物学占用这个词之前，它只表示年老的状态，这一文学义至今仍在。"},{"no":"08","title":"Institutional senescence","titleCN":"机构的老化","definition":"the loss of adaptability in an organisation that has stopped renewing itself","definitionCN":"组织停止自我更新后失去适应能力","example":"Institutional senescence set in once the same committee approved everything.","exampleCN":"自从同一个委员会审批所有事项，机构的老化就开始了。","why":"Organisations age in a recognisable way, so the biological noun is applied to them by analogy.","whyCN":"组织会以可辨识的方式变老，因此人们用类比把这个生物学名词用到了它们身上。"},{"no":"09","title":"Immunosenescence","titleCN":"免疫衰老","definition":"the age-related decline in the immune system's ability to respond to new threats","definitionCN":"免疫系统随年龄增长而对新威胁反应减弱","example":"Immunosenescence explains why older patients respond less well to some vaccines.","exampleCN":"免疫衰老解释了为何年长患者对某些疫苗反应较弱。","why":"A single branch of the immune system ages on its own schedule, and the compound names it precisely.","whyCN":"免疫系统中有一个分支按自己的时间表衰老，这个复合词精确地命名了它。"}],"etymology":{"intro":{"en":"The word comes from Latin senescere, to begin to grow old, built on senex, an old man. The Latin source is clear; the exact year the English noun entered use is approximate.","cn":"这个词来自拉丁语中表示「开始变老」的动词，其根是表示「老人」的名词。拉丁来源清楚，英语名词进入使用的确切年份为约数。"},"items":[{"era":"LATIN SENEX","en":"Senex meant an old man and stands behind senior and senate as well.","cn":"这个词指老年男子，也是「年长的」与「元老院」等词的根源。"},{"era":"LATIN SENESCERE","en":"The verb added an inceptive ending to mean to begin to grow old, stressing the start of the process.","cn":"这个动词加上表示「开始」的词尾，意为「开始变老」，强调过程的起点。"},{"era":"LATIN SENESCENTIA","en":"The abstract noun named the process itself rather than the person who undergoes it.","cn":"这个抽象名词命名的是过程本身，而非经历过程的人。"},{"era":"ENGLISH ENTRY","en":"English adopted the noun in the seventeenth century for the state of being old.","cn":"英语在十七世纪借入这个名词，用来表示年老的状态。"},{"era":"NARROWING IN BIOLOGY","en":"Twentieth-century biology narrowed the word to a programmed process with measurable steps.","cn":"二十世纪的生物学把词义收窄为有可测步骤的程序性过程。"},{"era":"THE CELLULAR TURN","en":"When cells were found to stop dividing for good, the same noun was attached to that arrest.","cn":"当人们发现细胞会永久停止分裂，同一个名词便被用到了这种停滞上。"}]},"similar":{"note":{"en":"The first group shares the Latin root senex; the second group names ageing and decline in plainer words.","cn":"第一组共享表示「老人」的拉丁词根；第二组是用更朴素的词表示衰老与衰退。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"senescent","ipa":"/sɪˈnesnt/","tag":"same root","definition":"The adjective meaning growing old or having stopped dividing.","definitionCN":"表示「正在变老」或「已停止分裂」的形容词。"},{"word":"senesce","ipa":"/sɪˈnes/","tag":"same root","definition":"The verb meaning to begin to grow old.","definitionCN":"表示「开始变老」的动词。"},{"word":"senility","ipa":"/sɪˈnɪləti/","tag":"same root","definition":"The state of being old, often with weakened mental powers.","definitionCN":"年老的状态，常含心智衰退之意。"},{"word":"senile","ipa":"/ˈsiːnaɪl/","tag":"same root","definition":"Old and showing the effects of age.","definitionCN":"年老的并显出衰老影响。"},{"word":"senior","ipa":"/ˈsiːniə/","tag":"same root","definition":"Older or higher in rank.","definitionCN":"年长的或级别较高的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ageing","ipa":"/ˈeɪdʒɪŋ/","tag":"near meaning","definition":"The process of growing older.","definitionCN":"变老的过程。"},{"word":"decline","ipa":"/dɪˈklaɪn/","tag":"near meaning","definition":"A gradual loss of strength or quality.","definitionCN":"力量或质量的逐渐下降。"},{"word":"deterioration","ipa":"/dɪˌtɪəriəˈreɪʃən/","tag":"near meaning","definition":"The process of becoming worse.","definitionCN":"变得更差的过程。"},{"word":"old age","ipa":"/əʊld eɪdʒ/","tag":"near meaning","definition":"The later part of a person's life.","definitionCN":"人生的后期。"},{"word":"withering","ipa":"/ˈwɪðərɪŋ/","tag":"near meaning","definition":"Shrinking and drying up, as a plant does.","definitionCN":"像植物那样萎缩干枯。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the leaf, the cell and the population; abstract ones treat senescence as a scheduled programme rather than a breakdown.","cn":"正常联想沿着叶片、细胞与人群展开；抽象联想把衰老看作被安排好的程序而非崩坏。"},"normal":[{"en":"A leaf yellows on schedule, and that schedule is senescence.","cn":"叶子按时变黄，这个时间表就是衰老。"},{"en":"A cell that stops dividing but stays alive is senescent.","cn":"停止分裂却仍活着的细胞就是衰老细胞。"},{"en":"The Hayflick limit is the cell's built-in countdown.","cn":"海弗利克极限就是细胞自带的倒计时。"},{"en":"An ageing population is senescence written at the scale of a country.","cn":"人口老龄化就是把衰老写到一个国家的尺度上。"},{"en":"The immune system ages too, and the compound is immunosenescence.","cn":"免疫系统也会衰老，这个复合词就是免疫衰老。"}],"abstract":[{"en":"Senescence is not damage; it is a programme that damage can accelerate.","cn":"衰老不是损伤本身，而是一套可被损伤加速的程序。"},{"en":"Every system that renews itself must also decide when to stop.","cn":"每个能自我更新的系统都必须决定何时停止。"},{"en":"Ageing is the price of having a schedule at all.","cn":"变老，是拥有时间表所付出的代价。"}]},"examples":[{"en":"Senescence is now studied as an active programme rather than simple wear.","cn":"衰老如今被当作主动程序而非单纯磨损来研究。"},{"en":"The forest showed clear signs of senescence after the dry decade.","cn":"干旱十年之后，这片森林显出明显的衰老迹象。"},{"en":"Researchers now treat senescence as a target rather than an inevitable fate.","cn":"研究人员如今把衰老当作可干预的目标，而非不可改变的归宿。"}],"dict_mnemonic":{"note":"词根记忆 · 非词源","text":"sen（老）+ escence（开始成为）——开始变老：衰老","word":"senescence"},"root":"来自拉丁语 senescere「开始变老」，其根为 senex「老人」，与 senior、senate 同源。拉丁来源清楚，英语名词约在十七世纪进入使用，确切年份不确定；二十世纪后词义收窄为生物学的程序性衰老。","sensesIntro":{"en":"Nine senses carry one root meaning of growing old across cells, bodies, leaves, populations, institutions and the immune system.","cn":"九个义项把「变老」这一词根含义贯穿细胞、身体、叶片、人群、机构与免疫系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a yellowing leaf with a visible vein map and a lens beside it.","cn":"核心意象：一片正在变黄的叶子，叶脉清晰，旁边放着放大镜。"},"chain":["CELL ARREST","BODY DECLINE","DIVISION LIMIT","LEAF FALL","AGEING POPULATION","INSTITUTIONS AND IMMUNITY"],"branches":[{"senses":"01 · 03","en":"THE CELLULAR CORE: a permanent exit from division, reached after a counted number of cycles.","cn":"细胞内核：永久退出分裂，且发生在计数过的若干循环之后。"},{"senses":"02","en":"THE WHOLE BODY: every organ losing reserve at once.","cn":"整个身体：每个器官同时失去储备。"},{"senses":"04","en":"THE PLANT VERSION: an ordered breakdown that recycles nutrients before shedding.","cn":"植物版本：脱落前发生的有序分解并回收养分。"},{"senses":"05 · 07","en":"THE HUMAN ARC: a population growing older and a single life reaching its late stage.","cn":"人类弧线：人口整体变老，以及单条生命进入晚期。"},{"senses":"06 · 08 · 09","en":"THE TARGETS: senescent cells in disease, institutions losing adaptability, and an ageing immune system.","cn":"靶点层面：疾病中的衰老细胞、失去适应力的机构，以及衰老的免疫系统。"}]},"affixes":{"intro":{"en":"One Latin root, senex, yields a verb of growing old, an abstract noun and a family of adjectives.","cn":"一个拉丁词根「老人」衍生出表示变老的动词、抽象名词以及一组形容词。"},"latinIntro":{"en":"Latin supplies the noun of age, the inceptive verb and the adjective of old age; English adds the abstract ending and later compounds.","cn":"拉丁语提供了表示年老的名称、表示开始变老的动词与老年形容词；英语加上抽象名词词尾，后来又构成复合词。"},"items":[{"word":"senex","structure":"Latin noun","meaning":"old man","meaningCN":"老人","example":"The root also stands behind words for elders and councils of elders.","exampleCN":"这个词根也藏在表示长者与长者议事会的词背后。"},{"word":"senescere","structure":"Latin verb","meaning":"to begin to grow old","meaningCN":"开始变老","example":"The inceptive ending stresses the start of ageing.","exampleCN":"表示「开始」的词尾强调衰老的起点。"},{"word":"senescentia","structure":"Latin noun","meaning":"a growing old","meaningCN":"变老；衰老","example":"The abstract noun passed into English as senescence.","exampleCN":"这个抽象名词以「衰老」的形式进入英语。"},{"word":"senilis","structure":"Latin adjective","meaning":"of old age","meaningCN":"老年的","example":"It supplies the English adjectives for senile conditions.","exampleCN":"它提供了英语中表示老年性状态的形容词。"},{"word":"-escent","structure":"Latin suffix","meaning":"becoming, beginning to be","meaningCN":"正在成为……的","example":"It marks a process that has started but not finished.","exampleCN":"它标记已经开始但尚未完成的过程。"},{"word":"-ence","structure":"Latin suffix","meaning":"state or quality","meaningCN":"状态或性质","example":"It turns the participle into the name of a state.","exampleCN":"它把分词变成状态名称。"},{"word":"senescent","structure":"English adjective","meaning":"growing old","meaningCN":"衰老的","example":"The adjective keeps the inceptive sense of starting to age.","exampleCN":"这个形容词保留了「开始变老」的起始含义。"},{"word":"senesce","structure":"English verb","meaning":"to grow old","meaningCN":"变老","example":"The verb is a back formation from the noun.","exampleCN":"这个动词是从名词逆构出来的。"},{"word":"immunosenescence","structure":"English compound","meaning":"ageing of immunity","meaningCN":"免疫衰老","example":"A modern compound joins immunity to the old noun.","exampleCN":"一个现代复合词把免疫与这个古老名词连在一起。"}],"latinEntries":[{"word":"senex","structure":"Latin noun","meaning":"old man","meaningCN":"老人"},{"word":"senescere","structure":"Latin verb","meaning":"to begin to grow old","meaningCN":"开始变老"},{"word":"senescentia","structure":"Latin noun","meaning":"a growing old","meaningCN":"衰老"},{"word":"senilis","structure":"Latin adjective","meaning":"of old age","meaningCN":"老年的"}],"derivatives":[{"word":"senescent","pos":"adj.","zh":"由动词加表示「正在……的」词尾构成，义为「衰老的；老化的」"},{"word":"senesce","pos":"v.","zh":"去掉名词词尾得到的动词，义为「变老；开始衰老」"},{"word":"senility","pos":"n.","zh":"同一词根经另一形容词路径形成的名词，义为「衰老；老态」"},{"word":"senile","pos":"adj.","zh":"同一词根的形容词，义为「年老的；老年性的」"},{"word":"immunosenescence","pos":"n.","zh":"由表示「免疫」的成分加本词构成，义为「免疫衰老」"},{"word":"senolytic","pos":"adj./n.","zh":"由本词加表示「溶解、清除」的成分构成，指清除衰老细胞的药物"}]}},{"word":"gravitational field","ipa_uk":"/ˌɡrævɪˈteɪʃənl fiːld/","ipa_us":"/ˌɡrævɪˈteɪʃənəl fiːld/","definition_zh":"引力场；重力场；由质量产生的、对其他质量施加吸引力的空间区域","definition_en":"the region of space around a mass in which another mass experiences an attractive force","core_image":"一张网格状的时空示意图，中间压着一颗小球，网格向下凹陷","scene":"天文台里，研究员盯着屏幕上绕月探测器轨迹的弯曲弧线，那弧度正是看不见的力造成的。The probe's path bent as it crossed the moon's gravitational field.","sceneCN":"这里指卫星周围的引力场（第 4 个义项：行星或卫星质量所产生的引力作用区域）；句意为探测器穿过月球引力场时轨迹发生了弯曲。图中可辨识物件：轨迹屏、弯曲弧线、月球轮廓、控制台。","pos":[{"tag":"n.","zh":"名词短语：可数，指某质量周围的引力作用区域；常带表示来源的介词短语"}],"collocations":[{"phrase":"the earth's gravitational field","zh":"地球引力场"},{"phrase":"gravitational field strength","zh":"引力场强度"},{"phrase":"a uniform gravitational field","zh":"匀强引力场"},{"phrase":"lines of gravitational field","zh":"引力场线"},{"phrase":"map the gravitational field","zh":"测绘引力场"},{"phrase":"a strong gravitational field","zh":"强引力场"},{"phrase":"the gravitational field of a planet","zh":"行星的引力场"}],"forms":[{"label":"短语原形","form":"gravitational field"},{"label":"复数","form":"gravitational fields"},{"label":"定语用法","form":"gravitational field + 名词"},{"label":"介词短语","form":"in a gravitational field"},{"label":"构成成分一","form":"gravitational"},{"label":"构成成分二","form":"field"},{"label":"相关名词","form":"gravitation"}],"derivatives":[{"word":"gravitation","pos":"n.","zh":"由拉丁动词加表示「作用、过程」的词尾构成，义为「引力作用」"},{"word":"gravitational","pos":"adj.","zh":"由本词组的第一成分构成，义为「引力的；重力的」"},{"word":"gravitate","pos":"v.","zh":"同一词根的动词，义为「受引力作用；被吸引」"},{"word":"gravity","pos":"n.","zh":"同一词根的名词，义为「重力；严重性」"},{"word":"graviton","pos":"n.","zh":"由本词根加表示「粒子」的词尾构成，指假设中的引力子"},{"word":"gravimeter","pos":"n.","zh":"由本词根加表示「测量仪器」的成分构成，义为「重力仪」"}],"senses":[{"no":"01","title":"A region of gravitational influence","titleCN":"引力场的基本定义","definition":"the region around a mass in which its attraction can be detected by another body","definitionCN":"质量周围能被另一物体检测到其吸引作用的区域","example":"A gravitational field is the region around a mass where another mass feels a pull.","exampleCN":"引力场是质量周围另一质量能感到吸引的区域。","why":"Physics needed a way to speak about action at a distance without naming a messenger, so it described the space itself.","whyCN":"物理学需要一种不必指明传递者也能谈论超距作用的说法，于是转而描述空间本身。"},{"no":"02","title":"Field strength","titleCN":"引力场强度","definition":"the force per unit mass at a point, equal to the local acceleration of a freely falling body","definitionCN":"某点单位质量所受的力，等于自由落体在该处的加速度","example":"The gravitational field strength at the surface is about ten newtons per kilogram.","exampleCN":"地表的引力场强度约为每千克十牛顿。","why":"Once the field is a quantity, it can be measured, graphed and compared between planets.","whyCN":"一旦场成为可量化的量，就能测量、绘图并在行星之间比较。"},{"no":"03","title":"Earth's field","titleCN":"地球引力场","definition":"the field produced by the earth, which defines local vertical and the weight of objects","definitionCN":"地球产生的场，定义当地的竖直方向与物体的重量","example":"Satellites stay in orbit because they move through the earth's gravitational field.","exampleCN":"卫星之所以留在轨道上，是因为它们在穿过地球引力场。","why":"Everyday weight is the most familiar reading of the field, which is why the concept feels intuitive.","whyCN":"日常的重量就是对这个场最熟悉的读数，因此这一概念显得直观。"},{"no":"04","title":"A planet's or moon's field","titleCN":"行星或卫星的引力场","definition":"the field around a particular body, whose shape reveals how mass is distributed inside it","definitionCN":"围绕某一天体的场，其形状能揭示其内部质量分布","example":"The probe mapped the gravitational field of the moon in fine detail.","exampleCN":"探测器精细地测绘了月球的引力场。","why":"A field is not a perfect sphere when the body is lumpy, and those bumps become a map of what lies beneath.","whyCN":"当天体质量分布不均时，场并非完美球形，这些起伏便成了地下结构的图。"},{"no":"05","title":"A uniform field","titleCN":"匀强引力场","definition":"an idealised field whose strength and direction are the same at every point in a region","definitionCN":"在某一区域内各点强度与方向都相同的理想化场","example":"Near the floor of the laboratory, the gravitational field is almost uniform.","exampleCN":"在实验室地板附近，引力场几乎是匀强的。","why":"Textbooks flatten the field on purpose, because constant acceleration makes the arithmetic simple.","whyCN":"教科书有意把场压平，因为恒定加速度让运算变得简单。"},{"no":"06","title":"Field lines","titleCN":"引力场线","definition":"imaginary curves drawn to show the direction a small test mass would be pulled","definitionCN":"用来表示小试验质量受力方向的假想曲线","example":"Field lines of the gravitational field always point toward the mass that creates them.","exampleCN":"引力场线总是指向产生它们的质量。","why":"Drawing lines turns an invisible influence into a picture that can be checked by eye.","whyCN":"画出线条，就把看不见的作用变成了可以用眼睛核对的图像。"},{"no":"07","title":"Gravitational potential","titleCN":"引力势","definition":"the work needed per unit mass to move a body from a reference point to a given point in the field","definitionCN":"在场中把单位质量从参考点移到某点所需的功","example":"The gravitational field can also be described by a potential, one number at each point.","exampleCN":"引力场也可以用势来描述，每个点对应一个数值。","why":"A single number per point is easier to compute with than a direction and a magnitude, so the field gets a scalar twin.","whyCN":"每点一个数比方向加大小更易计算，于是场有了一个标量孪生描述。"},{"no":"08","title":"Curvature in general relativity","titleCN":"广义相对论中的时空弯曲","definition":"the description of gravity as the bending of spacetime by mass and energy rather than as a force in flat space","definitionCN":"把引力描述为质量与能量使时空弯曲，而非平直空间中的一种力","example":"In general relativity the gravitational field is the curvature of spacetime itself.","exampleCN":"在广义相对论中，引力场就是时空本身的弯曲。","why":"The old field became geometry, which removed the need for a force acting across empty space.","whyCN":"旧的场概念变成了几何，于是不再需要一种跨越真空的力。"},{"no":"09","title":"A sphere of attraction","titleCN":"比喻用法：吸引力范围","definition":"a figurative area in which a person or organisation draws others toward itself","definitionCN":"比喻意义上，个人或组织把他人吸引过来的范围","example":"The young firm had a gravitational field that pulled suppliers into its orbit.","exampleCN":"这家年轻公司拥有引力场般的吸引力，把供应商拉入自己的轨道。","why":"Because the concept describes invisible pulling, it transfers easily to markets and reputations.","whyCN":"由于这一概念描述的是看不见的牵引，它很容易被挪用到市场与声誉上。"}],"etymology":{"intro":{"en":"The phrase joins an adjective from Latin gravis, heavy, to an English word for open ground that later became a technical term for a region of influence. The direct sources are clear; the date of the phrase's first technical use is approximate.","cn":"这个短语把一个来自拉丁语「重的」的形容词，与一个原指开阔地的英语词连在一起，后者后来成为指「作用区域」的术语。直接来源清楚，短语首次技术性使用的年代为约数。"},"items":[{"era":"LATIN GRAVIS","en":"Gravis meant heavy, weighty and, figuratively, serious.","cn":"这个词表示「重的、有分量的」，引申为「严重的」。"},{"era":"LATIN GRAVITAS","en":"The noun named weight and also the dignity of a person who carries weight.","cn":"这个名词既指重量，也指有分量者的威严。"},{"era":"LATIN GRAVITARE","en":"The verb meant to weigh down or to be heavy, and English made it gravitate.","cn":"这个动词意为「压重、变重」，英语据其造出表示「被吸引」的动词。"},{"era":"ENGLISH GRAVITATION","en":"Newton's physics gave English the noun for the attraction between masses.","cn":"牛顿的物理学为英语提供了表示质量间吸引的名词。"},{"era":"OLD ENGLISH FELD","en":"Feld meant open land or a stretch of ground, a word for a bounded expanse.","cn":"这个词指开阔地或一片土地，本是一个表示有界延展的词。"},{"era":"THE TECHNICAL PHRASE","en":"Nineteenth-century physics turned field into a region of force, and the two words combined into one term.","cn":"十九世纪的物理学把「场」变成力的作用区域，两个词于是合成一个术语。"}]},"similar":{"note":{"en":"The first group shares the adjective gravitational or the noun field; the second group names other ways of describing attraction.","cn":"第一组共享形容词「引力的」或名词「场」；第二组表示描述吸引的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gravitational force","ipa":"/ˌɡrævɪˈteɪʃənl fɔːs/","tag":"same adjective","definition":"The force exerted between two masses.","definitionCN":"两个质量之间施加的力。"},{"word":"gravitational wave","ipa":"/ˌɡrævɪˈteɪʃənl weɪv/","tag":"same adjective","definition":"A ripple in spacetime produced by accelerating masses.","definitionCN":"加速的质量在时空中产生的涟漪。"},{"word":"gravitational lens","ipa":"/ˌɡrævɪˈteɪʃənl lenz/","tag":"same adjective","definition":"A mass that bends light from a distant source.","definitionCN":"使远处光源光线弯曲的质量。"},{"word":"gravitational potential","ipa":"/ˌɡrævɪˈteɪʃənl pəˈtenʃəl/","tag":"same adjective","definition":"The potential energy per unit mass in a field.","definitionCN":"场中单位质量的势能。"},{"word":"field","ipa":"/fiːld/","tag":"component","definition":"A region in which a force acts on a body.","definitionCN":"力对物体起作用的区域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gravity field","ipa":"/ˈɡrævəti fiːld/","tag":"near meaning","definition":"A plainer name for the same region of attraction.","definitionCN":"对同一引力区域的更朴素说法。"},{"word":"field of force","ipa":"/fiːld əv fɔːs/","tag":"near meaning","definition":"Any region where a force is defined at every point.","definitionCN":"在任何一点都定义有某种力的区域。"},{"word":"attraction","ipa":"/əˈtrækʃən/","tag":"near meaning","definition":"The tendency of bodies to draw toward one another.","definitionCN":"物体相互靠拢的趋势。"},{"word":"pull","ipa":"/pʊl/","tag":"near meaning","definition":"A steady force drawing something toward a source.","definitionCN":"把某物拉向来源的持续力。"},{"word":"sphere of influence","ipa":"/sfɪə əv ˈɪnfluəns/","tag":"near meaning","definition":"An area in which one power or person can affect events.","definitionCN":"某一力量或个人能影响事件的区域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations start from the bent grid and move to strength, maps and relativity; abstract ones treat the field as an invisible shape in space.","cn":"正常联想从被压弯的网格出发，走向场强、测绘与相对论；抽象联想把场看作空间中看不见的形状。"},"normal":[{"en":"Put a ball on a stretched sheet and the dip is a gravitational field.","cn":"把球放在绷紧的布上，凹陷就是引力场。"},{"en":"A scale reading is your body sensing the local field strength.","cn":"体重秤的读数，就是你的身体在感知当地的场强。"},{"en":"Probes map bumps in the field to find mass hidden underground.","cn":"探测器测绘场的起伏，从而找出地下的质量。"},{"en":"Field lines always point at the mass that made them.","cn":"场线总是指向产生它们的质量。"},{"en":"Einstein replaced the field with the shape of spacetime.","cn":"爱因斯坦用时空的形状取代了场。"}],"abstract":[{"en":"A field is a way of saying that space itself remembers where the mass is.","cn":"场是一种说法：空间本身记得质量在哪里。"},{"en":"Invisible influence becomes real once you can draw its lines.","cn":"看不见的作用一旦能画出线条，就变得真实。"},{"en":"Anything that pulls has a field, even a reputation.","cn":"凡能牵引者皆有场，声誉也不例外。"}]},"examples":[{"en":"The gravitational field near the surface is almost constant.","cn":"地表附近的引力场几乎是恒定的。"},{"en":"Instruments measured a weak gravitational field around the small asteroid.","cn":"仪器测得这颗小行星周围有微弱的引力场。"},{"en":"Students plotted the gravitational field on a grid of arrows.","cn":"学生们用箭头网格画出了这个引力场。"}],"dict_mnemonic":{"note":"组合记忆 · 非词源","text":"gravitational（引力的）+ field（场）——引力作用的场，就是引力场","word":"gravitational field"},"root":"由 gravitational 与 field 组合而成。前者源自拉丁语 gravis「重的」，经 gravitas「重量」与 gravitare「使变重」进入英语；后者源自古英语 feld「开阔地、一片土地」。十九世纪物理学把 field 变为「力的作用区域」，两词遂合成术语，确切首见年代不确定。","sensesIntro":{"en":"Nine senses move from the bare definition to strength, the earth, other bodies, idealised cases, lines, potential, curvature and metaphor.","cn":"九个义项从基本定义出发，依次走向场强、地球、其他天体、理想情形、场线、势、时空弯曲与比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a taut grid with a heavy ball sinking into it.","cn":"核心意象：一张绷紧的网格，被重球压出凹陷。"},"chain":["REGION OF PULL","STRENGTH","PLANETARY MAPS","IDEAL AND DRAWN","POTENTIAL","CURVATURE AND METAPHOR"],"branches":[{"senses":"01 · 02","en":"THE CORE PAIR: the region where a pull exists and the number that measures it.","cn":"核心一对：存在吸引的区域，以及测量它的数值。"},{"senses":"03 · 04","en":"THE REAL BODIES: the earth's field and the mapped field of another world.","cn":"真实天体：地球的场，以及另一个世界被测绘出的场。"},{"senses":"05 · 06","en":"THE SIMPLIFIED PICTURE: a uniform field and the lines drawn to show it.","cn":"简化图景：匀强场，以及为显示它而画的场线。"},{"senses":"07 · 08","en":"THE DEEPER DESCRIPTIONS: a potential at each point, then curvature of spacetime.","cn":"更深描述：每点一个势，随后是时空弯曲。"},{"senses":"09","en":"THE TRANSFER: an invisible pull used for markets and reputations.","cn":"迁移用法：把看不见的牵引用到市场与声誉上。"}]},"affixes":{"intro":{"en":"The phrase is built from a Latin adjective of weight and an Old English noun of ground, each with its own family.","cn":"这个短语由一个表示重量的拉丁形容词和一个表示土地的英语名词构成，各自都有一族同根词。"},"latinIntro":{"en":"Latin supplies gravis and its noun and verb; Old English supplies feld, which survives as field.","cn":"拉丁语提供了表示重的形容词及其名词与动词；古英语提供了后来变为 field 的土地名词。"},"items":[{"word":"gravis","structure":"Latin adjective","meaning":"heavy, serious","meaningCN":"重的；严重的","example":"It is the root of gravity and of grave in the sense of serious.","exampleCN":"它是「重力」以及表示「严重的」那个词的根。"},{"word":"gravitas","structure":"Latin noun","meaning":"weight, dignity","meaningCN":"重量；威严","example":"The noun names both physical weight and personal seriousness.","exampleCN":"这个名词既指物理重量，也指人的庄重。"},{"word":"gravitare","structure":"Latin verb","meaning":"to weigh down","meaningCN":"压重；使变重","example":"English formed gravitate from this verb.","exampleCN":"英语据这个动词造出了表示「受吸引」的动词。"},{"word":"-ation","structure":"Latin noun suffix","meaning":"action or process","meaningCN":"动作或过程","example":"It turns the verb into the name of the attraction itself.","exampleCN":"它把动词变成表示吸引作用本身的名词。"},{"word":"-al","structure":"Latin adjective suffix","meaning":"relating to","meaningCN":"与……相关的","example":"It turns gravitation into an adjective.","exampleCN":"它把「引力」变成形容词。"},{"word":"feld","structure":"Old English noun","meaning":"open land, a stretch of ground","meaningCN":"开阔地；一片土地","example":"The word named a bounded expanse before it named a region of force.","exampleCN":"这个词先指有界的延展，后才指力的区域。"},{"word":"field","structure":"English noun","meaning":"region of force or activity","meaningCN":"力或活动的区域","example":"Physics gave the old land word its modern technical sense.","exampleCN":"物理学给了这个古老的土地词现代技术含义。"},{"word":"graviton","structure":"English noun","meaning":"hypothetical quantum of gravity","meaningCN":"假设的引力量子","example":"The suffix marks a particle rather than a region.","exampleCN":"这个词尾标记粒子而非区域。"}],"latinEntries":[{"word":"gravis","structure":"Latin adjective","meaning":"heavy","meaningCN":"重的"},{"word":"gravitas","structure":"Latin noun","meaning":"weight","meaningCN":"重量"},{"word":"gravitare","structure":"Latin verb","meaning":"to weigh down","meaningCN":"压重"},{"word":"-alis","structure":"Latin suffix","meaning":"relating to","meaningCN":"与……相关的"}],"derivatives":[{"word":"gravitation","pos":"n.","zh":"由拉丁动词加表示「作用、过程」的词尾构成，义为「引力作用」"},{"word":"gravitational","pos":"adj.","zh":"由本词组的第一成分构成，义为「引力的；重力的」"},{"word":"gravitate","pos":"v.","zh":"同一词根的动词，义为「受引力作用；被吸引」"},{"word":"gravity","pos":"n.","zh":"同一词根的名词，义为「重力；严重性」"},{"word":"graviton","pos":"n.","zh":"由本词根加表示「粒子」的词尾构成，指假设中的引力子"},{"word":"gravimeter","pos":"n.","zh":"由本词根加表示「测量仪器」的成分构成，义为「重力仪」"}]}},{"word":"electromagnetic spectrum","ipa_uk":"/ɪˌlektrəʊmæɡˈnetɪk ˈspektrəm/","ipa_us":"/ɪˌlektroʊmæɡˈnetɪk ˈspektrəm/","definition_zh":"电磁波谱；电磁辐射按波长（或频率）排列形成的完整谱段","definition_en":"the full range of electromagnetic radiation, ordered by wavelength or frequency from radio waves to gamma rays","core_image":"一条从左到右由长波到短波渐变的彩色谱带，左端标着射电，右端标着伽马","scene":"夜里，射电望远镜的抛物面朝向天空，机房里一排屏幕显示着不同波段的信号曲线。Radio telescopes read the long-wavelength end of the electromagnetic spectrum.","sceneCN":"这里指电磁波谱中波长最长的那一段（第 4 个义项：射电与微波部分）；句意为射电望远镜读取的是电磁波谱的长波端。图中可辨识物件：抛物面天线、控制屏、信号曲线、夜空。","pos":[{"tag":"n.","zh":"名词短语：可数，指整个电磁波谱；也指某一具体波段范围"}],"collocations":[{"phrase":"the visible part of the electromagnetic spectrum","zh":"电磁波谱中的可见部分"},{"phrase":"across the electromagnetic spectrum","zh":"在整个电磁波谱范围内"},{"phrase":"the electromagnetic spectrum bands","zh":"电磁波谱的各个波段"},{"phrase":"map the electromagnetic spectrum","zh":"测绘电磁波谱"},{"phrase":"the radio end of the electromagnetic spectrum","zh":"电磁波谱的射电端"},{"phrase":"spectrum allocation","zh":"频谱分配"},{"phrase":"a band of the electromagnetic spectrum","zh":"电磁波谱的一个波段"}],"forms":[{"label":"短语原形","form":"electromagnetic spectrum"},{"label":"复数","form":"electromagnetic spectra"},{"label":"定语用法","form":"electromagnetic spectrum + 名词"},{"label":"介词短语","form":"within the electromagnetic spectrum"},{"label":"构成成分一","form":"electromagnetic"},{"label":"构成成分二","form":"spectrum"},{"label":"相关名词","form":"spectroscopy"}],"derivatives":[{"word":"electromagnetic","pos":"adj.","zh":"由表示「电的」与「磁的」两个成分构成，义为「电磁的」"},{"word":"spectra","pos":"n.","zh":"本词第二成分的复数形式，义为「多个谱」"},{"word":"spectral","pos":"adj.","zh":"由本词第二成分加形容词词尾构成，义为「光谱的；谱的」"},{"word":"spectroscopy","pos":"n.","zh":"由本词第二成分加表示「观测、研究」的成分构成，义为「光谱学」"},{"word":"spectroscope","pos":"n.","zh":"由本词第二成分加表示「观察仪器」的成分构成，义为「分光镜」"},{"word":"spectrometer","pos":"n.","zh":"由本词第二成分加表示「测量仪器」的成分构成，义为「光谱仪」"}],"senses":[{"no":"01","title":"The whole range of radiation","titleCN":"整个电磁辐射范围","definition":"all electromagnetic radiation taken together, from the longest radio waves to the shortest gamma rays","definitionCN":"从最长射电波到最短伽马射线的全部电磁辐射的总和","example":"The electromagnetic spectrum runs from radio waves to gamma rays without a gap.","exampleCN":"电磁波谱从射电波延伸到伽马射线，中间没有空隙。","why":"A single ordering by wavelength turns many apparently separate phenomena into one family.","whyCN":"按波长排成一条序列，就把许多看似分离的现象归为同一族。"},{"no":"02","title":"Named bands","titleCN":"划分出的波段","definition":"the conventional divisions of the spectrum into radio, microwave, infrared, visible, ultraviolet, X-ray and gamma bands","definitionCN":"把波谱按惯例分为射电、微波、红外、可见光、紫外、伦琴射线与伽马等波段","example":"Astronomers divide the electromagnetic spectrum into bands named after their wavelengths.","exampleCN":"天文学家按波长把电磁波谱分成若干波段。","why":"The bands are administrative and historical rather than sharply physical, but they let people talk about regions.","whyCN":"这些分段更多是管理与历史形成的，而非物理上截然分明，但它们让人能谈论某些区域。"},{"no":"03","title":"The visible portion","titleCN":"可见光部分","definition":"the narrow band that the human eye can detect, roughly between violet and red","definitionCN":"人眼能够感知的狭窄波段，大致介于紫光与红光之间","example":"The human eye samples only a narrow slice of the electromagnetic spectrum.","exampleCN":"人眼只取用电磁波谱中很窄的一段。","why":"Sight is a narrow window, and the phrase makes that narrowness visible by contrast.","whyCN":"视觉只是一扇窄窗，这个说法通过对比让这种狭窄变得可见。"},{"no":"04","title":"Radio and microwave portion","titleCN":"射电与微波段","definition":"the long-wavelength end used by radio telescopes, radar and communication links","definitionCN":"射电望远镜、雷达与通信链路所使用的长波段","example":"Radio telescopes read the long-wavelength end of the electromagnetic spectrum.","exampleCN":"射电望远镜读取的是电磁波谱的长波端。","why":"Long waves pass through dust and clouds, so this end of the spectrum reveals what optics cannot.","whyCN":"长波能穿过尘埃与云层，因此波谱的这一端能揭示光学观测看不到的东西。"},{"no":"05","title":"Astronomical survey use","titleCN":"天文观测中的使用","definition":"the practice of observing the same object in several bands to recover its full physical picture","definitionCN":"在同一目标上观测多个波段，以还原其完整物理图景的做法","example":"Surveying the electromagnetic spectrum in many bands gives a fuller picture of a galaxy.","exampleCN":"在多个波段普查电磁波谱能给出更完整的星系图景。","why":"No single band tells the whole story, so astronomers stack observations across the spectrum.","whyCN":"没有任何单一波段能讲完整个故事，因此天文学家把各波段观测叠在一起。"},{"no":"06","title":"Communication allocation","titleCN":"通信频谱分配","definition":"the regulated assignment of frequency ranges to operators and services","definitionCN":"把频率范围按规定分配给运营商与业务的做法","example":"Regulators auction blocks of the electromagnetic spectrum to mobile operators.","exampleCN":"监管机构把电磁波谱中的若干频段拍卖给移动运营商。","why":"The spectrum is a finite public resource, so its use has to be divided by rules.","whyCN":"波谱是有限的公共资源，其使用必须按规则划分。"},{"no":"07","title":"A plotted spectrum","titleCN":"频谱图与光谱图","definition":"a graph showing how much energy arrives at each wavelength or frequency","definitionCN":"显示各波长或频率上到达多少能量的图","example":"A plot of the electromagnetic spectrum shows intensity against frequency.","exampleCN":"电磁波谱的图示以频率为横轴显示强度。","why":"Once the range is drawn as a graph, peaks and gaps become readable at a glance.","whyCN":"一旦把范围画成图，峰与空隙就能一眼读出。"},{"no":"08","title":"Spectral fingerprints","titleCN":"谱线特征","definition":"the pattern of absorption or emission lines by which a substance can be identified","definitionCN":"可用来识别物质的吸收线或发射线图案","example":"Each element leaves a unique pattern in the electromagnetic spectrum.","exampleCN":"每种元素都在电磁波谱上留下独特的图案。","why":"Lines are element-specific, which turned the spectrum into a chemical fingerprint.","whyCN":"谱线因元素而异，这就把波谱变成了化学指纹。"},{"no":"09","title":"The spectrum as a domain","titleCN":"作为作战域的频谱","definition":"the electromagnetic environment treated as a space to be controlled in communications and conflict","definitionCN":"在通信与冲突中被视为需要掌控的电磁环境","example":"Modern forces plan to control the electromagnetic spectrum during a conflict.","exampleCN":"现代军队计划在冲突中掌控电磁波谱。","why":"Military planners redefined a physical range as territory, which is a strategic rather than a scientific move.","whyCN":"军事规划者把一段物理范围重新定义为「领土」，这是战略而非科学的操作。"}],"etymology":{"intro":{"en":"The phrase combines a nineteenth-century adjective for electricity and magnetism with a Latin word that Newton had already used for the band of prismatic colours. The pieces are well documented; the exact date of the full phrase is approximate.","cn":"这个短语把十九世纪表示电与磁的形容词，与一个已被牛顿用来指棱镜色带的拉丁词组合起来。各部分来源有据，整个短语的确切首见年代为约数。"},"items":[{"era":"GREEK ELEKTRON","en":"Elektron meant amber, because rubbing amber produces static charge.","cn":"这个词指琥珀，因为摩擦琥珀会产生静电。"},{"era":"LATIN MAGNES","en":"Magnes named the lodestone of Magnesia, the original natural magnet.","cn":"这个词指马格尼西亚的磁石，即最早被认识的天然磁体。"},{"era":"LATIN SPECTRUM","en":"Spectrum meant an appearance or image, from the verb meaning to look.","cn":"这个词表示外观或影像，来自表示「看」的动词。"},{"era":"NEWTON'S COLOURS","en":"Newton used spectrum for the coloured band thrown by a prism, fixing the word in optics.","cn":"牛顿用这个词指棱镜投出的彩色带，使其在光学中定型。"},{"era":"UNITING TWO FORCES","en":"Nineteenth-century physics showed that electricity, magnetism and light are one phenomenon.","cn":"十九世纪的物理学证明电、磁与光是同一种现象。"},{"era":"THE FULL PHRASE","en":"The full phrase appears once the whole range of radiation was understood as a single ordered set, late in the nineteenth century.","cn":"当全部辐射被理解为一条有序序列后，完整短语才出现，时在十九世纪晚期。"}]},"similar":{"note":{"en":"The first group shares the adjective or the noun spectrum; the second group names particular bands and kinds of range.","cn":"第一组共享形容词「电磁的」或名词「谱」；第二组指特定波段与范围类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"electromagnetic radiation","ipa":"/ɪˌlektrəʊmæɡˈnetɪk ˌrædiˈeɪʃən/","tag":"same adjective","definition":"Energy carried by oscillating electric and magnetic fields.","definitionCN":"由振荡电场与磁场携带的能量。"},{"word":"electromagnetic wave","ipa":"/ɪˌlektrəʊmæɡˈnetɪk weɪv/","tag":"same adjective","definition":"A wave of coupled electric and magnetic fields.","definitionCN":"电场与磁场相互耦合形成的波。"},{"word":"electromagnetic field","ipa":"/ɪˌlektrəʊmæɡˈnetɪk fiːld/","tag":"same adjective","definition":"The field produced by charges and currents.","definitionCN":"由电荷与电流产生的场。"},{"word":"spectrum","ipa":"/ˈspektrəm/","tag":"component","definition":"A range of wavelengths or frequencies.","definitionCN":"一段波长或频率范围。"},{"word":"spectral","ipa":"/ˈspektrəl/","tag":"same root","definition":"Relating to a spectrum.","definitionCN":"与谱相关的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"visible spectrum","ipa":"/ˈvɪzəbl ˈspektrəm/","tag":"near meaning","definition":"The band of light the eye can see.","definitionCN":"人眼能看见的那段光。"},{"word":"radio spectrum","ipa":"/ˈreɪdiəʊ ˈspektrəm/","tag":"near meaning","definition":"The frequencies used for radio communication.","definitionCN":"用于无线电通信的频率范围。"},{"word":"frequency band","ipa":"/ˈfriːkwənsi bænd/","tag":"near meaning","definition":"A continuous range of frequencies set aside for a use.","definitionCN":"为某种用途划出的一段连续频率。"},{"word":"wavelength range","ipa":"/ˈweɪvleŋθ reɪndʒ/","tag":"near meaning","definition":"The span between the shortest and longest waves observed.","definitionCN":"所观测最短波与最长波之间的跨度。"},{"word":"spectral range","ipa":"/ˈspektrəl reɪndʒ/","tag":"near meaning","definition":"The extent of wavelengths an instrument can record.","definitionCN":"仪器能记录的波长范围。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the rainbow strip outward in both directions; abstract ones treat the spectrum as a single ordered map of one phenomenon.","cn":"正常联想沿着彩虹色带向两端延伸；抽象联想把波谱看作同一现象的一张有序地图。"},"normal":[{"en":"Prism in, rainbow out: that band is the visible part.","cn":"棱镜进去，彩虹出来，那条色带就是可见部分。"},{"en":"Stretch the rainbow far left and you reach radio waves.","cn":"把彩虹向左拉得很远，就到了射电波。"},{"en":"Stretch it far right and you reach gamma rays.","cn":"向右拉得很远，就到了伽马射线。"},{"en":"Radio telescopes work at the long-wave end where dust cannot block them.","cn":"射电望远镜工作在尘埃挡不住的长波端。"},{"en":"Every element writes its own lines on the strip.","cn":"每种元素都在这条带上写下自己的谱线。"}],"abstract":[{"en":"The spectrum is one axis: everything electromagnetic is a position on it.","cn":"波谱就是一根轴：一切电磁现象都是它上面的一个位置。"},{"en":"Bands are habits of speech, not walls in nature.","cn":"波段是说话的习惯，不是自然界的墙。"},{"en":"A resource becomes territory the moment someone writes rules for it.","cn":"资源一旦被人写下规则，就变成了领土。"}]},"examples":[{"en":"Visible light occupies only a small part of the electromagnetic spectrum.","cn":"可见光只占电磁波谱的一小部分。"},{"en":"The satellite monitors several bands of the electromagnetic spectrum.","cn":"这颗卫星监测电磁波谱的若干波段。"},{"en":"Engineers test how the material responds across the electromagnetic spectrum.","cn":"工程师测试该材料在整个电磁波谱上的响应。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"electromagnetic（电磁的）+ spectrum（谱）——电磁的谱，即电磁波谱","word":"electromagnetic spectrum"},"root":"由 electromagnetic 与 spectrum 组合。前者由希腊语 elektron「琥珀」与拉丁语 magnes「磁石」经 magnet 构成；后者来自拉丁语 spectrum「外观、影像」，出自表示「看」的动词。牛顿先以该词指棱镜色带，十九世纪晚期辐射被理解为一条有序序列后，完整短语才定型，确切年代不确定。","sensesIntro":{"en":"Nine senses unroll one ordered strip: its whole length, its bands, its visible slice, its long-wave end, its uses, its regulation, its graphs, its lines and its strategic reading.","cn":"九个义项展开同一条有序谱带：全长、分段、可见的一小段、长波端、用途、管理、图示、谱线与其战略解读。"},"semanticMap":{"core":{"en":"CORE IMAGE: a strip that shifts from long red waves to short violet ones, then keeps going both ways.","cn":"核心意象：一条由长波红端过渡到短波紫端的谱带，并向两端继续延伸。"},"chain":["THE WHOLE STRIP","BANDS","VISIBLE SLICE","LONG-WAVE END","OBSERVING AND ALLOCATING","GRAPHS AND LINES"],"branches":[{"senses":"01 · 02","en":"THE CORE TWO: one continuous range and the conventional bands cut into it.","cn":"核心两项：一条连续范围，以及在其上划分的惯用波段。"},{"senses":"03 · 04","en":"THE TWO ENDS PEOPLE USE: the narrow visible slice and the long-wave end.","cn":"人常用的两端：狭窄的可见段与长波段。"},{"senses":"05 · 06","en":"THE USES: multi-band astronomy and regulated communication blocks.","cn":"用途：多波段天文观测与受管制的通信频段。"},{"senses":"07 · 08","en":"THE READINGS: intensity plotted against frequency, and lines that identify elements.","cn":"读法：以频率为横轴画强度，以及可识别元素的谱线。"},{"senses":"09","en":"THE STRATEGIC SHIFT: the same strip treated as a domain to control.","cn":"战略转向：同一条谱带被当作需要掌控的领域。"}]},"affixes":{"intro":{"en":"Two Greek and Latin roots plus a Latin noun of appearance make up the phrase, and its second element has generated a large family.","cn":"两个希腊与拉丁词根加一个表示外观的拉丁名词构成了这个短语，其第二成分还衍生出一大族词。"},"latinIntro":{"en":"Greek supplies the word for amber, Latin supplies the lodestone and the noun for appearance; modern science combined them.","cn":"希腊语提供了「琥珀」一词，拉丁语提供了「磁石」与表示外观的名词；近代科学把它们组合起来。"},"items":[{"word":"elektron","structure":"Greek noun","meaning":"amber","meaningCN":"琥珀","example":"The word gave its name to electricity because amber holds charge.","exampleCN":"这个词因琥珀能带电荷而成为「电」的名称来源。"},{"word":"magnes","structure":"Latin noun","meaning":"lodestone","meaningCN":"磁石","example":"It named the natural magnet found in one district.","exampleCN":"它指在某一地区发现的天然磁体。"},{"word":"spectrum","structure":"Latin noun","meaning":"appearance, image","meaningCN":"外观；影像","example":"Newton fixed its optical sense as the band of colours.","exampleCN":"牛顿把它的光学含义固定为彩色带。"},{"word":"specere","structure":"Latin verb","meaning":"to look","meaningCN":"看","example":"The noun is built on the act of looking.","exampleCN":"这个名词建立在「看」这一动作上。"},{"word":"electro-","structure":"Greek prefix","meaning":"electric","meaningCN":"电的","example":"It marks the electrical half of the adjective.","exampleCN":"它标记形容词中「电」的那一半。"},{"word":"-ic","structure":"Latin suffix","meaning":"relating to","meaningCN":"与……相关的","example":"It turns the noun magnet into an adjective.","exampleCN":"它把名词「磁体」变成形容词。"},{"word":"-trum","structure":"Latin suffix","meaning":"instrument or means","meaningCN":"工具或手段","example":"The ending appears in the Latin noun for a means of seeing.","exampleCN":"这个词尾出现在拉丁语中表示「观看手段」的名词里。"},{"word":"spectral","structure":"English adjective","meaning":"of a spectrum","meaningCN":"谱的","example":"The adjective describes anything belonging to a spectrum.","exampleCN":"这个形容词描述属于谱的事物。"}],"latinEntries":[{"word":"spectrum","structure":"Latin noun","meaning":"appearance","meaningCN":"外观"},{"word":"specere","structure":"Latin verb","meaning":"to look","meaningCN":"看"},{"word":"magnes","structure":"Latin noun","meaning":"lodestone","meaningCN":"磁石"}],"derivatives":[{"word":"electromagnetic","pos":"adj.","zh":"由表示「电的」与「磁的」两个成分构成，义为「电磁的」"},{"word":"spectra","pos":"n.","zh":"本词第二成分的复数形式，义为「多个谱」"},{"word":"spectral","pos":"adj.","zh":"由本词第二成分加形容词词尾构成，义为「光谱的；谱的」"},{"word":"spectroscopy","pos":"n.","zh":"由本词第二成分加表示「观测、研究」的成分构成，义为「光谱学」"},{"word":"spectroscope","pos":"n.","zh":"由本词第二成分加表示「观察仪器」的成分构成，义为「分光镜」"},{"word":"spectrometer","pos":"n.","zh":"由本词第二成分加表示「测量仪器」的成分构成，义为「光谱仪」"}]}},{"word":"cosmic radiation","ipa_uk":"/ˌkɒzmɪk ˌreɪdiˈeɪʃən/","ipa_us":"/ˌkɑːzmɪk ˌreɪdiˈeɪʃən/","definition_zh":"宇宙辐射；来自外太空的高能粒子与射线","definition_en":"high-energy particles and rays that reach the earth from outer space","core_image":"高原上的探测器，计数灯在黑暗中一闪一闪，屋顶上方划过细密的虚线","scene":"高原观测站里，闪烁体探测器的计数灯明明灭灭，说明有看不见的粒子穿过了屋顶。Cosmic radiation passes through the station roof and leaves faint flashes in the detector.","sceneCN":"这里指来自外太空、能穿透屋顶的高能粒子（第 1 个义项：宇宙辐射的总体）；句意为宇宙辐射穿过观测站屋顶，在探测器里留下微弱闪光。图中可辨识物件：闪烁体探测器、计数灯、屋顶、夜空。","pos":[{"tag":"n.","zh":"名词短语：多作不可数，指来自太空的高能粒子与射线；强调来源而非单一粒子"}],"collocations":[{"phrase":"galactic cosmic radiation","zh":"银河宇宙辐射"},{"phrase":"solar cosmic radiation","zh":"太阳宇宙辐射"},{"phrase":"cosmic radiation dose","zh":"宇宙辐射剂量"},{"phrase":"cosmic radiation exposure","zh":"宇宙辐射照射"},{"phrase":"a flux of cosmic radiation","zh":"宇宙辐射通量"},{"phrase":"cosmic radiation shielding","zh":"宇宙辐射屏蔽"},{"phrase":"high-energy cosmic radiation","zh":"高能宇宙辐射"}],"forms":[{"label":"短语原形","form":"cosmic radiation"},{"label":"不可数用法","form":"cosmic radiation"},{"label":"定语用法","form":"cosmic radiation + 名词"},{"label":"介词短语","form":"exposed to cosmic radiation"},{"label":"构成成分一","form":"cosmic"},{"label":"构成成分二","form":"radiation"},{"label":"相关名词","form":"cosmic ray"}],"derivatives":[{"word":"cosmic","pos":"adj.","zh":"由希腊语表示「宇宙、秩序」的名词加形容词词尾构成，义为「宇宙的」"},{"word":"cosmos","pos":"n.","zh":"同一词根的名词，义为「宇宙；有序的整体」"},{"word":"cosmic ray","pos":"n.","zh":"以本短语第一成分构成的近义术语，指单个高能粒子"},{"word":"radiate","pos":"v.","zh":"本短语第二成分的动词形式，义为「辐射；发散」"},{"word":"radiation","pos":"n.","zh":"由动词加表示「作用、过程」的词尾构成，义为「辐射」"},{"word":"radiative","pos":"adj.","zh":"由本短语第二成分加形容词词尾构成，义为「辐射的」"}],"senses":[{"no":"01","title":"High-energy particles from space","titleCN":"来自太空的高能粒子","definition":"the general name for energetic particles and rays arriving at the earth from outside its atmosphere","definitionCN":"对从大气层之外到达地球的高能粒子与射线的总称","example":"Cosmic radiation arrives at the top of the atmosphere from every direction.","exampleCN":"宇宙辐射从各个方向到达大气层顶部。","why":"A single umbrella term was needed once balloon flights showed that ionisation increased with altitude.","whyCN":"当气球观测显示电离随高度增加后，就需要一个统称。"},{"no":"02","title":"Primary cosmic radiation","titleCN":"初级宇宙辐射","definition":"the original particles arriving from space before they interact with the atmosphere","definitionCN":"在与大气发生作用之前从太空到达的原始粒子","example":"Primary cosmic radiation consists mostly of protons stripped of their electrons.","exampleCN":"初级宇宙辐射主要由失去电子的质子组成。","why":"Dividing primary from secondary separates what space sends from what the air makes.","whyCN":"把初级与次级分开，就把太空送来的东西与空气生成的东西区别开来。"},{"no":"03","title":"Secondary cosmic radiation","titleCN":"次级宇宙辐射","definition":"the cascade of particles produced when primary radiation strikes air molecules","definitionCN":"初级辐射撞击空气分子时产生的粒子级联","example":"Secondary cosmic radiation forms a shower of particles when the primary hits air.","exampleCN":"当初级粒子撞上空气时，次级宇宙辐射形成粒子簇射。","why":"By the time radiation reaches sea level almost none of it is primary, so the distinction matters for measurement.","whyCN":"当辐射到达海平面时几乎已没有初级粒子，因此这一区分对测量很重要。"},{"no":"04","title":"Galactic cosmic radiation","titleCN":"银河宇宙辐射","definition":"the component accelerated elsewhere in the galaxy, arriving steadily from outside the solar system","definitionCN":"在银河系其他地方被加速、从太阳系之外稳定到达的成分","example":"Galactic cosmic radiation comes from outside the solar system and varies slowly.","exampleCN":"银河宇宙辐射来自太阳系之外，变化缓慢。","why":"Its steadiness makes it a baseline against which solar outbursts stand out.","whyCN":"它的稳定使它成为基准，太阳爆发在对比下便显得突出。"},{"no":"05","title":"Solar cosmic radiation","titleCN":"太阳宇宙辐射","definition":"the particles accelerated by the sun, especially during flares and coronal mass ejections","definitionCN":"由太阳加速的粒子，尤其在耀斑与日冕物质抛射期间","example":"Solar cosmic radiation surges during a large flare.","exampleCN":"在一次大耀斑期间，太阳宇宙辐射会骤增。","why":"The sun is a local and variable source, so its contribution is named separately.","whyCN":"太阳是局部的、变化的源，因此它的贡献被单独命名。"},{"no":"06","title":"Dose in aviation and spaceflight","titleCN":"航空与航天的辐射剂量","definition":"the accumulated exposure received by aircrews and astronauts from cosmic radiation","definitionCN":"机组人员与航天员从宇宙辐射中累积受到的照射","example":"Aircrews receive more cosmic radiation than people on the ground.","exampleCN":"机组人员受到的宇宙辐射比地面人员更多。","why":"Shielding by air is thinner at altitude, so the same sky delivers a larger dose.","whyCN":"高空的空气屏蔽更薄，同一片天空因此送来更大的剂量。"},{"no":"07","title":"Effects on electronics","titleCN":"对电子器件的影响","definition":"single-particle upsets in circuits caused by an energetic particle strike","definitionCN":"高能粒子撞击引起的电路单粒子翻转","example":"A single particle of cosmic radiation can flip a bit in a memory chip.","exampleCN":"一个宇宙辐射粒子就能翻转存储芯片中的一位。","why":"Miniaturised circuits hold so little charge that one strike now matters.","whyCN":"微型化电路所存电荷极少，一次撞击便足以造成影响。"},{"no":"08","title":"Cosmogenic nuclides and dating","titleCN":"宇宙成因核素与测年","definition":"rare isotopes produced in rock by cosmic radiation, used to date exposure surfaces","definitionCN":"岩石中由宇宙辐射产生的稀有同位素，用于给暴露面测年","example":"Cosmogenic nuclides produced by cosmic radiation allow surfaces to be dated.","exampleCN":"由宇宙辐射产生的宇宙成因核素使地表得以测年。","why":"The sky leaves a slow chemical clock in stone, and the clock can be read.","whyCN":"天空在石头里留下一只缓慢的化学钟，而这钟可以被读出。"},{"no":"09","title":"Ultra-high-energy cosmic radiation","titleCN":"超高能宇宙辐射","definition":"the rarest particles, carrying energies far beyond anything built on earth can produce","definitionCN":"最稀少的粒子，其能量远超地球上任何人造装置所能产生","example":"Ultra-high-energy cosmic radiation is rare but carries more energy than any accelerator can reach.","exampleCN":"超高能宇宙辐射很稀少，却携带比任何加速器都高的能量。","why":"At the far end of the energy range, the rarity itself becomes the scientific problem.","whyCN":"在能量范围的最远端，稀少本身成了科学问题。"}],"etymology":{"intro":{"en":"The phrase joins a Greek adjective for the ordered universe to a Latin noun for the act of sending out rays. Both halves are well attested; the phrase itself dates from the era when balloon flights first detected the radiation, so its first use is approximate.","cn":"这个短语把一个表示有序宇宙的希腊形容词，与一个表示发出射线的拉丁名词组合起来。两半来源均有据；短语本身产生于气球升空首次探测到该辐射的年代，确切首见为约数。"},"items":[{"era":"GREEK KOSMOS","en":"Kosmos meant order, ornament and, by extension, the world as an ordered whole.","cn":"这个词表示秩序、装饰，引申指作为有序整体的世界。"},{"era":"GREEK KOSMIKOS","en":"The adjective described anything belonging to that ordered whole.","cn":"这个形容词描述属于那个有序整体的事物。"},{"era":"LATIN RADIUS","en":"Radius meant a spoke of a wheel and then a ray of light.","cn":"这个词先指车轮的辐条，后指光线。"},{"era":"LATIN RADIARE","en":"The verb meant to emit rays or to shine.","cn":"这个动词意为发出射线或发光。"},{"era":"ENGLISH RADIATION","en":"English formed the noun for the emission and for the energy emitted.","cn":"英语由此构成名词，指发射行为与被发射的能量。"},{"era":"THE DISCOVERY ERA","en":"Before the First World War, balloon flights showed that ionisation rose with altitude, and the phrase for the source soon followed.","cn":"在第一次世界大战之前，气球飞行显示电离随高度上升，指称这一来源的短语随即出现。"}]},"similar":{"note":{"en":"The first group shares the adjective cosmic or is easily confused with it; the second group names the same or related energetic particles.","cn":"第一组共享形容词「宇宙的」，或容易与之混淆；第二组指相同或相关的高能粒子。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cosmic ray","ipa":"/ˌkɒzmɪk reɪ/","tag":"same adjective","definition":"A single high-energy particle from space.","definitionCN":"来自太空的单个高能粒子。"},{"word":"cosmic dust","ipa":"/ˌkɒzmɪk dʌst/","tag":"same adjective","definition":"Tiny solid grains drifting between the stars.","definitionCN":"在星际间飘浮的微小固体颗粒。"},{"word":"comic","ipa":"/ˈkɒmɪk/","tag":"look-alike","definition":"Funny, or relating to comedy.","definitionCN":"滑稽的，或与喜剧相关的。"},{"word":"cosmetic","ipa":"/kɒzˈmetɪk/","tag":"look-alike","definition":"Relating to beauty treatment or superficial change.","definitionCN":"与美容或表面修饰相关的。"},{"word":"cosmos","ipa":"/ˈkɒzmɒs/","tag":"same root","definition":"The universe as an ordered whole.","definitionCN":"作为有序整体的宇宙。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ionising radiation","ipa":"/ˈaɪənaɪzɪŋ ˌreɪdiˈeɪʃən/","tag":"near meaning","definition":"Radiation energetic enough to strip electrons from atoms.","definitionCN":"能量足以从原子中剥离电子的辐射。"},{"word":"space radiation","ipa":"/speɪs ˌreɪdiˈeɪʃən/","tag":"near meaning","definition":"The radiation environment beyond the atmosphere.","definitionCN":"大气层之外的辐射环境。"},{"word":"galactic radiation","ipa":"/ɡəˈlæktɪk ˌreɪdiˈeɪʃən/","tag":"near meaning","definition":"Radiation originating within the galaxy.","definitionCN":"源自银河系内部的辐射。"},{"word":"high-energy particles","ipa":"/ˌhaɪ ˈenədʒi ˈpɑːtɪklz/","tag":"near meaning","definition":"Particles travelling at close to the speed of light.","definitionCN":"以接近光速运动的粒子。"},{"word":"background radiation","ipa":"/ˈbækɡraʊnd ˌreɪdiˈeɪʃən/","tag":"near meaning","definition":"The ordinary low-level radiation present in an environment.","definitionCN":"环境中普遍存在的低强度辐射。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the particle from space to the ground; abstract ones treat the word as an invisible rain that never stops.","cn":"正常联想沿着粒子从太空到地面的路径展开；抽象联想把这个词看作一场永不停歇的看不见的雨。"},"normal":[{"en":"A balloon rises and the ionisation meter climbs: that is cosmic radiation.","cn":"气球升高，电离计读数上升，那就是宇宙辐射。"},{"en":"Primary particles come from space; secondary ones are made in the air.","cn":"初级粒子来自太空，次级粒子在空气中生成。"},{"en":"The galaxy sends a steady background; the sun sends sudden surges.","cn":"银河送来稳定的背景，太阳送来突发的骤增。"},{"en":"At cruising altitude the thin air shields less, so the dose rises.","cn":"在巡航高度空气稀薄、屏蔽更弱，因此剂量上升。"},{"en":"One stray particle can flip a bit in a memory chip.","cn":"一个游离的粒子就能翻转存储芯片中的一位。"}],"abstract":[{"en":"Cosmic radiation is a rain with no clouds and no shelter.","cn":"宇宙辐射是一场没有云也没有屋檐的雨。"},{"en":"Anything that arrives from everywhere at once becomes a background rather than an event.","cn":"凡从各处同时到达者，便成了背景而非事件。"},{"en":"The rarest particles carry the largest questions.","cn":"最稀少的粒子承载着最大的问题。"}]},"examples":[{"en":"High-altitude flights increase the crew's exposure to cosmic radiation.","cn":"高空飞行增加了机组人员受到的宇宙辐射。"},{"en":"The detector recorded cosmic radiation throughout the night.","cn":"探测器整夜记录着宇宙辐射。"},{"en":"Thick rock shields underground labs from cosmic radiation.","cn":"厚实的岩层为地下实验室屏蔽了宇宙辐射。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"cosmic（宇宙的）+ radiation（辐射）——来自宇宙的辐射，即宇宙辐射","word":"cosmic radiation"},"root":"由 cosmic 与 radiation 组合。前者源自希腊语 kosmos「秩序、世界」；后者源自拉丁语 radius「辐条、光线」及其动词 radiare「发光、发射线」。短语随二十世纪初气球观测发现高空电离增强而出现，确切首见年代不确定。","sensesIntro":{"en":"Nine senses follow one shower of particles from its origin to its effects: the whole flux, its primary and secondary parts, its galactic and solar sources, its doses, its damage, its clock and its rarest end.","cn":"九个义项跟踪同一场粒子雨，从来源追到影响：整体通量、初级与次级、银河与太阳来源、剂量、损伤、测年之钟与最稀少的一端。"},"semanticMap":{"core":{"en":"CORE IMAGE: a detector on a plateau, counting invisible arrivals.","cn":"核心意象：高原上的探测器，在数着看不见的来客。"},"chain":["THE WHOLE FLUX","SPLIT BY ORIGIN","GALACTIC AND SOLAR","DOSE","DAMAGE AND CLOCKS","THE RARE END"],"branches":[{"senses":"01 · 02 · 03","en":"THE CORE SPLIT: one arriving flux, divided into what space sent and what the air made.","cn":"核心划分：同一股到达的通量，分为太空送来的与空气生成的。"},{"senses":"04 · 05","en":"THE TWO SOURCES: a steady galactic background and sudden solar surges.","cn":"两个来源：稳定的银河背景与突发的太阳骤增。"},{"senses":"06","en":"THE HUMAN DOSE: aircrews and astronauts receive more of it.","cn":"人体剂量：机组与航天员受到更多照射。"},{"senses":"07 · 08","en":"THE TWO TRACES: flipped bits in circuits and rare isotopes in stone.","cn":"两种痕迹：电路中翻转的位与石头中的稀有同位素。"},{"senses":"09","en":"THE EXTREME: particles too energetic for any earthly machine.","cn":"极端一端：能量高到任何地球装置都无法产生的粒子。"}]},"affixes":{"intro":{"en":"A Greek noun of order and a Latin noun of rays supply both halves, each with its own small family.","cn":"一个表示秩序的希腊名词与一个表示射线的拉丁名词提供了两半，各自带一小族词。"},"latinIntro":{"en":"Greek supplies kosmos and its adjective; Latin supplies radius, its verb and the noun of emission.","cn":"希腊语提供了「宇宙」及其形容词；拉丁语提供了「辐条、光线」、其动词以及表示发射的名词。"},"items":[{"word":"kosmos","structure":"Greek noun","meaning":"order, world","meaningCN":"秩序；世界","example":"It named the universe as something arranged rather than random.","exampleCN":"它把宇宙命名为被安排而非随机的东西。"},{"word":"kosmikos","structure":"Greek adjective","meaning":"of the world","meaningCN":"世界的；宇宙的","example":"The adjective passed into English as cosmic.","exampleCN":"这个形容词以「宇宙的」形式进入英语。"},{"word":"-ic","structure":"Latin suffix","meaning":"relating to","meaningCN":"与……相关的","example":"It forms the adjective from the Greek noun.","exampleCN":"它把希腊名词变成形容词。"},{"word":"radius","structure":"Latin noun","meaning":"spoke, ray","meaningCN":"辐条；光线","example":"The word moved from a wheel's spoke to a beam of light.","exampleCN":"这个词从车轮辐条转到光束。"},{"word":"radiare","structure":"Latin verb","meaning":"to emit rays","meaningCN":"发出射线","example":"The verb supplies the English verb and noun of radiation.","exampleCN":"这个动词提供了英语的动词与名词形式。"},{"word":"-ation","structure":"Latin noun suffix","meaning":"action or process","meaningCN":"动作或过程","example":"It names the act of sending out energy.","exampleCN":"它命名发出能量的行为。"},{"word":"radiation","structure":"English noun","meaning":"emission of energy","meaningCN":"辐射","example":"The noun covers both the process and what is emitted.","exampleCN":"这个名词既指过程也指被发出的东西。"},{"word":"cosmic ray","structure":"English compound","meaning":"one energetic particle","meaningCN":"单个高能粒子","example":"The compound narrows the mass noun to a countable particle.","exampleCN":"这个复合词把不可数的总称收窄为可数的粒子。"}],"latinEntries":[{"word":"radius","structure":"Latin noun","meaning":"spoke, ray","meaningCN":"辐条；光线"},{"word":"radiare","structure":"Latin verb","meaning":"to emit rays","meaningCN":"发出射线"},{"word":"radiatus","structure":"Latin adjective","meaning":"rayed","meaningCN":"带射线的"}],"derivatives":[{"word":"cosmic","pos":"adj.","zh":"由希腊语表示「宇宙、秩序」的名词加形容词词尾构成，义为「宇宙的」"},{"word":"cosmos","pos":"n.","zh":"同一词根的名词，义为「宇宙；有序的整体」"},{"word":"cosmic ray","pos":"n.","zh":"以本短语第一成分构成的近义术语，指单个高能粒子"},{"word":"radiate","pos":"v.","zh":"本短语第二成分的动词形式，义为「辐射；发散」"},{"word":"radiation","pos":"n.","zh":"由动词加表示「作用、过程」的词尾构成，义为「辐射」"},{"word":"radiative","pos":"adj.","zh":"由本短语第二成分加形容词词尾构成，义为「辐射的」"}]}},{"word":"methane","ipa_uk":"/ˈmiːθeɪn/","ipa_us":"/ˈmeθeɪn/","definition_zh":"甲烷；最简单的烷烃，一个碳原子与四个氢原子结合的气体","definition_en":"the simplest hydrocarbon, a colourless gas of one carbon atom bonded to four hydrogen atoms","core_image":"燃气灶上稳定的蓝色火焰，灶台旁放着一只检测管","scene":"厨房里，燃气灶的蓝色火焰稳定地燃烧，工程师蹲下检查管道接口。The blue flame on the stove is methane burning with plenty of oxygen.","sceneCN":"这里指作为燃气主要成分的甲烷（第 2 个义项：天然气的主体成分）；句意为灶上的蓝色火焰就是甲烷在氧气充足时燃烧。图中可辨识物件：燃气灶、蓝色火焰、管道接口、检测管。","pos":[{"tag":"n.","zh":"名词：不可数，指这种气体或其在混合物中的成分"}],"collocations":[{"phrase":"methane emissions","zh":"甲烷排放"},{"phrase":"methane gas","zh":"甲烷气体"},{"phrase":"capture methane","zh":"捕集甲烷"},{"phrase":"methane hydrate","zh":"甲烷水合物"},{"phrase":"atmospheric methane","zh":"大气中的甲烷"},{"phrase":"a molecule of methane","zh":"一个甲烷分子"},{"phrase":"methane leakage","zh":"甲烷泄漏"}],"forms":[{"label":"名词原形","form":"methane"},{"label":"不可数用法","form":"methane"},{"label":"定语用法","form":"methane + 名词"},{"label":"化学式读法","form":"一个碳四个氢"},{"label":"相关基团","form":"methyl"},{"label":"相关醇类","form":"methanol"},{"label":"相关同系物","form":"ethane"}],"derivatives":[{"word":"methyl","pos":"n.","zh":"由本词词干加表示「基团」的成分构成，义为「甲基」"},{"word":"methanol","pos":"n.","zh":"由「甲基」加表示「醇」的成分构成，义为「甲醇」"},{"word":"methane hydrate","pos":"n.","zh":"本词与表示「水合物」的词构成的复合术语，义为「甲烷水合物」"},{"word":"methanogen","pos":"n.","zh":"由本词加表示「产生者」的成分构成，义为「产甲烷菌」"},{"word":"methanogenesis","pos":"n.","zh":"由本词加表示「生成」的成分构成，义为「产甲烷过程」"},{"word":"methanotrophic","pos":"adj.","zh":"由本词加表示「以……为食」的成分构成，义为「食甲烷的」"}],"senses":[{"no":"01","title":"The chemical compound","titleCN":"甲烷这种化合物","definition":"the simplest alkane, a colourless and odourless gas with one carbon and four hydrogen atoms","definitionCN":"最简单的烷烃，一个碳原子与四个氢原子结合的无色无味气体","example":"Methane is the simplest hydrocarbon, one carbon atom bonded to four hydrogen atoms.","exampleCN":"甲烷是最简单的烃，一个碳原子与四个氢原子相连。","why":"Chemistry needed a name for the first member of the alkane series, and every later member is built by adding carbon units.","whyCN":"化学需要为烷烃系列的第一个成员命名，此后每个成员都以增加碳单位的方式构造。"},{"no":"02","title":"The main part of natural gas","titleCN":"天然气的主要成分","definition":"the dominant component of the gas extracted from wells and burned for heat and power","definitionCN":"从井中采出、用于取暖与发电的气体的主体成分","example":"Natural gas is mostly methane, with small amounts of heavier gases.","exampleCN":"天然气主要是甲烷，另含少量较重的气体。","why":"The fuel people call gas is chemically almost one substance, which is why the two names are often used interchangeably.","whyCN":"人们称作「燃气」的燃料在化学上几乎是单一物质，因此两个名称常被混用。"},{"no":"03","title":"Livestock and agricultural emissions","titleCN":"牲畜与农业排放","definition":"methane produced by ruminant digestion and by flooded rice fields","definitionCN":"反刍动物消化与淹水稻田所产生的甲烷","example":"Cattle and rice paddies are large sources of methane.","exampleCN":"牛群与稻田是甲烷的重要来源。","why":"Microbes in oxygen-free stomachs and mud make the gas, so agriculture becomes a chemical source.","whyCN":"无氧的胃与泥中的微生物制造了这种气体，农业因此成为化学来源。"},{"no":"04","title":"Landfill gas and biogas","titleCN":"填埋气与沼气","definition":"the gas released by decomposing waste or produced in a digester, often captured as fuel","definitionCN":"垃圾分解释放或在消化器中产生、常被收集作燃料的气体","example":"Landfill methane can be captured and burned for power.","exampleCN":"填埋场产生的甲烷可以被收集并燃烧发电。","why":"Waste buried without air is digested the same way a stomach digests, and the product can be put to use.","whyCN":"无氧埋藏的垃圾像胃一样被消化，产物还可以被利用。"},{"no":"05","title":"A greenhouse gas","titleCN":"温室气体","definition":"a gas that absorbs infrared radiation and warms the atmosphere, molecule for molecule far stronger than carbon dioxide over short spans","definitionCN":"吸收红外辐射并使大气变暖的气体，短期内逐分子远强于二氧化碳","example":"Methane traps far more heat per molecule than carbon dioxide over a short period.","exampleCN":"短期内甲烷每个分子截留的热量远多于二氧化碳。","why":"Its molecular bonds match infrared wavelengths, which is exactly what makes it a warming agent.","whyCN":"它的分子键振动与红外波段相匹配，这正是它成为升温因素的原因。"},{"no":"06","title":"Methane hydrate","titleCN":"甲烷水合物","definition":"an ice-like solid in which methane sits inside cages of water molecules, found in deep sediments","definitionCN":"甲烷被水分子笼状结构包裹的冰状固体，见于深海沉积层","example":"Methane hydrate is an ice-like solid found in deep sea sediments.","exampleCN":"甲烷水合物是一种见于深海沉积层的冰状固体。","why":"Cold and pressure let water build cages around the gas, storing energy in a form that looks like ice.","whyCN":"低温与高压让水在气体周围搭起笼子，把能量储存在看起来像冰的形态里。"},{"no":"07","title":"Methane in the carbon cycle","titleCN":"碳循环中的甲烷","definition":"the short-lived but intense step in which carbon passes through a one-carbon gas before returning to carbon dioxide","definitionCN":"碳以单碳气体形态经过的短暂而强烈的环节，随后返回二氧化碳","example":"Methane has a short lifetime in the air, but it is a potent warming agent.","exampleCN":"甲烷在大气中的寿命很短，却是强效的升温因素。","why":"A gas that leaves the air quickly can still do damage quickly, so lifetime and potency must be read together.","whyCN":"离开大气很快的气体也能很快造成影响，因此寿命与强度必须一起看。"},{"no":"08","title":"Methane on other worlds","titleCN":"其他天体上的甲烷","definition":"the same molecule detected in the atmospheres and surfaces of other planets and moons","definitionCN":"在其他行星与卫星的大气或表面探测到的同一分子","example":"Titan's atmosphere is rich in methane, giving it an orange haze.","exampleCN":"土卫六的大气富含甲烷，因此呈现橙色雾霭。","why":"The molecule is common enough in the solar system that it becomes a marker of chemistry elsewhere.","whyCN":"这种分子在太阳系中足够常见，因而成为其他地方化学活动的标记。"},{"no":"09","title":"Mine gas","titleCN":"矿井瓦斯","definition":"the methane that accumulates in coal mines and must be drained or ventilated to prevent explosion","definitionCN":"积聚在煤矿中、必须抽排或通风以防爆炸的甲烷","example":"Mine methane has to be ventilated before it can explode.","exampleCN":"矿井甲烷必须先通风排出，否则就会爆炸。","why":"A gas that is harmless in a kitchen becomes a hazard when it collects in a confined working space.","whyCN":"在厨房里无害的气体，一旦在封闭的工作空间聚集就成了危险。"}],"etymology":{"intro":{"en":"The name was coined in the nineteenth century from the Greek words for wine and wood, by way of the radical methyl. The coinage is documented; the exact year it was proposed is usually given as approximate.","cn":"这个名称于十九世纪由表示「酒」与「木」的希腊词经「甲基」这一基团名构造而成。造词过程有据，提出的确切年份通常只给约数。"},"items":[{"era":"GREEK METHY","en":"Methy meant wine, and the early chemists linked the radical to alcohol.","cn":"这个词表示酒，早期化学家因此把这个基团与酒精联系起来。"},{"era":"GREEK HYLE","en":"Hyle meant wood or matter, the second half of the older radical name.","cn":"这个词表示木或物质，是较早基团名的后半部分。"},{"era":"FRENCH METHYLENE","en":"French chemists formed a name for the radical from those two Greek elements.","cn":"法国化学家由这两个希腊成分构造出该基团的名称。"},{"era":"THE RADICAL METHYL","en":"The shorter radical name methyl then served as the base for the gas.","cn":"较短的基团名「甲基」随后成为这种气体的构词基础。"},{"era":"THE SUFFIX -ANE","en":"A suffix was chosen to mark hydrocarbons with only single bonds.","cn":"人们选定一个词尾来标记只含单键的烃。"},{"era":"THE COINAGE METHANE","en":"Methyl plus that suffix gave methane, proposed in the eighteen sixties and quickly adopted.","cn":"「甲基」加上该词尾得到甲烷，于十九世纪六十年代提出并被迅速采用。"}]},"similar":{"note":{"en":"The first group shares the methyl stem or the alkane suffix; the second group names other gases of the same family or of the carbon cycle.","cn":"第一组共享「甲基」词干或烷烃词尾；第二组指同族或碳循环中的其他气体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"methyl","ipa":"/ˈmiːθaɪl/","tag":"same stem","definition":"The chemical group of one carbon and three hydrogens.","definitionCN":"一个碳与三个氢组成的化学基团。"},{"word":"methanol","ipa":"/ˈmiːθənɒl/","tag":"same stem","definition":"The simplest alcohol, one carbon with an attached hydroxyl group.","definitionCN":"最简单的醇，一个碳上连有羟基。"},{"word":"methylene","ipa":"/ˈmiːθɪliːn/","tag":"same stem","definition":"The older radical name from which methyl was shortened.","definitionCN":"较早的基团名，甲基由其缩短而来。"},{"word":"ethane","ipa":"/ˈiːθeɪn/","tag":"same series","definition":"The two-carbon member of the same alkane series.","definitionCN":"同一烷烃系列中的二碳成员。"},{"word":"methanogen","ipa":"/ˈmiːθənədʒen/","tag":"derived","definition":"A microbe that produces methane.","definitionCN":"产生甲烷的微生物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"natural gas","ipa":"/ˈnætʃrəl ɡæs/","tag":"near meaning","definition":"The fuel mixture that is mostly methane.","definitionCN":"以甲烷为主的燃料混合物。"},{"word":"biogas","ipa":"/ˈbaɪəʊɡæs/","tag":"near meaning","definition":"Gas produced by decomposing organic matter.","definitionCN":"有机物分解产生的气体。"},{"word":"carbon dioxide","ipa":"/ˈkɑːbən daɪˈɒksaɪd/","tag":"near meaning","definition":"The two-oxygen gas that methane becomes when it burns or breaks down.","definitionCN":"甲烷燃烧或分解后生成的含两个氧的气体。"},{"word":"greenhouse gas","ipa":"/ˈɡriːnhaʊs ɡæs/","tag":"near meaning","definition":"Any gas that traps heat in the atmosphere.","definitionCN":"任何在大气中截留热量的气体。"},{"word":"marsh gas","ipa":"/ˈmɑːʃ ɡæs/","tag":"near meaning","definition":"An old name for methane bubbling out of wetlands.","definitionCN":"对湿地冒出的甲烷的旧称。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the gas from a single molecule to the stove, the farm, the landfill and the mine; abstract ones treat it as a short-lived but strong lever on the climate.","cn":"正常联想沿着气体从单个分子到灶台、农场、填埋场与矿井展开；抽象联想把它看作对气候短暂却有力的杠杆。"},"normal":[{"en":"One carbon holding four hydrogens: that is the whole molecule.","cn":"一个碳抱四个氢，整个分子就是这样。"},{"en":"A kitchen flame is methane meeting enough oxygen.","cn":"厨房的火焰就是甲烷遇到充足的氧气。"},{"en":"Cows and flooded fields make it without any flame at all.","cn":"牛与淹水的田地完全不靠火焰也能制造它。"},{"en":"Buried waste releases it, and pipelines can collect it.","cn":"埋藏的垃圾会释放它，管道可以把它收集起来。"},{"en":"In a mine the same gas must be drained before it gathers.","cn":"在矿井里，同样的气体必须在其聚集前被抽走。"}],"abstract":[{"en":"Methane is a short-lived gas with a loud voice.","cn":"甲烷是一种寿命短、嗓门大的气体。"},{"en":"Because it leaves quickly, its damage is concentrated in time.","cn":"因为它离开得快，它的影响在时间上被集中。"},{"en":"A molecule that appears in kitchens, swamps and distant moons is the same molecule everywhere.","cn":"出现在厨房、沼泽与遥远卫星上的分子，在任何地方都是同一个分子。"}]},"examples":[{"en":"The lab measured methane in air samples from the landfill.","cn":"实验室测量了填埋场空气样本中的甲烷。"},{"en":"Methane is a far more potent warming gas than carbon dioxide.","cn":"甲烷是比二氧化碳强得多的升温气体。"},{"en":"Drilling released methane that had been trapped in the sediment.","cn":"钻探释放了原本封存在沉积物中的甲烷。"}],"dict_mnemonic":{"note":"读音记忆 · 非词源","text":"读作「米散」——一个碳四个氢的气体散在空气里：甲烷","word":"methane"},"root":"由十九世纪化学命名体系构造：希腊语 methy「酒」与 hyle「木、物质」先构成基团名 methyl，再加表示单键烃的词尾构成 methane。「甲烷」这一中文名取「甲」为第一、首位的含义。造词过程清楚，确切提出年份为约数。","sensesIntro":{"en":"Nine senses follow one molecule from the flask to the stove, the herd, the landfill, the atmosphere, the deep sea, other worlds and the mine.","cn":"九个义项跟踪同一个分子，从烧瓶走到灶台、畜群、填埋场、大气、深海、其他天体与矿井。"},"semanticMap":{"core":{"en":"CORE IMAGE: a steady blue flame on a stove.","cn":"核心意象：灶台上一簇稳定的蓝色火焰。"},"chain":["THE MOLECULE","FUEL","FARMS AND WASTE","THE ATMOSPHERE","DEEP STORES","OTHER WORLDS AND MINES"],"branches":[{"senses":"01 · 02","en":"THE CORE: one carbon with four hydrogens, and the fuel that is mostly this gas.","cn":"核心：一个碳配四个氢，以及以它为绝对主体的燃料。"},{"senses":"03 · 04","en":"THE PRODUCERS: animals and flooded fields, then buried waste and digesters.","cn":"产生者：牲畜与淹水田地，然后是埋藏垃圾与消化器。"},{"senses":"05 · 07","en":"THE CLIMATE ROLE: a strong absorber with a short stay in the air.","cn":"气候角色：强吸收者，但在空气中停留短暂。"},{"senses":"06","en":"THE DEEP STORE: gas held in icy cages under the sea floor.","cn":"深海储存：被封在海底冰笼中的气体。"},{"senses":"08 · 09","en":"THE ELSEWHERE AND THE DANGER: distant atmospheres and the confined space of a mine.","cn":"他处与危险：遥远天体的大气，以及矿井的封闭空间。"}]},"affixes":{"intro":{"en":"Two Greek nouns were fused into a chemical radical name, and a suffix for single bonds completed the gas.","cn":"两个希腊名词被融合成一个化学基团名，再由一个表示单键的词尾完成这种气体的命名。"},"latinIntro":{"en":"Greek supplies the words for wine and wood; the radical name came through French, and the gas name was coined in German and English chemistry. No Latin noun underlies the word, so the Latin entry list is left empty.","cn":"希腊语提供了表示「酒」与「木」的词；基团名经法语传来，气体名则由德国与英国化学界构造。词背后没有拉丁名词，因此拉丁词条列表留空。"},"items":[{"word":"methy","structure":"Greek noun","meaning":"wine","meaningCN":"酒","example":"The first element tied the radical to alcohol.","exampleCN":"第一个成分把这个基团与酒精联系起来。"},{"word":"hyle","structure":"Greek noun","meaning":"wood, matter","meaningCN":"木；物质","example":"The second element named the material side of the radical.","exampleCN":"第二个成分命名该基团的物质一面。"},{"word":"methyl","structure":"chemical radical name","meaning":"one carbon with three hydrogens","meaningCN":"甲基","example":"It became the base of the gas name.","exampleCN":"它成为气体名称的基础。"},{"word":"-ene","structure":"chemical suffix","meaning":"double-bond radical","meaningCN":"双键基团词尾","example":"It marked the older radical rather than the final gas.","exampleCN":"它标记较早的基团而非最终的气体。"},{"word":"-ane","structure":"chemical suffix","meaning":"single-bonded hydrocarbon","meaningCN":"单键烃词尾","example":"It made clear that the gas has only single bonds.","exampleCN":"它明确表示这种气体只含单键。"},{"word":"methane","structure":"English noun","meaning":"the first alkane","meaningCN":"甲烷","example":"The name marks the first member of the series.","exampleCN":"这个名称标记该系列的第一个成员。"},{"word":"methanol","structure":"English noun","meaning":"the simplest alcohol","meaningCN":"甲醇","example":"The same stem with an alcohol ending.","exampleCN":"同一词干加上醇类词尾。"},{"word":"methanogen","structure":"English noun","meaning":"methane-producing microbe","meaningCN":"产甲烷菌","example":"The stem plus a suffix for a producer.","exampleCN":"词干加上表示「产生者」的词尾。"}],"latinEntries":[],"derivatives":[{"word":"methyl","pos":"n.","zh":"由本词词干加表示「基团」的成分构成，义为「甲基」"},{"word":"methanol","pos":"n.","zh":"由「甲基」加表示「醇」的成分构成，义为「甲醇」"},{"word":"methane hydrate","pos":"n.","zh":"本词与表示「水合物」的词构成的复合术语，义为「甲烷水合物」"},{"word":"methanogen","pos":"n.","zh":"由本词加表示「产生者」的成分构成，义为「产甲烷菌」"},{"word":"methanogenesis","pos":"n.","zh":"由本词加表示「生成」的成分构成，义为「产甲烷过程」"},{"word":"methanotrophic","pos":"adj.","zh":"由本词加表示「以……为食」的成分构成，义为「食甲烷的」"}]}},{"word":"atmospheric circulation","ipa_uk":"/ˌætməsˈferɪk ˌsɜːkjəˈleɪʃən/","ipa_us":"/ˌætməsˈferɪk ˌsɜːrkjəˈleɪʃən/","definition_zh":"大气环流；大气中热量与水汽的大尺度输送与循环","definition_en":"the large-scale movement of air that carries heat and moisture around a planet","core_image":"一张挂在墙上的全球地图，上面画满从赤道升起、向两极弯曲的箭头","scene":"气象台的屏幕上，一圈圈箭头从赤道升起、向两极偏转，值班员在图上标出雨带。The map showed atmospheric circulation lifting warm air at the equator and turning it poleward.","sceneCN":"这里指全球尺度的大气环流（第 1 个义项：大气热量与水汽的大范围输送）；句意为图上显示大气环流在赤道抬起暖空气，并使其向极地方向偏转。图中可辨识物件：气象屏、箭头流线、雨带标记、全球地图。","pos":[{"tag":"n.","zh":"名词短语：多作不可数，指大气的大尺度环流；强调某一具体环流时可加修饰语"}],"collocations":[{"phrase":"global atmospheric circulation","zh":"全球大气环流"},{"phrase":"general atmospheric circulation","zh":"大气环流总体"},{"phrase":"weaken atmospheric circulation","zh":"削弱大气环流"},{"phrase":"atmospheric circulation pattern","zh":"大气环流型"},{"phrase":"tropical atmospheric circulation","zh":"热带大气环流"},{"phrase":"atmospheric circulation and rainfall","zh":"大气环流与降水"},{"phrase":"a model of atmospheric circulation","zh":"大气环流模型"}],"forms":[{"label":"短语原形","form":"atmospheric circulation"},{"label":"复数（少见）","form":"atmospheric circulations"},{"label":"定语用法","form":"atmospheric circulation + 名词"},{"label":"介词短语","form":"driven by atmospheric circulation"},{"label":"构成成分一","form":"atmospheric"},{"label":"构成成分二","form":"circulation"},{"label":"相关名词","form":"atmosphere"}],"derivatives":[{"word":"atmosphere","pos":"n.","zh":"由希腊语表示「蒸汽」与「球体」的成分构成，义为「大气；气氛」"},{"word":"atmospheric","pos":"adj.","zh":"由本短语第一成分构成，义为「大气的」"},{"word":"circulate","pos":"v.","zh":"由拉丁语表示「小环」的名词构成的动词，义为「循环；流通」"},{"word":"circulation","pos":"n.","zh":"由动词加表示「作用、过程」的词尾构成，义为「循环；流通」"},{"word":"circulatory","pos":"adj.","zh":"由本短语第二成分加形容词词尾构成，义为「循环的」"}],"senses":[{"no":"01","title":"Global circulation","titleCN":"全球大气环流","definition":"the planet-wide system of winds that moves heat from warm regions to cold ones","definitionCN":"把热量从温暖区域输送到寒冷区域的行星尺度风系","example":"Atmospheric circulation carries heat from the tropics toward the poles.","exampleCN":"大气环流把热量从热带输送到两极。","why":"Without a moving atmosphere the tropics would keep their heat and the poles would keep their cold.","whyCN":"若没有运动的大气，热带会一直保有热量，两极则一直寒冷。"},{"no":"02","title":"The three-cell model","titleCN":"三圈环流模型","definition":"the textbook division of global circulation into polar, mid-latitude and tropical cells","definitionCN":"教科书把全球环流分为极地、中纬度与热带三个环流圈","example":"The three-cell model simplifies atmospheric circulation into polar, mid-latitude and tropical cells.","exampleCN":"三圈环流模型把大气环流简化为极地、中纬度与热带三个环流圈。","why":"A single cell cannot span a rotating planet, so the flow breaks into three bands per hemisphere.","whyCN":"单个环流圈无法覆盖一颗自转的行星，因此每个半球分裂为三段。"},{"no":"03","title":"The Hadley cell","titleCN":"哈得来环流","definition":"the tropical overturning in which air rises at the equator, flows poleward aloft and sinks near thirty degrees","definitionCN":"热带地区的翻转环流：空气在赤道上升，高空向极地流动，在纬度约三十度处下沉","example":"The Hadley cell is the tropical part of atmospheric circulation.","exampleCN":"哈得来环流是大气环流中热带的那一部分。","why":"A named cell makes the tropics a single machine with a rising and a sinking side.","whyCN":"一个被命名的环流圈把热带变成一台只有上升侧与下沉侧的机器。"},{"no":"04","title":"The Walker circulation","titleCN":"沃克环流","definition":"the east-west overturning over the equatorial Pacific that links sea temperature to rainfall","definitionCN":"赤道太平洋上东西方向的翻转环流，把海温与降水联系起来","example":"The Walker circulation is a key part of atmospheric circulation over the Pacific.","exampleCN":"沃克环流是太平洋上空大气环流的关键部分。","why":"The tropics also overturn along the equator, not only across latitudes.","whyCN":"热带不仅在纬向翻转，也沿赤道方向翻转。"},{"no":"05","title":"The jet stream","titleCN":"急流","definition":"a narrow fast current of air in the upper troposphere that steers weather systems","definitionCN":"对流层上部狭窄而快速的气流，引导天气系统移动","example":"Jet streams are fast ribbons within the upper atmospheric circulation.","exampleCN":"急流是上层大气环流中快速的气带。","why":"Concentrating the flow into a narrow band makes it far faster than the surrounding air.","whyCN":"把流动集中于狭窄的一条，使它远快于周围空气。"},{"no":"06","title":"Monsoon circulation","titleCN":"季风环流","definition":"a seasonal reversal of winds between land and sea caused by uneven heating","definitionCN":"海陆受热不均导致风向随季节反向的环流","example":"Monsoon circulation is the seasonal part of atmospheric circulation that reverses with the seasons.","exampleCN":"季风环流是大气环流中随季节反向的那一部分。","why":"Land heats faster than water, so the pressure pattern flips and the wind follows.","whyCN":"陆地升温快于水面，气压格局翻转，风便随之转向。"},{"no":"07","title":"Circulation and climate zones","titleCN":"环流与气候带","definition":"the link between patterns of rising and sinking air and the wet or dry zones they produce","definitionCN":"空气上升与下沉的格局同其所造成的湿润或干旱地带之间的联系","example":"Regions with weak atmospheric circulation receive little rainfall.","exampleCN":"大气环流较弱的地区降水很少。","why":"Rising air rains and sinking air dries, so the map of circulation becomes a map of climates.","whyCN":"上升的空气下雨，下沉的空气致旱，环流图因此成了气候图。"},{"no":"08","title":"Circulation on other planets","titleCN":"其他行星的大气环流","definition":"the wind systems of other atmospheres, shaped by their own rotation, heating and composition","definitionCN":"其他天体大气的风系，由其自转、受热与成分塑形","example":"Venus has an atmospheric circulation that turns far faster than the planet itself.","exampleCN":"金星的大气环流旋转得远比行星本身快。","why":"The same physics applied elsewhere produces circulation patterns that no earthly textbook predicts.","whyCN":"同一套物理用到别处，会产生地球教科书无法预言的运动格局。"},{"no":"09","title":"Indoor air circulation","titleCN":"室内空气循环","definition":"the movement of air within a room that keeps temperature and freshness even","definitionCN":"房间内使温度与新鲜度保持均匀的空气流动","example":"Good atmospheric circulation in a room keeps the air from going stale.","exampleCN":"房间内良好的空气循环能防止空气变得沉闷。","why":"The same words scale down from a planet to a room, because both depend on air being moved rather than still.","whyCN":"同一组词从行星缩小到房间仍可用，因为两者都依赖空气被移动而非静止。"}],"etymology":{"intro":{"en":"The phrase joins a Greek-derived adjective for the vapour sphere around a world to a Latin-derived noun for movement in a ring. Both elements are well documented; the phrase took its meteorological sense in the nineteenth century, so its first use is approximate.","cn":"这个短语把一个源自希腊语、表示环绕世界的蒸汽层的形容词，与一个源自拉丁语、表示环状运动的名词组合起来。两个成分来源有据；短语在十九世纪取得气象学含义，确切首见为约数。"},"items":[{"era":"GREEK ATMOS","en":"Atmos meant vapour or steam, the invisible envelope of a world.","cn":"这个词表示蒸汽或雾气，即环绕世界的那层看不见的东西。"},{"era":"GREEK SPHAIRA","en":"Sphaira meant a ball or sphere, and the two together named the vapour sphere.","cn":"这个词表示球体，两者合起来命名了「蒸汽之球」。"},{"era":"LATIN CIRCULUS","en":"Circulus was a small ring, the diminutive of the word for a circle.","cn":"这个词是表示圆的名词的小称，意为小环。"},{"era":"LATIN CIRCULARE","en":"The verb meant to make round or to move in a circle.","cn":"这个动词意为做成圆形或在环中运动。"},{"era":"ENGLISH CIRCULATION","en":"English first applied the noun to blood, then to any fluid moving in a circuit.","cn":"英语先用这个名词指血液循环，后指任何沿回路流动的流体。"},{"era":"THE METEOROLOGICAL PHRASE","en":"Nineteenth-century meteorology needed a term for planetary-scale wind systems, and the two words were joined.","cn":"十九世纪的气象学需要一个指行星尺度风系的术语，两个词于是被组合起来。"}]},"similar":{"note":{"en":"The first group shares the adjective atmospheric or the noun circulation; the second group names the motion of air in plainer terms.","cn":"第一组共享形容词「大气的」或名词「环流」；第二组用更朴素的说法指空气的运动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"atmospheric pressure","ipa":"/ˌætməsˈferɪk ˈpreʃə/","tag":"same adjective","definition":"The weight of the air column at a point.","definitionCN":"某点上空气柱的重量。"},{"word":"atmospheric layer","ipa":"/ˌætməsˈferɪk ˈleɪə/","tag":"same adjective","definition":"One of the stacked shells of a planet's air.","definitionCN":"行星大气层叠结构中的一层。"},{"word":"atmospheric model","ipa":"/ˌætməsˈferɪk ˈmɒdl/","tag":"same adjective","definition":"A numerical representation of the state of the air.","definitionCN":"对大气状态的数值表示。"},{"word":"circulation","ipa":"/ˌsɜːkjəˈleɪʃən/","tag":"component","definition":"Movement of a fluid around a closed path.","definitionCN":"流体沿闭合路径的运动。"},{"word":"atmosphere","ipa":"/ˈætməsfɪə/","tag":"same root","definition":"The envelope of gas around a planet.","definitionCN":"行星周围的气体外壳。"}]},{"heading":"NEAR MEANING","entries":[{"word":"air flow","ipa":"/eə fləʊ/","tag":"near meaning","definition":"The movement of air from one place to another.","definitionCN":"空气从一处到另一处的运动。"},{"word":"wind pattern","ipa":"/wɪnd ˈpætən/","tag":"near meaning","definition":"The recurring shape of winds over a region.","definitionCN":"某一地区风的反复出现的形态。"},{"word":"convection","ipa":"/kənˈvekʃən/","tag":"near meaning","definition":"Vertical motion driven by heating from below.","definitionCN":"由下方加热驱动的垂直运动。"},{"word":"global wind system","ipa":"/ˈɡləʊbl wɪnd ˈsɪstəm/","tag":"near meaning","definition":"The whole set of prevailing winds on a planet.","definitionCN":"一颗行星上全部盛行风的总和。"},{"word":"weather system","ipa":"/ˈweðə ˈsɪstəm/","tag":"near meaning","definition":"A moving pattern of pressure, cloud and rain.","definitionCN":"移动的气压、云与降水格局。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations start at the equator and follow the arrows outward and back; abstract ones treat circulation as a way of evening out what the sun makes uneven.","cn":"正常联想从赤道出发，沿着箭头向外再返回；抽象联想把环流看作把太阳造成的不均匀重新摊平的方式。"},"normal":[{"en":"Warm air rises at the equator and turns poleward.","cn":"暖空气在赤道上升，并向极地方向偏转。"},{"en":"It sinks near thirty degrees, which is why deserts sit there.","cn":"它在纬度约三十度处下沉，沙漠因此分布在那里。"},{"en":"Each hemisphere splits into three cells because the planet spins.","cn":"由于行星自转，每个半球分成三个环流圈。"},{"en":"A jet stream is the fast core of the upper flow.","cn":"急流是上层气流中速度快的那条核心。"},{"en":"Over the Pacific the flow also turns east to west, and that is the Walker cell.","cn":"在太平洋上空气流还东西向翻转，那就是沃克环流。"}],"abstract":[{"en":"Circulation is the atmosphere refusing to let heat stay where it landed.","cn":"环流是大气拒绝让热量留在原地。"},{"en":"Every rising column must have somewhere to sink.","cn":"每一处上升的气柱都必须在某处下沉。"},{"en":"Wind is not weather's decoration; it is its accounting system.","cn":"风不是天气的装饰，而是天气的记账系统。"}]},"examples":[{"en":"Atmospheric circulation redistributes heat from low to high latitudes.","cn":"大气环流把热量从低纬重新分配到高纬。"},{"en":"The study linked weaker atmospheric circulation to drier summers.","cn":"这项研究把减弱的大气环流与更干旱的夏季联系起来。"},{"en":"Climate models resolve atmospheric circulation at ever finer scales.","cn":"气候模式以越来越精细的尺度解析大气环流。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"atmospheric（大气的）+ circulation（循环）——大气的循环，即大气环流","word":"atmospheric circulation"},"root":"由 atmospheric 与 circulation 组合。前者源自希腊语 atmos「蒸汽」与 sphaira「球体」；后者源自拉丁语 circulus「小环」及其动词 circulare「使成环状」。短语在十九世纪气象学中取得现代含义，确切首见年代不确定。","sensesIntro":{"en":"Nine senses move outward from the planet-wide flow to its cells, its jet, its seasonal reversal, its climates, other worlds and finally a single room.","cn":"九个义项从行星尺度的流动向外展开，走向各个环流圈、急流、季节反转、气候带、其他天体，最后收束到一个房间。"},"semanticMap":{"core":{"en":"CORE IMAGE: arrows rising at the equator and bending toward the poles on a wall map.","cn":"核心意象：墙图上从赤道升起、向两极弯曲的箭头。"},"chain":["THE GLOBAL FLOW","THREE CELLS","TROPICAL CELL","PACIFIC CELL","JET AND MONSOON","CLIMATE AND ELSEWHERE"],"branches":[{"senses":"01 · 02","en":"THE CORE: the whole moving envelope and the three-cell shorthand used to teach it.","cn":"核心：整个运动的大气层，以及用于教学的「三圈」简写。"},{"senses":"03 · 04","en":"THE NAMED CELLS: one overturning across latitudes, one across the equatorial Pacific.","cn":"被命名的环流圈：一个跨纬度翻转，一个沿赤道太平洋翻转。"},{"senses":"05 · 06","en":"THE FAST AND SEASONAL: a narrow upper jet and a wind that reverses with the seasons.","cn":"快速与季节性的两种：狭窄的高空急流，以及随季节反向的风。"},{"senses":"07 · 09","en":"THE SCALES: wet and dry climate zones, other planets, and a single room.","cn":"尺度变化：干湿气候带、其他行星，以及单个房间。"},{"senses":"08","en":"THE COMPARISON: circulation on a world that spins differently.","cn":"比较对象：自转方式不同的世界上的环流。"}]},"affixes":{"intro":{"en":"A Greek noun of vapour plus a Greek noun of sphere give the first element; a Latin ring gives the second.","cn":"一个希腊语「蒸汽」名词加一个希腊语「球体」名词构成第一成分；一个拉丁语「环」构成第二成分。"},"latinIntro":{"en":"Greek supplies atmos and sphaira; Latin supplies circulus, its verb and the noun of motion.","cn":"希腊语提供了「蒸汽」与「球体」；拉丁语提供了「小环」、其动词以及表示运动的名词。"},"items":[{"word":"atmos","structure":"Greek noun","meaning":"vapour, steam","meaningCN":"蒸汽；雾气","example":"It named the invisible envelope rather than the air itself.","exampleCN":"它命名的是看不见的外壳，而非空气本身。"},{"word":"sphaira","structure":"Greek noun","meaning":"ball, sphere","meaningCN":"球体","example":"It supplied the second half of atmosphere.","exampleCN":"它提供了「大气」一词的后半部分。"},{"word":"-ic","structure":"Latin suffix","meaning":"relating to","meaningCN":"与……相关的","example":"It turns atmosphere into an adjective.","exampleCN":"它把「大气」变成形容词。"},{"word":"circulus","structure":"Latin noun","meaning":"small ring","meaningCN":"小环","example":"The diminutive sense survives in the idea of a closed loop.","exampleCN":"小称含义残留在「闭合回路」这一观念中。"},{"word":"circulare","structure":"Latin verb","meaning":"to make round, to move in a circle","meaningCN":"使成圆形；环行","example":"The verb yields the English verb circulate.","exampleCN":"这个动词产生英语动词「循环」。"},{"word":"-ation","structure":"Latin noun suffix","meaning":"action or process","meaningCN":"动作或过程","example":"It names movement around a circuit.","exampleCN":"它命名沿回路的运动。"},{"word":"circulation","structure":"English noun","meaning":"movement around a closed path","meaningCN":"循环；流通","example":"The noun first described blood and later air.","exampleCN":"这个名词先指血液，后指空气。"},{"word":"atmospheric","structure":"English adjective","meaning":"of the atmosphere","meaningCN":"大气的","example":"The adjective makes the phrase specific to a planet's air.","exampleCN":"这个形容词使短语专门指行星的大气。"}],"latinEntries":[{"word":"circulus","structure":"Latin noun","meaning":"small ring","meaningCN":"小环"},{"word":"circulare","structure":"Latin verb","meaning":"to make round","meaningCN":"使成圆形"},{"word":"circulatio","structure":"Latin noun","meaning":"a going round","meaningCN":"循环"}],"derivatives":[{"word":"atmosphere","pos":"n.","zh":"由希腊语表示「蒸汽」与「球体」的成分构成，义为「大气；气氛」"},{"word":"atmospheric","pos":"adj.","zh":"由本短语第一成分构成，义为「大气的」"},{"word":"circulate","pos":"v.","zh":"由拉丁语表示「小环」的名词构成的动词，义为「循环；流通」"},{"word":"circulation","pos":"n.","zh":"由动词加表示「作用、过程」的词尾构成，义为「循环；流通」"},{"word":"circulatory","pos":"adj.","zh":"由本短语第二成分加形容词词尾构成，义为「循环的」"}]}},{"word":"El Niño","ipa_uk":"/el ˈniːnjəʊ/","ipa_us":"/el ˈniːnjoʊ/","definition_zh":"厄尔尼诺；赤道太平洋海面温度异常偏暖、并改变全球天气的气候现象","definition_en":"a recurring warming of the equatorial Pacific Ocean that alters weather patterns around the world","core_image":"秘鲁渔港的清晨，空网被拖上甲板，港口的黑板上记着当月的渔获数字","scene":"秘鲁渔港的清晨，渔民把几乎空了的渔网拖上甲板，港口的黑板上记着当月的渔获数字。The anchovy boats returned almost empty as El Niño shut down the upwelling.","sceneCN":"这里指厄尔尼诺对渔场的影响（第 5 个义项：暖水抑制上升流、导致渔获崩塌）；句意为厄尔尼诺切断了上升流，鳀鱼船几乎空手而归。图中可辨识物件：渔船、空渔网、港口黑板、渔获数字。","pos":[{"tag":"n.","zh":"专有名词短语：指这一气候现象；可作定语修饰年份或事件"}],"collocations":[{"phrase":"a strong El Niño","zh":"强厄尔尼诺"},{"phrase":"an El Niño year","zh":"厄尔尼诺年"},{"phrase":"the onset of El Niño","zh":"厄尔尼诺的开始"},{"phrase":"El Niño conditions","zh":"厄尔尼诺状态"},{"phrase":"during El Niño","zh":"在厄尔尼诺期间"},{"phrase":"El Niño forecast","zh":"厄尔尼诺预测"},{"phrase":"the El Niño event","zh":"这次厄尔尼诺事件"}],"forms":[{"label":"短语原形","form":"El Niño"},{"label":"复数","form":"El Niños"},{"label":"定语用法","form":"El Niño + 名词"},{"label":"介词短语","form":"during El Niño"},{"label":"不定冠词用法","form":"an El Niño"},{"label":"构成成分一","form":"El"},{"label":"构成成分二","form":"Niño"}],"derivatives":[{"word":"El Niño year","pos":"n.","zh":"本词加表示「年份」的词构成，义为「厄尔尼诺年」"},{"word":"El Niño event","pos":"n.","zh":"本词加表示「事件」的词构成，义为「厄尔尼诺事件」"},{"word":"El Niño conditions","pos":"n.","zh":"本词加表示「状态」的词构成，义为「厄尔尼诺状态」"},{"word":"El Niño warming","pos":"n.","zh":"本词加表示「增暖」的词构成，义为「厄尔尼诺增暖」"},{"word":"El Niño Southern Oscillation","pos":"n.","zh":"本词与表示「南方涛动」的词组构成的完整术语"}],"senses":[{"no":"01","title":"The climate pattern","titleCN":"厄尔尼诺现象","definition":"a recurring pattern in which the tropical Pacific shifts into a warm phase with worldwide effects","definitionCN":"赤道太平洋反复进入暖位相并产生全球影响的气候格局","example":"El Niño is a recurring warming of the equatorial Pacific that reshapes weather worldwide.","exampleCN":"厄尔尼诺是赤道太平洋反复出现的增暖，会重塑全球天气。","why":"A local ocean change turned out to have global reach, so the name had to cover a pattern rather than a current.","whyCN":"一处局部的海洋变化竟有全球影响，因此这个名称必须涵盖一种格局而非一股洋流。"},{"no":"02","title":"The warm water anomaly","titleCN":"海温异常增暖","definition":"the spread of unusually warm surface water from the western Pacific toward the central and eastern Pacific","definitionCN":"异常温暖的表层水从西太平洋向中、东太平洋扩展","example":"During El Niño, warm water spreads east across the equatorial Pacific.","exampleCN":"在厄尔尼诺期间，暖水沿赤道太平洋向东扩展。","why":"Trade winds normally pile warm water in the west; when they weaken, the warm pool slides east.","whyCN":"信风通常把暖水堆在西侧；信风减弱时，暖水池便向东滑去。"},{"no":"03","title":"The event cycle","titleCN":"事件与周期","definition":"the irregular return of warm episodes every few years, never on a fixed timetable","definitionCN":"暖事件每隔几年不规则地重现，从无固定时间表","example":"El Niño returns every two to seven years, though not on a fixed schedule.","exampleCN":"厄尔尼诺每隔两到七年重现一次，但时间表并不固定。","why":"The rhythm is real but not periodic, which makes forecasting a probability problem rather than a calendar.","whyCN":"这种节律真实存在却并非周期性的，因此预测成了概率问题而非查日历。"},{"no":"04","title":"Global weather effects","titleCN":"全球天气影响","definition":"the shift of rain belts and storm tracks that follows the warm phase","definitionCN":"随暖位相而发生的雨带与风暴路径移动","example":"El Niño typically brings drought to the western Pacific and storms to the east.","exampleCN":"厄尔尼诺通常给西太平洋带来干旱，给东太平洋带来风暴。","why":"Moving the warm pool moves where air rises, and rainfall follows rising air.","whyCN":"暖水池移动就移动了空气上升的位置，而降水跟着上升气流走。"},{"no":"05","title":"Effects on fisheries","titleCN":"对渔业的影响","definition":"the collapse of upwelling and fish catches along the eastern Pacific coast","definitionCN":"东太平洋沿岸上升流与渔获的崩溃","example":"The last strong El Niño devastated the anchovy catch off Peru.","exampleCN":"上一次强厄尔尼诺重创了秘鲁沿岸的鳀鱼渔获。","why":"Warm water suppresses the rise of cold nutrient-rich water, and the food chain loses its base.","whyCN":"暖水抑制了富含营养的冷水上涌，食物链因此失去基础。"},{"no":"06","title":"Drought and floods","titleCN":"干旱与洪水","definition":"the extremes of too little and too much rain that appear in different regions during one event","definitionCN":"同一次事件中不同地区出现的少雨与多雨极端","example":"El Niño often means drought in one country and floods in another.","exampleCN":"厄尔尼诺常常意味着一国干旱而另一国洪水。","why":"A single displaced rain belt creates both deficits and surpluses at once.","whyCN":"一条被移动的雨带会同时造成缺雨与多雨。"},{"no":"07","title":"Agriculture and the economy","titleCN":"农业与经济","definition":"the crop losses and price movements that follow a strong event","definitionCN":"强事件之后出现的作物损失与价格波动","example":"A strong El Niño can raise food prices for a whole region.","exampleCN":"一次强厄尔尼诺会抬升整个地区的食品价格。","why":"Weather becomes economic once harvests and prices move with it.","whyCN":"当收成与价格随天气波动，天气就成了经济问题。"},{"no":"08","title":"Monitoring and forecasting","titleCN":"监测与预测","definition":"the buoy and satellite networks that track the warm phase and issue seasonal outlooks","definitionCN":"追踪暖位相并发布季节展望的浮标与卫星网络","example":"Satellites and buoys now give months of warning before El Niño peaks.","exampleCN":"卫星与浮标现在能在厄尔尼诺达到顶峰前数月发出预警。","why":"An ocean that can be measured in advance turns a surprise into a season-long expectation.","whyCN":"可以提前测量的海洋，把意外变成了长达一季的预期。"},{"no":"09","title":"The name itself","titleCN":"名称的来历","definition":"the Spanish phrase for the child, given by Peruvian fishermen because the warm current appeared around Christmas","definitionCN":"西班牙语中表示「孩子」的说法，秘鲁渔民因暖流在圣诞节前后出现而如此命名","example":"Fishermen in Peru gave El Niño its name, calling it the child.","exampleCN":"秘鲁渔民给厄尔尼诺起了这个名字，称它为「孩子」。","why":"A name chosen for the season of its arrival ended up naming a global phenomenon.","whyCN":"一个因到来季节而得名的称呼，最终命名了一种全球现象。"}],"etymology":{"intro":{"en":"The name is Spanish for the child, applied by Peruvian fishermen to a warm current that arrived around Christmas. The Spanish source is certain; the deeper origin of the Spanish word for child is not settled, and the first use of the name is dated only approximately.","cn":"这个名称在西班牙语中意为「孩子」，秘鲁渔民把它用在圣诞节前后到来的暖流上。西班牙语来源确定；该西班牙词更早的来源尚无定论，名称首次使用的年代也只有约数。"},"items":[{"era":"SPANISH EL","en":"El is simply the definite article, so the phrase means the child rather than any child.","cn":"这一成分只是定冠词，因此整个短语意为「那个孩子」，而非任意一个孩子。"},{"era":"SPANISH NINO","en":"Niño means a child or a boy; its deeper origin is probably a nursery word and is not settled.","cn":"这个词意为孩子或男孩；更早的来源可能是一个幼儿用词，尚无定论。"},{"era":"THE CHRISTMAS CURRENT","en":"Fishermen noticed a warm counter-current appearing near Christmas and named it after the Christ child.","cn":"渔民注意到一股暖性逆流在圣诞节前后出现，便以圣婴为其命名。"},{"era":"ENGLISH ADOPTION","en":"English borrowed the phrase in the twentieth century as the phenomenon became known beyond the region.","cn":"随着这一现象被区域之外所知，英语在二十世纪借入了这个短语。"},{"era":"LINKING OCEAN AND AIR","en":"Scientists connected the warming to a see-saw of pressure across the Pacific.","cn":"科学家把这种增暖与太平洋两端气压的跷跷板式变化联系起来。"},{"era":"THE MODERN SENSE","en":"The name now covers the whole coupled ocean-and-atmosphere event, not only the current.","cn":"这个名称如今涵盖整个海气耦合事件，而不只是那股洋流。"}]},"similar":{"note":{"en":"The first group shares the name or its compounds and includes its opposite phase; the second group describes warm phases in ordinary words.","cn":"第一组共享该名称或其复合形式，并包含它的相反位相；第二组用普通词语描述暖位相。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"El Niño year","ipa":"/el ˈniːnjəʊ jɪə/","tag":"compound","definition":"A year in which the warm phase is present.","definitionCN":"出现暖位相的年份。"},{"word":"El Niño event","ipa":"/el ˈniːnjəʊ ɪˈvent/","tag":"compound","definition":"One discrete episode of the warm phase.","definitionCN":"暖位相的一次独立事件。"},{"word":"El Niño Southern Oscillation","ipa":"/el ˈniːnjəʊ ˈsʌðən ˌɒsɪˈleɪʃən/","tag":"full term","definition":"The coupled ocean-atmosphere pattern that includes the warming.","definitionCN":"包含这种增暖的海气耦合格局。"},{"word":"La Niña","ipa":"/lə ˈniːnjə/","tag":"opposite phase","definition":"The cool phase of the same Pacific pattern.","definitionCN":"同一太平洋格局中的冷位相。"},{"word":"El Niños","ipa":"/el ˈniːnjəʊz/","tag":"plural","definition":"More than one warm episode.","definitionCN":"不止一次的暖事件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"warm phase","ipa":"/wɔːm feɪz/","tag":"near meaning","definition":"The period when the tropical Pacific is unusually warm.","definitionCN":"热带太平洋异常温暖的时期。"},{"word":"Pacific warming","ipa":"/pəˈsɪfɪk ˈwɔːmɪŋ/","tag":"near meaning","definition":"A rise in sea surface temperature across the Pacific.","definitionCN":"太平洋海表温度的上升。"},{"word":"climate anomaly","ipa":"/ˈklaɪmət əˈnɒməli/","tag":"near meaning","definition":"A departure from the usual climate pattern.","definitionCN":"偏离常态的气候格局。"},{"word":"ocean warming event","ipa":"/ˈəʊʃən ˈwɔːmɪŋ ɪˈvent/","tag":"near meaning","definition":"A discrete episode of unusually warm ocean water.","definitionCN":"海水异常温暖的一次独立事件。"},{"word":"seasonal outlook","ipa":"/ˈsiːzənl ˈaʊtlʊk/","tag":"near meaning","definition":"A forecast for the coming season.","definitionCN":"对未来一季的预测。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the warm pool sliding east and the rain belts with it; abstract ones treat the name as a remembered story that became a scientific term.","cn":"正常联想跟随暖水池向东滑动、雨带随之移动；抽象联想把这个名称看作一则被记住的故事，后来成了科学术语。"},"normal":[{"en":"Peruvian fishermen saw a warm current at Christmas and called it the child.","cn":"秘鲁渔民在圣诞节看到一股暖流，称它为「孩子」。"},{"en":"Weak trade winds let the warm pool slide east along the equator.","cn":"信风减弱时，暖水池沿赤道向东滑。"},{"en":"Air rises over the new warm water, and rain follows.","cn":"空气在新的暖水上空上升，降水随之而来。"},{"en":"Cold nutrient water stops rising off Peru, and the fish leave.","cn":"秘鲁外海富含营养的冷水不再上涌，鱼群随之离开。"},{"en":"The event returns every few years without keeping a calendar.","cn":"这一事件每隔几年回来一次，却从不看日历。"}],"abstract":[{"en":"A local current was promoted to a global pattern once its reach was mapped.","cn":"一股局部洋流在影响范围被测绘之后，被提升为一种全球格局。"},{"en":"Names given for a season can outgrow the season.","cn":"因季节而得的名号，可以长得比季节更大。"},{"en":"What looks like a failure in one port is a rearrangement of the whole ocean.","cn":"在一个港口看似失败的事，是整个海洋的重新排布。"}]},"examples":[{"en":"Forecasters declared an El Niño after the equatorial Pacific warmed for a third month.","cn":"在赤道太平洋连续三个月增暖之后，预报员宣布厄尔尼诺形成。"},{"en":"The drought was later attributed to a moderate El Niño.","cn":"这场干旱后来被归因于一次中等强度的厄尔尼诺。"},{"en":"Shipping and farming both plan around the expected El Niño.","cn":"航运与农业都围绕预期的厄尔尼诺做安排。"}],"dict_mnemonic":{"note":"词源记忆 · 非词源","text":"西班牙语里意为「孩子」，因暖流在圣诞节前后出现而得名：厄尔尼诺","word":"El Niño"},"root":"西班牙语短语，字面意为「那个孩子」，十九世纪秘鲁渔民用来称呼圣诞节前后出现的暖性逆流。西班牙语来源确定；该词更早的来源尚无定论，作为术语的首见年代亦为约数。","sensesIntro":{"en":"Nine senses move from the named pattern to its warm water, its irregular cycle, its weather, its fisheries, its droughts, its prices, its forecasts and the story behind the name.","cn":"九个义项从这一命名格局出发，走向暖水、不规则周期、天气、渔业、干旱、价格、预测，以及名称背后的故事。"},"semanticMap":{"core":{"en":"CORE IMAGE: empty nets at a Peruvian port with a catch board on the wall.","cn":"核心意象：秘鲁渔港的空网，墙上挂着渔获记录板。"},"chain":["THE PATTERN","WARM WATER EAST","IRREGULAR RETURN","WEATHER SHIFT","FISHERIES AND PRICES","WATCHING AND NAMING"],"branches":[{"senses":"01 · 02","en":"THE CORE: a named warm phase and the eastward slide of warm surface water.","cn":"核心：被命名的暖位相，以及表层暖水向东滑动。"},{"senses":"03","en":"THE RHYTHM: a return every few years with no fixed calendar.","cn":"节律：每隔几年回归，却没有固定的日历。"},{"senses":"04 · 05 · 06","en":"THE CONSEQUENCES: moved rain belts, failed upwelling, and paired droughts and floods.","cn":"后果：雨带移动、上升流失效，以及干旱与洪水的成对出现。"},{"senses":"07","en":"THE ECONOMY: harvest losses that turn into prices.","cn":"经济：收成损失转化为价格。"},{"senses":"08 · 09","en":"THE WATCHERS AND THE NAME: buoys and satellites, and the Christmas child of Peruvian fishermen.","cn":"观察者与名称：浮标与卫星，以及秘鲁渔民口中的圣婴。"}]},"affixes":{"intro":{"en":"The phrase is a Spanish article plus a Spanish noun, so it has no English affixes; its parts are two whole words.","cn":"这个短语是一个西班牙语定冠词加一个西班牙语名词，因此没有英语词缀；其组成是两个完整的词。"},"latinIntro":{"en":"Spanish supplies both words: the definite article and the word for a child. No Latin noun stands behind the phrase, so the Latin entry list is left empty.","cn":"两个词都来自西班牙语：定冠词与表示「孩子」的名词。短语背后没有拉丁名词，因此拉丁词条列表留空。"},"items":[{"word":"el","structure":"Spanish article","meaning":"the","meaningCN":"这个（定冠词）","example":"It marks the phrase as a specific child rather than any child.","exampleCN":"它表明这个短语指的是特定的那个孩子。"},{"word":"niño","structure":"Spanish noun","meaning":"child, boy","meaningCN":"孩子；男孩","example":"Its deeper origin is probably a nursery word and remains unsettled.","exampleCN":"它更早的来源可能是幼儿用词，至今没有定论。"},{"word":"El Niño","structure":"Spanish phrase","meaning":"the child","meaningCN":"那个孩子","example":"The phrase became a proper name for a warm current.","exampleCN":"这个短语成了一股暖流的专名。"},{"word":"El Niños","structure":"English plural","meaning":"more than one episode","meaningCN":"多次事件","example":"English adds a plural to count separate events.","exampleCN":"英语加复数来计数分开的事件。"},{"word":"El Niño year","structure":"English compound","meaning":"a year with the warm phase","meaningCN":"厄尔尼诺年","example":"The name becomes an adjective-like modifier.","exampleCN":"这个名称变成了类似形容词的修饰语。"},{"word":"El Niño event","structure":"English compound","meaning":"one warm episode","meaningCN":"厄尔尼诺事件","example":"The compound makes the pattern countable.","exampleCN":"这个复合词使这一格局可以被计数。"},{"word":"El Niño conditions","structure":"English compound","meaning":"the state of the warm phase","meaningCN":"厄尔尼诺状态","example":"It names a state rather than an episode.","exampleCN":"它命名一种状态而非一次事件。"},{"word":"El Niño Southern Oscillation","structure":"English term","meaning":"the coupled pattern","meaningCN":"厄尔尼诺与南方涛动","example":"The full term joins ocean and atmosphere.","exampleCN":"完整术语把海洋与大气连在一起。"}],"latinEntries":[],"derivatives":[{"word":"El Niño year","pos":"n.","zh":"本词加表示「年份」的词构成，义为「厄尔尼诺年」"},{"word":"El Niño event","pos":"n.","zh":"本词加表示「事件」的词构成，义为「厄尔尼诺事件」"},{"word":"El Niño conditions","pos":"n.","zh":"本词加表示「状态」的词构成，义为「厄尔尼诺状态」"},{"word":"El Niño warming","pos":"n.","zh":"本词加表示「增暖」的词构成，义为「厄尔尼诺增暖」"},{"word":"El Niño Southern Oscillation","pos":"n.","zh":"本词与表示「南方涛动」的词组构成的完整术语"}]}},{"word":"La Niña","ipa_uk":"/lə ˈniːnjə/","ipa_us":"/lə ˈniːnjoʊ/","definition_zh":"拉尼娜；赤道太平洋海面温度异常偏低、并改变全球天气的气候现象","definition_en":"a recurring cooling of the equatorial Pacific Ocean that alters weather patterns around the world","core_image":"澳大利亚内陆的麦田，雨后的泥地被收割机压出深色车辙，谷仓前积着一片浅水","scene":"澳大利亚内陆的麦田里，收割机在雨后的泥地里缓慢前行，谷仓前的积水映着灰云。La Niña brought the rain that turned the wheat belt green again.","sceneCN":"这里指拉尼娜带来的多雨影响（第 4 个义项：冷位相使部分地区降水增多）；句意为拉尼娜带来的雨水让小麦带重新变绿。图中可辨识物件：麦田、收割机、车辙、谷仓与积水。","pos":[{"tag":"n.","zh":"专有名词短语：指这一气候现象；可作定语修饰年份或事件"}],"collocations":[{"phrase":"a strong La Niña","zh":"强拉尼娜"},{"phrase":"a La Niña year","zh":"拉尼娜年"},{"phrase":"the onset of La Niña","zh":"拉尼娜的开始"},{"phrase":"La Niña conditions","zh":"拉尼娜状态"},{"phrase":"during La Niña","zh":"在拉尼娜期间"},{"phrase":"La Niña forecast","zh":"拉尼娜预测"},{"phrase":"the La Niña event","zh":"这次拉尼娜事件"}],"forms":[{"label":"短语原形","form":"La Niña"},{"label":"复数","form":"La Niñas"},{"label":"定语用法","form":"La Niña + 名词"},{"label":"介词短语","form":"during La Niña"},{"label":"不定冠词用法","form":"a La Niña"},{"label":"构成成分一","form":"La"},{"label":"构成成分二","form":"Niña"}],"derivatives":[{"word":"La Niña year","pos":"n.","zh":"本词加表示「年份」的词构成，义为「拉尼娜年」"},{"word":"La Niña event","pos":"n.","zh":"本词加表示「事件」的词构成，义为「拉尼娜事件」"},{"word":"La Niña conditions","pos":"n.","zh":"本词加表示「状态」的词构成，义为「拉尼娜状态」"},{"word":"La Niña phase","pos":"n.","zh":"本词加表示「位相」的词构成，义为「拉尼娜位相」"},{"word":"La Niña cooling","pos":"n.","zh":"本词加表示「变冷」的词构成，义为「拉尼娜降温」"}],"senses":[{"no":"01","title":"The climate pattern","titleCN":"拉尼娜现象","definition":"a recurring pattern in which the tropical Pacific shifts into a cool phase with worldwide effects","definitionCN":"赤道太平洋反复进入冷位相并产生全球影响的气候格局","example":"La Niña is a recurring cooling of the equatorial Pacific that reshapes weather worldwide.","exampleCN":"拉尼娜是赤道太平洋反复出现的变冷，会重塑全球天气。","why":"The cool half of a single ocean cycle needed its own name once the warm half had one.","whyCN":"同一海洋循环的冷的一半，在暖的一半有了名字之后也需要自己的名字。"},{"no":"02","title":"The cold water anomaly","titleCN":"海温异常偏低","definition":"the build-up of unusually cold surface water along the equator, especially in the central and eastern Pacific","definitionCN":"沿赤道、尤其在太平洋中部与东部积聚的异常寒冷表层水","example":"La Niña deepens the cold tongue of water along the equator.","exampleCN":"拉尼娜使沿赤道的冷水舌加深。","why":"Stronger trade winds push warm water west and pull cold water up in the east.","whyCN":"更强的信风把暖水推向西侧，并在东侧把冷水拉上来。"},{"no":"03","title":"Alternation with the warm phase","titleCN":"与暖位相的交替","definition":"the tendency of the cool phase to follow the warm one, though the handover is not automatic","definitionCN":"冷位相倾向于跟随暖位相出现，但交接并非必然","example":"La Niña often follows El Niño, though the handover is not automatic.","exampleCN":"拉尼娜常紧接厄尔尼诺出现，但交接并不自动发生。","why":"The two phases are ends of one see-saw, but the system can pause in between.","whyCN":"两个位相是同一跷跷板的两端，但系统也可以在中间停顿。"},{"no":"04","title":"Global weather effects","titleCN":"全球天气影响","definition":"the shift of rain belts that brings wetter conditions to some regions and drier ones to others","definitionCN":"雨带移动，使一些地区更湿润、另一些更干旱","example":"La Niña tends to bring wetter conditions to parts of Australia and Indonesia.","exampleCN":"拉尼娜往往给澳大利亚与印度尼西亚的部分地区带来更湿润的条件。","why":"Cool water in the east strengthens rising air in the west, and rain follows the rising air.","whyCN":"东侧的冷水加强了西侧的上升气流，降水便随上升气流而来。"},{"no":"05","title":"Atlantic hurricanes","titleCN":"大西洋飓风","definition":"the tendency of the cool phase to reduce wind shear over the Atlantic and favour more storms","definitionCN":"冷位相倾向于减弱大西洋上空的风切变，从而有利于更多风暴生成","example":"A La Niña year often raises the number of Atlantic hurricanes.","exampleCN":"拉尼娜年往往使大西洋飓风数量增加。","why":"Weaker upper winds let storm columns stay upright, and upright storms intensify.","whyCN":"上层风减弱使风暴柱得以保持直立，直立的风暴便会增强。"},{"no":"06","title":"Stronger upwelling and fisheries","titleCN":"上升流增强与渔业","definition":"the boost in nutrient-rich upwelling along eastern ocean margins, which can help fish stocks","definitionCN":"东侧大洋边缘富含营养的上升流增强，可能有利于鱼类资源","example":"La Niña strengthens upwelling off the Peruvian coast and helps the anchovy fleet.","exampleCN":"拉尼娜加强了秘鲁沿岸的上升流，对鳀鱼船队有利。","why":"The same wind that cools the surface also lifts deep water and its nutrients.","whyCN":"使表层变冷的风，同时也把深层水与其营养带上来。"},{"no":"07","title":"Drought in some regions","titleCN":"部分地区的干旱","definition":"the drier conditions that appear in other regions during the same cool phase","definitionCN":"同一冷位相期间在其他地区出现的更干旱条件","example":"La Niña has been linked to drought in the southern United States.","exampleCN":"拉尼娜被认为与美国南部的干旱有关。","why":"One displaced rain belt leaves a deficit somewhere for every surplus it creates elsewhere.","whyCN":"一条被移动的雨带在别处制造多少盈余，就在某处留下多少亏空。"},{"no":"08","title":"Monitoring and forecasting","titleCN":"监测与预测","definition":"the buoy and satellite networks that detect the cool phase and issue seasonal outlooks","definitionCN":"探测冷位相并发布季节展望的浮标与卫星网络","example":"Forecasters watch the same buoys to detect La Niña.","exampleCN":"预报员监测同一批浮标来发现拉尼娜。","why":"Both phases are read from the same instruments, so monitoring one means monitoring the other.","whyCN":"两个位相都由同一批仪器读取，因此监测其一就等于监测其二。"},{"no":"09","title":"The name itself","titleCN":"名称的来历","definition":"Spanish for the girl, chosen as the counterpart of the older phrase for the child","definitionCN":"西班牙语中表示「女孩」的说法，被选作较早的「孩子」一词的对应名称","example":"The name La Niña means the little girl.","exampleCN":"拉尼娜这个名字意为「小女孩」。","why":"A mirror name is the cheapest way to label the opposite half of a cycle.","whyCN":"给循环的另一半贴标签，最省事的办法就是取一个镜像名称。"}],"etymology":{"intro":{"en":"The name is Spanish for the girl, formed as the feminine counterpart of the older phrase for the child. The Spanish source is certain; the deeper origin of the Spanish word is not settled, and the first use of this name is dated only approximately.","cn":"这个名称在西班牙语中意为「女孩」，是较早的「孩子」说法的阴性对应形式。西班牙语来源确定；该西班牙词更早的来源尚无定论，名称首次使用的年代也只有约数。"},"items":[{"era":"SPANISH LA","en":"La is the feminine definite article, marking the phrase as the girl.","cn":"这一成分是阴性定冠词，表明短语指的是「那个女孩」。"},{"era":"SPANISH NINA","en":"Niña is the feminine form of the word for a child; its deeper origin is probably a nursery word and is not settled.","cn":"这个词是表示孩子的名词的阴性形式；更早的来源可能是幼儿用词，尚无定论。"},{"era":"A MIRROR NAME","en":"Meteorologists needed a label for the cool half of the cycle and chose the feminine counterpart of the older name.","cn":"气象学家需要给循环中冷的一半贴标签，便取了旧名的阴性对应形式。"},{"era":"LATE ENGLISH ADOPTION","en":"English took up the phrase late in the twentieth century, well after the warm phase had been named.","cn":"英语在二十世纪晚期才采用这个短语，远晚于暖位相得名。"},{"era":"ATTACHING IT TO COOLING","en":"The name was fixed to the cold phase once the seesaw between the two phases was described.","cn":"在两位相之间的跷跷板关系被描述清楚后，这个名字被固定到冷位相上。"},{"era":"THE MODERN SENSE","en":"The phrase now covers the whole coupled ocean-and-atmosphere event, not only the cold water.","cn":"这个短语如今涵盖整个海气耦合事件，而不只是冷水。"}]},"similar":{"note":{"en":"The first group shares the name or its compounds and includes its opposite phase; the second group describes cool phases in ordinary words.","cn":"第一组共享该名称或其复合形式，并包含它的相反位相；第二组用普通词语描述冷位相。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"La Niña year","ipa":"/lə ˈniːnjə jɪə/","tag":"compound","definition":"A year in which the cool phase is present.","definitionCN":"出现冷位相的年份。"},{"word":"La Niña event","ipa":"/lə ˈniːnjə ɪˈvent/","tag":"compound","definition":"One discrete episode of the cool phase.","definitionCN":"冷位相的一次独立事件。"},{"word":"La Niña conditions","ipa":"/lə ˈniːnjə kənˈdɪʃənz/","tag":"compound","definition":"The state of the ocean and air during the cool phase.","definitionCN":"冷位相期间海洋与大气的状态。"},{"word":"El Niño","ipa":"/el ˈniːnjəʊ/","tag":"opposite phase","definition":"The warm phase of the same Pacific pattern.","definitionCN":"同一太平洋格局中的暖位相。"},{"word":"La Niñas","ipa":"/lə ˈniːnjəz/","tag":"plural","definition":"More than one cool episode.","definitionCN":"不止一次的冷事件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cool phase","ipa":"/kuːl feɪz/","tag":"near meaning","definition":"The period when the tropical Pacific is unusually cool.","definitionCN":"热带太平洋异常凉爽的时期。"},{"word":"Pacific cooling","ipa":"/pəˈsɪfɪk ˈkuːlɪŋ/","tag":"near meaning","definition":"A fall in sea surface temperature across the Pacific.","definitionCN":"太平洋海表温度的下降。"},{"word":"cold anomaly","ipa":"/kəʊld əˈnɒməli/","tag":"near meaning","definition":"A patch of water colder than the long-term average.","definitionCN":"比长期平均更冷的一片水域。"},{"word":"upwelling phase","ipa":"/ʌpˈwelɪŋ feɪz/","tag":"near meaning","definition":"A period when deep water rises strongly to the surface.","definitionCN":"深层水强烈上升到表层的时期。"},{"word":"seasonal outlook","ipa":"/ˈsiːzənl ˈaʊtlʊk/","tag":"near meaning","definition":"A forecast for the coming season.","definitionCN":"对未来一季的预测。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow cold water rising in the east and rain moving west; abstract ones treat the name as a mirror turned on an earlier story.","cn":"正常联想跟随东侧冷水上涌、降水向西移动；抽象联想把这个名称看作照向早先故事的一面镜子。"},"normal":[{"en":"Stronger trade winds push warm water west and lift cold water east.","cn":"更强的信风把暖水推向西侧，并在东侧抬起冷水。"},{"en":"Cold water in the east means rising air in the west, and rain there.","cn":"东侧冷水意味着西侧空气上升，降水便落在那里。"},{"en":"Weak upper winds over the Atlantic let hurricanes stand up straight.","cn":"大西洋上空弱的上层风让飓风直立起来。"},{"en":"The same wind that cools the surface lifts nutrients from below.","cn":"使表层变冷的风，也从下方带起营养。"},{"en":"The name is simply the girl, mirroring the earlier child.","cn":"这个名字只是「女孩」，镜像了早先的「孩子」。"}],"abstract":[{"en":"One cycle has two halves, so one name inevitably produces its mirror.","cn":"一个循环有两半，一个名字必然生出它的镜像。"},{"en":"Cold water is not the absence of the warm phase but its partner.","cn":"冷水不是暖位相的缺席，而是它的搭档。"},{"en":"The same wind that removes heat from one coast delivers food to another.","cn":"同一阵风从一处海岸带走热量，却在另一处送来食物。"}]},"examples":[{"en":"Forecasters declared a La Niña after the equatorial Pacific cooled for a third month.","cn":"在赤道太平洋连续三个月变冷之后，预报员宣布拉尼娜形成。"},{"en":"The wet winter was attributed to a moderate La Niña.","cn":"这个多雨的冬季被归因于一次中等强度的拉尼娜。"},{"en":"Insurance models now include La Niña scenarios.","cn":"保险模型如今把拉尼娜情景纳入考虑。"}],"dict_mnemonic":{"note":"词源记忆 · 非词源","text":"西班牙语里意为「女孩」，作为「孩子」的对应名称：拉尼娜","word":"La Niña"},"root":"西班牙语短语，字面意为「那个女孩」，是较早的「那个孩子」说法的阴性对应形式，二十世纪晚期被气象学采用来指太平洋冷位相。西班牙语来源确定；该词更早的来源尚无定论，术语首见年代为约数。","sensesIntro":{"en":"Nine senses move from the named cool pattern to its cold water, its alternation, its rains, its hurricanes, its upwelling, its droughts, its forecasts and the mirror name.","cn":"九个义项从这一冷位相格局出发，走向冷水、交替、降雨、飓风、上升流、干旱、预测，以及那个镜像名称。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wheat field cut by wheel ruts after rain, with water in front of the barn.","cn":"核心意象：雨后麦田里的车辙，谷仓前的一汪积水。"},"chain":["THE PATTERN","COLD WATER EAST","THE SEESAW","RAIN AND STORMS","UPWELLING AND DROUGHT","WATCHING AND NAMING"],"branches":[{"senses":"01 · 02","en":"THE CORE: a named cool phase and the cold tongue along the equator.","cn":"核心：被命名的冷位相，以及沿赤道的冷水舌。"},{"senses":"03","en":"THE SEESAW: the cool half following the warm half, without a fixed handover.","cn":"跷跷板：冷的一半跟随暖的一半，但没有固定的交接。"},{"senses":"04 · 05","en":"THE WEATHER: wetter belts in some places and more Atlantic storms.","cn":"天气：一些地区更湿润，大西洋风暴更多。"},{"senses":"06 · 07","en":"THE OCEAN'S TWO FACES: stronger upwelling for fish, drier ground elsewhere.","cn":"海洋的两张面孔：上升流增强利于鱼群，别处地面更干。"},{"senses":"08 · 09","en":"THE WATCHERS AND THE NAME: the same buoys, and the girl who mirrors the child.","cn":"观察者与名称：同一批浮标，以及镜像「孩子」的「女孩」。"}]},"affixes":{"intro":{"en":"The phrase is a Spanish article plus a Spanish noun, so it has no English affixes; its parts are two whole words.","cn":"这个短语是一个西班牙语定冠词加一个西班牙语名词，因此没有英语词缀；其组成是两个完整的词。"},"latinIntro":{"en":"Spanish supplies both words: the feminine article and the feminine word for a child. No Latin noun stands behind the phrase, so the Latin entry list is left empty.","cn":"两个词都来自西班牙语：阴性定冠词与表示孩子的阴性名词。短语背后没有拉丁名词，因此拉丁词条列表留空。"},"items":[{"word":"la","structure":"Spanish article","meaning":"the, feminine","meaningCN":"这个（阴性定冠词）","example":"It marks the phrase as the girl rather than any girl.","exampleCN":"它表明短语指的是特定的那个女孩。"},{"word":"niña","structure":"Spanish noun","meaning":"girl","meaningCN":"女孩","example":"It is the feminine counterpart of the word for a boy.","exampleCN":"它是表示男孩的名词的阴性对应形式。"},{"word":"La Niña","structure":"Spanish phrase","meaning":"the girl","meaningCN":"那个女孩","example":"The phrase became a proper name for a cool phase.","exampleCN":"这个短语成了冷位相的专名。"},{"word":"La Niñas","structure":"English plural","meaning":"more than one episode","meaningCN":"多次事件","example":"English adds a plural to count separate events.","exampleCN":"英语加复数来计数分开的事件。"},{"word":"La Niña year","structure":"English compound","meaning":"a year with the cool phase","meaningCN":"拉尼娜年","example":"The name becomes an adjective-like modifier.","exampleCN":"这个名称变成了类似形容词的修饰语。"},{"word":"La Niña event","structure":"English compound","meaning":"one cool episode","meaningCN":"拉尼娜事件","example":"The compound makes the pattern countable.","exampleCN":"这个复合词使这一格局可以被计数。"},{"word":"La Niña phase","structure":"English compound","meaning":"the cool half of the cycle","meaningCN":"拉尼娜位相","example":"It names a phase rather than an event.","exampleCN":"它命名一个位相而非一次事件。"},{"word":"La Niña conditions","structure":"English compound","meaning":"the state of the cool phase","meaningCN":"拉尼娜状态","example":"It names a state rather than an episode.","exampleCN":"它命名一种状态而非一次事件。"}],"latinEntries":[],"derivatives":[{"word":"La Niña year","pos":"n.","zh":"本词加表示「年份」的词构成，义为「拉尼娜年」"},{"word":"La Niña event","pos":"n.","zh":"本词加表示「事件」的词构成，义为「拉尼娜事件」"},{"word":"La Niña conditions","pos":"n.","zh":"本词加表示「状态」的词构成，义为「拉尼娜状态」"},{"word":"La Niña phase","pos":"n.","zh":"本词加表示「位相」的词构成，义为「拉尼娜位相」"},{"word":"La Niña cooling","pos":"n.","zh":"本词加表示「变冷」的词构成，义为「拉尼娜降温」"}]}},{"word":"temperature fluctuation","ipa_uk":"/ˈtemprətʃə ˌflʌktʃuˈeɪʃən/","ipa_us":"/ˈtemprətʃər ˌflʌktʃuˈeɪʃən/","definition_zh":"温度波动；温度在某段时间内围绕基准值上下起伏的现象","definition_en":"the rise and fall of temperature around a baseline over a period of time","core_image":"恒温箱的记录纸上，一条锯齿线始终围着平直的基准线上下抖动","scene":"实验室的恒温箱前，技术员盯着记录纸上的锯齿线，那条线始终围着一条平直的基准线上下抖动。The chart showed a small temperature fluctuation around the set point.","sceneCN":"这里指受控设备中围绕设定值的温度波动（第 5 个义项：恒温系统内的温度起伏）；句意为记录图显示设定点附近有小幅温度波动。图中可辨识物件：恒温箱、记录纸、锯齿曲线、基准线。","pos":[{"tag":"n.","zh":"名词短语：可数，指一次或一段温度起伏；常带表示幅度的介词短语"}],"collocations":[{"phrase":"a slight temperature fluctuation","zh":"轻微的温度波动"},{"phrase":"diurnal temperature fluctuation","zh":"昼夜温度波动"},{"phrase":"seasonal temperature fluctuation","zh":"季节温度波动"},{"phrase":"a temperature fluctuation of two degrees","zh":"两度的温度波动"},{"phrase":"measure temperature fluctuation","zh":"测量温度波动"},{"phrase":"temperature fluctuation range","zh":"温度波动范围"},{"phrase":"large temperature fluctuation","zh":"大幅度温度波动"}],"forms":[{"label":"短语原形","form":"temperature fluctuation"},{"label":"复数","form":"temperature fluctuations"},{"label":"定语用法","form":"temperature fluctuation + 名词"},{"label":"介词短语","form":"a fluctuation in temperature"},{"label":"构成成分一","form":"temperature"},{"label":"构成成分二","form":"fluctuation"}],"derivatives":[{"word":"temperature","pos":"n.","zh":"由拉丁语表示「调和、适度」的动词派生，义为「温度」"},{"word":"fluctuate","pos":"v.","zh":"由拉丁语表示「波动」的动词构成，义为「起伏；波动」"},{"word":"fluctuation","pos":"n.","zh":"由动词加表示「作用、过程」的词尾构成，义为「波动」"},{"word":"fluctuating","pos":"adj.","zh":"由动词加形容词词尾构成，义为「起伏不定的」"},{"word":"temperate","pos":"adj.","zh":"与本短语第一成分同源，义为「温和的；温带的」"}],"senses":[{"no":"01","title":"Rise and fall around a baseline","titleCN":"围绕基准值的起伏","definition":"the general movement of temperature up and down rather than in one direction","definitionCN":"温度上下往复而非单向变化的总体运动","example":"A temperature fluctuation of two degrees was enough to change the reaction rate.","exampleCN":"两度的温度波动就足以改变反应速率。","why":"Change can be directional or oscillating, and this phrase names the oscillating kind.","whyCN":"变化可以是单向的，也可以是往复的，这个短语命名的是往复的那一类。"},{"no":"02","title":"Short-term wobble versus trend","titleCN":"短期起伏与长期趋势","definition":"a brief departure from the average that carries little information about the long run","definitionCN":"对平均值的短暂偏离，对长期走势几乎不提供信息","example":"A single temperature fluctuation says little about a long-term trend.","exampleCN":"单次温度波动对长期趋势说明不了什么。","why":"Mixing up a wiggle with a slope is one of the commonest mistakes in reading data.","whyCN":"把一次抖动当成一段斜坡，是读数据时最常见的错误之一。"},{"no":"03","title":"Diurnal fluctuation","titleCN":"昼夜温度波动","definition":"the daily cycle of warming by day and cooling by night","definitionCN":"白天升温、夜间降温的每日循环","example":"Diurnal temperature fluctuation is largest under clear skies and dry air.","exampleCN":"晴朗干燥的空气下，昼夜温度波动最大。","why":"Sunlight arrives and leaves on a schedule, so the temperature follows a daily rhythm.","whyCN":"阳光按时间表到来与离开，温度便随之有每日的节律。"},{"no":"04","title":"Seasonal fluctuation","titleCN":"季节温度波动","definition":"the yearly swing between warm and cold seasons","definitionCN":"一年之中暖季与冷季之间的摆动","example":"Seasonal temperature fluctuation drives the timing of migration.","exampleCN":"季节温度波动决定迁徙的时间。","why":"The planet's tilt imposes a yearly wave, and living things read that wave as a calendar.","whyCN":"行星的倾斜造成一年的波，生物把这列波读成日历。"},{"no":"05","title":"Fluctuation in a controlled system","titleCN":"受控系统中的温度波动","definition":"the small deviation from a set point inside an oven, incubator or reactor","definitionCN":"烤箱、培养箱或反应器内偏离设定值的小幅偏差","example":"The incubator keeps temperature fluctuation below a tenth of a degree.","exampleCN":"这台培养箱把温度波动控制在十分之一度以内。","why":"Control engineering cares about the size of the wiggle, not the average alone.","whyCN":"控制工程关心抖动的幅度，而不只是平均值。"},{"no":"06","title":"Fluctuation in climate records","titleCN":"气候记录中的温度波动","definition":"a multi-year or multi-century rise and fall recovered from proxies and instruments","definitionCN":"从代用资料与仪器中复原的多年或数百年尺度的升降","example":"Proxy records reveal a temperature fluctuation that lasted several centuries.","exampleCN":"代用资料揭示了一次持续数百年的温度波动。","why":"Past climates are read as waves, so the phrase describes the shape rather than a single value.","whyCN":"过去的气候被读成波，因此这个短语描述的是形状而非单个数值。"},{"no":"07","title":"Statistical fluctuation","titleCN":"统计涨落","definition":"variation that comes from random sampling rather than from a real physical change","definitionCN":"源于随机抽样而非真实物理变化的变化","example":"Some of the variation is just statistical temperature fluctuation, not a real signal.","exampleCN":"其中一部分变化只是统计上的温度涨落，并非真实信号。","why":"Randomness alone can produce wiggles, so a signal has to rise above the noise.","whyCN":"随机性本身就能制造抖动，因此信号必须高出噪声。"},{"no":"08","title":"Body temperature fluctuation","titleCN":"体温波动","definition":"the normal or abnormal daily variation in the temperature of a living body","definitionCN":"活体温度的正常或异常日常变化","example":"A temperature fluctuation of half a degree can signal an infection.","exampleCN":"半度的体温波动就可能提示感染。","why":"Physiology uses a narrow band, so even a small wiggle becomes clinically meaningful.","whyCN":"生理学的带宽很窄，因此即使很小的抖动也具有临床意义。"},{"no":"09","title":"Ocean temperature fluctuation","titleCN":"海温波动","definition":"the rise and fall of sea surface temperature that buoys and satellites track","definitionCN":"浮标与卫星所追踪的海表温度升降","example":"Ocean temperature fluctuation on the equator is what the buoys are built to track.","exampleCN":"赤道上的海温波动正是这些浮标被造出来追踪的对象。","why":"The ocean stores and releases heat slowly, so its wiggles run on longer periods than air.","whyCN":"海洋缓慢地储存与释放热量，因此它的波动周期比空气更长。"}],"etymology":{"intro":{"en":"The phrase joins a Latin noun for a moderate mixture with a Latin noun for wave motion. Both roots are well documented; the phrase itself was assembled in scientific writing, so its first appearance is dated only approximately.","cn":"这个短语把一个表示「适度调和」的拉丁名词，与一个表示波浪运动的拉丁名词组合起来。两个词根来源有据；短语本身是在科学写作中组合而成的，首次出现只有约数。"},"items":[{"era":"LATIN TEMPERARE","en":"Temperare meant to mix in due proportion or to moderate.","cn":"这个动词表示按适当比例混合或使之适度。"},{"era":"LATIN TEMPERATURA","en":"The noun named a balanced mixture and later the moderate state of the air.","cn":"这个名词指调和的比例，后指空气的适中状态。"},{"era":"ENGLISH TEMPERATURE","en":"English shifted the noun from balance to the degree of heat measured by a scale.","cn":"英语把这个名词从「平衡」转到用刻度测量的热度。"},{"era":"LATIN FLUCTUS","en":"Fluctus meant a wave on water, from the verb for flowing.","cn":"这个词表示水面上的波浪，来自表示「流动」的动词。"},{"era":"LATIN FLUCTUARE","en":"The verb meant to move like a wave, to rise and fall, to waver.","cn":"这个动词表示像波浪一样运动、上下起伏、摇摆。"},{"era":"THE MODERN PHRASE","en":"Scientific writing joined the two nouns to name heat that will not hold still.","cn":"科学写作把两个名词连在一起，命名不肯静止的热度。"}]},"similar":{"note":{"en":"The first group shares the word temperature but names different features of it; the second group names other kinds of up-and-down movement.","cn":"第一组共享「温度」一词但指它的不同特征；第二组指其他上下起伏的运动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"temperature gradient","ipa":"/ˈtemprətʃə ˈɡreɪdiənt/","tag":"same first word","definition":"The rate at which temperature changes with distance.","definitionCN":"温度随距离变化的速率。"},{"word":"temperature inversion","ipa":"/ˈtemprətʃə ɪnˈvɜːʃən/","tag":"same first word","definition":"A layer where temperature rises with height instead of falling.","definitionCN":"温度随高度上升而非下降的一层大气。"},{"word":"temperature anomaly","ipa":"/ˈtemprətʃə əˈnɒməli/","tag":"same first word","definition":"The departure of temperature from a long-term average.","definitionCN":"温度对长期平均值的偏离。"},{"word":"temperature range","ipa":"/ˈtemprətʃə reɪndʒ/","tag":"same first word","definition":"The span between the highest and lowest values.","definitionCN":"最高值与最低值之间的跨度。"},{"word":"temperature sensor","ipa":"/ˈtemprətʃə ˈsensə/","tag":"same first word","definition":"A device that converts heat into a reading.","definitionCN":"把热量转换为读数的装置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"variation","ipa":"/ˌværiˈeɪʃən/","tag":"near meaning","definition":"A change in amount or level.","definitionCN":"数量或水平的变化。"},{"word":"oscillation","ipa":"/ˌɒsɪˈleɪʃən/","tag":"near meaning","definition":"A regular back-and-forth movement.","definitionCN":"有规律的往复运动。"},{"word":"swing","ipa":"/swɪŋ/","tag":"near meaning","definition":"A large movement from one extreme to the other.","definitionCN":"从一个极端到另一端的大幅移动。"},{"word":"deviation","ipa":"/ˌdiːviˈeɪʃən/","tag":"near meaning","definition":"A departure from a standard or expected value.","definitionCN":"对标准或预期值的偏离。"},{"word":"noise","ipa":"/nɔɪz/","tag":"near meaning","definition":"Random variation that obscures a signal.","definitionCN":"掩盖信号的随机变化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow one line on a chart as it wiggle around a straight reference; abstract ones treat fluctuation as information that must be separated from trend and noise.","cn":"正常联想跟随图上一条围着直线抖动的曲线；抽象联想把波动看作必须与趋势、噪声分开的信息。"},"normal":[{"en":"A recorder draws a sawtooth around a straight set line.","cn":"记录仪在平直的设定线周围画出锯齿。"},{"en":"At dawn the line climbs, at night it falls, and that is the daily wiggle.","cn":"黎明曲线上升，夜里下降，那就是每日的抖动。"},{"en":"A summer and winter swing is just the same wiggle at a slower tempo.","cn":"夏冬之间的摆动只是同一抖动放慢了节奏。"},{"en":"A good oven keeps its wiggle smaller than a tenth of a degree.","cn":"好的烤箱把抖动控制在十分之一度以内。"},{"en":"Buoys watch the same wiggle on the surface of the ocean.","cn":"浮标在海洋表面观察同一种抖动。"}],"abstract":[{"en":"Fluctuation is a wave in a number, not necessarily a wave in the world.","cn":"波动是数字里的波，未必是世界里的波。"},{"en":"Before calling a wiggle a trend, ask how long the record is.","cn":"把抖动称为趋势之前，先问记录有多长。"},{"en":"Every measurement carries a small tremble that belongs to the instrument, not the object.","cn":"每个测量都带着一点颤抖，那属于仪器而不属于对象。"}]},"examples":[{"en":"The reactor is designed to tolerate a small temperature fluctuation.","cn":"该反应堆被设计成能承受小幅温度波动。"},{"en":"Scientists separated the long-term trend from yearly temperature fluctuation.","cn":"科学家把长期趋势与逐年温度波动分开。"},{"en":"A sudden temperature fluctuation cracked the glass.","cn":"一次突然的温度波动使玻璃裂了。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"temperature（温度）+ fluctuation（波动）——温度的上下起伏，即温度波动","word":"temperature fluctuation"},"root":"由 temperature 与 fluctuation 组合。前者源自拉丁语 temperatura「调和的比例」，出自 temperare「调和、使适度」；后者源自拉丁语 fluctus「波浪」及其动词 fluctuare「起伏摇摆」，与表示「流动」的词根相关。短语在科学写作中组合而成，确切首见年代不确定。","sensesIntro":{"en":"Nine senses take one wiggle and read it at different scales: around a baseline, against a trend, across a day, a season, a machine, a century, a sample, a body and an ocean.","cn":"九个义项拿同一次抖动在不同尺度上解读：围绕基准、对照趋势、跨一天、跨一季、在一台设备里、跨一个世纪、在一个样本里、在一具身体里与在一片海洋上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sawtooth line hugging a straight reference line on recorder paper.","cn":"核心意象：记录纸上贴着直线基准的锯齿曲线。"},"chain":["THE BASELINE WIGGLE","TREND VERSUS WOBBLE","DAILY AND YEARLY","CONTROLLED BOXES","RECORDS AND SAMPLES","BODY AND OCEAN"],"branches":[{"senses":"01 · 02","en":"THE CORE: up-and-down motion, and the warning not to mistake it for a slope.","cn":"核心：上下往复的运动，以及不要把它误认成斜坡的提醒。"},{"senses":"03 · 04","en":"THE CALENDAR SCALES: one turn of the earth and one turn of the year.","cn":"日历尺度：地球自转一圈与一年一圈。"},{"senses":"05","en":"THE MACHINE: a set point and the small deviation allowed around it.","cn":"机器：一个设定点，以及允许其周围的小偏差。"},{"senses":"06 · 07","en":"THE LONG RECORD AND THE SAMPLE: centuries recovered from proxies, and randomness inside a measurement.","cn":"长记录与样本：从代用资料复原的数百年，以及测量内部的随机性。"},{"senses":"08 · 09","en":"THE TWO BODIES: a narrow physiological band and the slow heat of the sea.","cn":"两个躯体：狭窄的生理带宽与海洋缓慢的热量。"}]},"affixes":{"intro":{"en":"Two Latin roots, one of moderation and one of waves, supply both halves of the phrase.","cn":"两个拉丁词根，一个表示「调和」，一个表示「波浪」，提供了短语的两半。"},"latinIntro":{"en":"Latin supplies temperare and its noun for balanced heat, then fluctus and its verb for wave motion; English adds the noun endings.","cn":"拉丁语提供了表示调和及其名词，以及表示波浪的名词与动词；英语加上名词词尾。"},"items":[{"word":"temperare","structure":"Latin verb","meaning":"to mix, to moderate","meaningCN":"调和；使适度","example":"The idea of balance is older than the idea of heat.","exampleCN":"「平衡」的观念比「热度」的观念更古老。"},{"word":"temperatura","structure":"Latin noun","meaning":"due mixture, moderate state","meaningCN":"调和的比例；适中状态","example":"The noun moved from mixture to the state of the air.","exampleCN":"这个名词从「混合比例」转到空气的状态。"},{"word":"-ature","structure":"Latin noun suffix","meaning":"result of an action","meaningCN":"动作的结果","example":"It forms the English noun for the measured state.","exampleCN":"它构成表示被测状态的英语名词。"},{"word":"fluctus","structure":"Latin noun","meaning":"wave","meaningCN":"波浪","example":"It is the root of all the wave words in the phrase.","exampleCN":"它是短语中所有「波」类词的根。"},{"word":"fluctuare","structure":"Latin verb","meaning":"to rise and fall","meaningCN":"上下起伏","example":"The verb describes motion that will not settle.","exampleCN":"这个动词描述不肯安定下来的运动。"},{"word":"-ation","structure":"Latin noun suffix","meaning":"action or process","meaningCN":"动作或过程","example":"It turns the verb into the name of the movement.","exampleCN":"它把动词变成该运动的名称。"},{"word":"temperature","structure":"English noun","meaning":"degree of heat","meaningCN":"温度","example":"The first half of the phrase names what is moving.","exampleCN":"短语的前半命名了在动的东西。"},{"word":"fluctuation","structure":"English noun","meaning":"up-and-down change","meaningCN":"波动","example":"The second half names how it moves.","exampleCN":"短语的后半命名了它如何动。"}],"latinEntries":[{"word":"temperare","structure":"Latin verb","meaning":"to moderate","meaningCN":"使适度"},{"word":"temperatura","structure":"Latin noun","meaning":"due mixture","meaningCN":"调和的比例"},{"word":"fluctus","structure":"Latin noun","meaning":"wave","meaningCN":"波浪"},{"word":"fluctuare","structure":"Latin verb","meaning":"to rise and fall","meaningCN":"上下起伏"}],"derivatives":[{"word":"temperature","pos":"n.","zh":"由拉丁语表示「调和、适度」的动词派生，义为「温度」"},{"word":"fluctuate","pos":"v.","zh":"由拉丁语表示「波动」的动词构成，义为「起伏；波动」"},{"word":"fluctuation","pos":"n.","zh":"由动词加表示「作用、过程」的词尾构成，义为「波动」"},{"word":"fluctuating","pos":"adj.","zh":"由动词加形容词词尾构成，义为「起伏不定的」"},{"word":"temperate","pos":"adj.","zh":"与本短语第一成分同源，义为「温和的；温带的」"}]}}]);
